insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.2', '["**What it measures.** Whether each use of AI has a named person answerable for what it does, with the authority to change or stop it, and a known route for taking concerns upward.","**Why it matters.** The supplier assumes the customer governs use, IT assumes the business owns the outcome, and the business assumes someone senior approved it. A person wrongly refused, flagged or dismissed then finds nobody who can put it right.","**The UK position.** The government''s cross-sector principle, which is not statute and is applied by existing regulators, reads: \"Governance measures should be in place to ensure effective oversight of the supply and use of AI systems, with clear lines of accountability established across the AI life cycle.\" No general law requires a named owner for AI. Financial services comes closest. The Financial Conduct Authority says that in larger firms any use of AI falls within an existing senior manager''s responsibilities; most respondents to the regulators'' 2022 discussion paper opposed a separate responsibility for AI. The Prudential Regulation Authority expects banks with internal model approval to name an accountable senior manager for model risk. Government guidance tells departments to nominate a senior responsible owner for each AI project.","**What good looks like.** For each system, a written allocation: who is accountable, who operates it, who is consulted before change, where escalation goes. Escalations are logged and reviewed.","**Reading the answer.** Ask who could switch a given system off today. A committee is not an owner.","**A defensible figure.** The National Audit Office found that 24 of the 32 government bodies with deployed AI said their use cases always or usually had a named accountable owner (March 2024, paragraph 1.10)."]'::jsonb, false, '[{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Principle: Accountability and governance, \"Definition and explanation\"","access":"free"},{"title":"AI Update","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/publication/corporate/ai-update.pdf","locator":"Paras 3.38-3.41, p.16-17","access":"free"},{"title":"FS2/23: Artificial Intelligence and Machine Learning (feedback statement)","publisher":"Bank of England, Prudential Regulation Authority and Financial Conduct Authority","year":2023,"url":"https://www.bankofengland.co.uk/prudential-regulation/publication/2023/october/artificial-intelligence-and-machine-learning","locator":"Paras 4.16-4.19 (questions 12 to 14); summary of key points","access":"free"},{"title":"Supervisory Statement SS1/23: Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.2 (SMF accountability for model risk management framework), PDF p.14-15","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Section on accountability and responsibility (practical recommendations)","access":"free"},{"title":"Use of artificial intelligence in government (HC 612)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Summary para 11, p.8; para 1.10, p.20","access":"free"},{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Art. 22A(1)(a) and (2); note F1","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): What does the UK GDPR say about ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-does-the-uk-gdpr-say-about-adm/","locator":"Section on what meaningful human involvement means (criteria list)","access":"free"},{"title":"OECD AI Principles: Accountability (Principle 1.5)","publisher":"Organisation for Economic Co-operation and Development","year":2019,"url":"https://oecd.ai/en/dashboards/ai-principles/P9","locator":"Principle 1.5 (Accountability), text of the principle","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(2)","access":"free"},{"title":"Financial Services and Markets Act 2000, section 66A: Misconduct: action by the FCA","publisher":"legislation.gov.uk","year":2000,"url":"https://www.legislation.gov.uk/ukpga/2000/8/section/66A","locator":"s.66A(5) (Condition C), paragraphs (c) and (d)","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Executive summary, ''Governance and accountability''; section 3.1 (Governance and accountability), ''Accountability''","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"''How should we approach AI governance and risk management?'', second and third paragraphs","access":"free"},{"title":"Three lines of defense against risks from AI","publisher":"Jonas Schuett (arXiv; published in AI & Society)","year":2022,"url":"https://arxiv.org/abs/2212.08364","locator":"Abstract","access":"free"},{"title":"Putting AI Ethics into Practice: The Hourglass Model of Organizational AI Governance","publisher":"Matti Mäntymäki, Matti Minkkinen, Teemu Birkstedt and Mika Viljanen (arXiv)","year":2023,"url":"https://arxiv.org/pdf/2206.00335v2","locator":"Section on the AI system layer, component F ''Accountability and ownership'' (tasks T54-T56), PDF p.9","access":"free"}]'::jsonb, '2026-10-02')
