insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.3', '["**What it measures.** Whether there is a small set of approved, current policies: what AI may be used for, which tools staff may use with what data, and what happens when something goes wrong.","**Why it matters.** Without a rule, each employee decides alone what to put into a tool and how far to trust what comes out. Customers'' and colleagues'' information goes where nobody agreed it should, and people are affected by outputs nobody checked.","**The UK position.** No UK law requires an AI policy by name. Data protection law requires appropriate data protection policies where proportionate (UK GDPR, Article 24). The UK Corporate Governance Code asks listed company boards to ensure the necessary policies are in place. The Prudential Regulation Authority expects banks'' model risk policies to be board-approved and reviewed regularly. The Financial Reporting Council has said: \"It is important that there are clear policies and procedures that are embedded across all levels of the organisation.\" The government''s draft self-assessment tool asks whether an AI policy exists, is accessible to all employees and is reviewed. In government-commissioned interviews, very few businesses had one.","**What good looks like.** A board-approved set covering use, escalation and exceptions; a named owner for each; review triggered by changes in law or operations; adherence measured.","**Reading the answer.** Ask a member of staff which tools they may use and what must never go into one. A guess means the policy is unread. The UK''s automated decision rules changed on 5 February 2026; an older policy is out of date.","**A defensible figure.** Eleven of 100 listed companies sampled reported having an AI policy or reviewing their code of conduct to cover AI (Financial Reporting Council, November 2025, page 45)."]'::jsonb, false, '[{"title":"UK GDPR, Article 24: Responsibility of the controller","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/24","locator":"Art. 24(1) and (2)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Principle A, p.6; Principle I, p.8","access":"free"},{"title":"Annual Review of Corporate Governance Reporting","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/8893/Annual_Review_of_Corporate_Governance_Reporting_2025.pdf","locator":"p.45 (AI policy and reporting; closing paragraph of the AI section); sample on p.5","access":"free"},{"title":"Supervisory Statement SS1/23: Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.3 (Policies and procedures), points (a)-(c), PDF p.15-16","access":"free"},{"title":"AI Management Essentials tool (consultation version, accessible)","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/consultations/ai-management-essentials-tool/ai-management-essentials-tool-accessible","locator":"Section 2 (AI policy), questions 2.1-2.5","access":"free"},{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Note F1 (commencement); Art. 22A(1)","access":"free"},{"title":"AI Adoption Research","publisher":"Department for Science, Innovation and Technology (IFF Research and Technopolis Group)","year":2026,"url":"https://www.gov.uk/government/publications/ai-adoption-research/ai-adoption-research","locator":"Chapter 6 (Perceptions of trust and safety in AI), \"Using AI responsibly\"","access":"free"},{"title":"The Wates Corporate Governance Principles for Large Private Companies","publisher":"Financial Reporting Council","year":2018,"url":"https://media.frc.org.uk/documents/The_Wates_Corporate_Governance_Principles_for_Large_Private_Companies.pdf","locator":"Principle Three (Director responsibilities), guidance on accountability, p.15","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"GOVERN 1 and GOVERN 1.1, Table 1, p.22","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, as amended (passages marked AMENDED and NEW)","access":"free"},{"title":"R (Ayinde) v London Borough of Haringey; Al-Haroun v Qatar National Bank QPSC [2025] EWHC 1383 (Admin)","publisher":"High Court of Justice, King''s Bench Division, Divisional Court (The National Archives, Find Case Law)","year":2025,"url":"https://caselaw.nationalarchives.gov.uk/ewhc/admin/2025/1383","locator":"Para 9 (Dame Victoria Sharp P)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 17: Quality management system","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-17","locator":"Art. 17(1), opening words and point (m)","access":"free"},{"title":"Data protection audit framework, Accountability toolkit: Policies and procedures","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/accountability/policies-and-procedures/","locator":"Second control measure (review and approval process), list ''Ways to meet our expectations''; first control measure, ''Options to consider''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile, NIST AI 600-1","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf","locator":"Suggested action GV-1.4-002 (under GOVERN 1.4), printed p.15 (PDF p.19); see also GV-3.2-003 and GV-6.1-010","access":"free"},{"title":"Principles alone cannot guarantee ethical AI","publisher":"Brent Mittelstadt (arXiv; published in Nature Machine Intelligence)","year":2019,"url":"https://arxiv.org/abs/1906.06668","locator":"Abstract","access":"free"},{"title":"The Ethics of AI Ethics: An Evaluation of Guidelines","publisher":"Thilo Hagendorff (arXiv; published in Minds and Machines)","year":2020,"url":"https://arxiv.org/pdf/1903.03425v2","locator":"Section 3.3 (Ethics in practice), PDF p.6","access":"free"}]'::jsonb, '2026-10-02')
