insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.7', '["**What it measures.** Whether anyone outside the team that runs AI governance checks that it works: a review that is scoped, scheduled, carried out by someone free to disagree, and followed through.","**Why it matters.** People affected by AI decisions cannot inspect the controls behind them. They rely on someone independent having looked. Government research with the public found: \"Participants felt that, if assurance were delivered only by an AI developer that is profit motivated, it would not be trustworthy.\" Self-review tells a board what the organisation believes, not whether it is right.","**The UK position.** No general law requires an independent audit of AI governance. The Corporate Governance Code expects a listed company''s audit committee to review internal audit and, where there is none, to explain how internal assurance is achieved. The Information Commission (ICO) can require an organisation to permit an assessment of its data protection compliance. Government''s 2025 review, though, found the quality of AI assurance services unclear and the standards still developing.","**What good looks like.** Review scoped by risk, starting with systems that decide about people; a reviewer independent of those who built or run the system; findings given an owner and a date, and tracked to closure; results reported to the board. Internal audit standards require an external assessment of the audit function itself at least once every five years.","**Reading the answer.** A certificate is evidence only if someone can say what it covered. The internal auditors'' own AI framework warns that internal audit is likely to give only limited assurance on AI.","**A defensible figure.** In November 2024 the government estimated that 524 firms supplied AI assurance goods and services in the UK, 84 of them specialised."]'::jsonb, false, '[{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Provisions 25 and 26 (pages 12-13 of the document); Provision 29","access":"free"},{"title":"Introduction to AI assurance","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/introduction-to-ai-assurance/introduction-to-ai-assurance","locator":"Section on roles in the assurance ecosystem (accreditation bodies; UKAS); sections 5.2 (assurance spectrum), 5.6 (bias audit), 5.7 (compliance audit), 5.8 (conformity assessment)","access":"free"},{"title":"Assuring a responsible future for AI","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/assuring-a-responsible-future-for-ai/assuring-a-responsible-future-for-ai","locator":"Executive summary (''Our research has found''); section ''Opportunities for future market growth'' (supply; public research finding)","access":"free"},{"title":"Trusted third-party AI assurance roadmap","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/trusted-third-party-ai-assurance-roadmap/trusted-third-party-ai-assurance-roadmap","locator":"Section ''Challenges for a trusted third-party assurance market'' (Quality; Skills; Information access); ''Government actions'' (professionalisation)","access":"free"},{"title":"Portfolio of AI assurance techniques","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/guidance/portfolio-of-ai-assurance-techniques","locator":"Sections ''About the portfolio'' and ''Assurance techniques''","access":"free"},{"title":"Global Internal Audit Standards","publisher":"The Institute of Internal Auditors","year":2024,"url":"https://www.theiia.org/globalassets/site/standards/editable-versions/globalinternalauditstandards_2024january9_editable.pdf","locator":"Principle 7 (''Positioned Independently''); Standard 8.4 (''External Quality Assessment''); Glossary, ''independence''","access":"free"},{"title":"The IIA''s Artificial Intelligence Auditing Framework","publisher":"The Institute of Internal Auditors","year":2024,"url":"https://www.theiia.org/globalassets/site/content/tools/professional/aiframework-sept-2024-update2.pdf","locator":"Part 3 (''AI Auditing Framework''), opening section and ''Governance'' (document page 11-12); Part 2 (right to audit clause for vendors, page 10)","access":"free"},{"title":"ISO/IEC 42001 - AI Management System","publisher":"BSI Group","year":2026,"url":"https://www.bsigroup.com/en-GB/products-and-services/standards/iso-42001-ai-management-system/","locator":"Introductory section and FAQs (''What is BSI’s experience in auditing AI Management Systems?'')","access":"free"},{"title":"Data Protection Act 2018, section 146: Assessment notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/146","locator":"s.146(1) and (2)","access":"free"},{"title":"Data protection audit framework","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/","locator":"Introductory text; under-review banner; link to the artificial intelligence toolkit","access":"free"},{"title":"SS1/23: Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 4 (''Independent model validation'') and Principle 4.1 (the independent validation function); Principle 2.5 (Internal Audit); para 1.5 (in effect 17 May 2024)","access":"free"},{"title":"AI Act, Article 43: Conformity assessment (AI Act Service Desk copy)","publisher":"European Commission","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-43","locator":"Article 43(1) and (2), paragraph 2 marked AMENDED; Commission summary at the head of the page","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 5.3 (Measure), introductory text, document page 28; Table 3, MEASURE 1.3","access":"free"},{"title":"Notice of Adoption of Final Rule: Use of Automated Employment Decision Tools (6 RCNY Chapter 5, Subchapter T)","publisher":"New York City Department of Consumer and Worker Protection","year":2023,"url":"https://rules.cityofnewyork.us/wp-content/uploads/2023/04/DCWP-NOA-for-Use-of-Automated-Employment-Decisionmaking-Tools-2.pdf","locator":"Section 5-300, definition of ''Independent auditor''; section 5-301(a) (bias audit within the past year)","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division), published by The National Archives","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"Paragraph 199 (Ground 5, public sector equality duty); paragraph 201","access":"free"},{"title":"Ensuring statistical models command public confidence: learning lessons from the approach to developing models for awarding grades in the UK in 2020","publisher":"Office for Statistics Regulation","year":2021,"url":"https://osr.statisticsauthority.gov.uk/wp-content/uploads/2021/03/Ensuring_statistical_models_command_public_confidence.pdf","locator":"Section 3.4.1.1 (''Engagement with commissioners of the model and others who can help ensure the results meet the need''); section 3.3.1.1 (external challenge through Red Teams or independent advisory panels)","access":"free"},{"title":"Government Response: Royal Commission into the Robodebt Scheme","publisher":"Australian Government, Department of the Prime Minister and Cabinet","year":2023,"url":"https://www.pmc.gov.au/sites/default/files/resource/download/gov-response-royal-commission-robodebt-scheme.pdf","locator":"Recommendation 17.2 (''Establishment of a body to monitor and audit automated decision-making'') and the Government''s response, p.22","access":"free"},{"title":"Outsider Oversight: Designing a Third Party Audit Ecosystem for AI Governance","publisher":"Inioluwa Deborah Raji, Peggy Xu, Colleen Honigsberg and Daniel E. Ho (arXiv; AAAI/ACM AIES 2022)","year":2022,"url":"https://arxiv.org/abs/2206.04737","locator":"Abstract (arXiv:2206.04737v1)","access":"free"},{"title":"AI auditing: The Broken Bus on the Road to AI Accountability","publisher":"Abeba Birhane, Ryan Steed, Victor Ojewale, Briana Vecchione and Inioluwa Deborah Raji (arXiv; IEEE SaTML 2024)","year":2024,"url":"https://arxiv.org/abs/2401.14462","locator":"Abstract (arXiv:2401.14462v1)","access":"free"},{"title":"Auditing large language models: a three-layered approach","publisher":"Jakob Mökander, Jonas Schuett, Hannah Rose Kirk and Luciano Floridi (arXiv; AI and Ethics, 2023)","year":2023,"url":"https://arxiv.org/abs/2302.08500","locator":"Abstract (arXiv:2302.08500v2)","access":"free"},{"title":"The IIA''s Three Lines Model: an update of the Three Lines of Defense","publisher":"The Institute of Internal Auditors","year":2020,"url":"https://www.theiia.org/globalassets/documents/resources/the-iias-three-lines-model-an-update-of-the-three-lines-of-defense-july-2020/three-lines-model-updated-english.pdf","locator":"Principle 5 (''Third line independence''); Principle 4 (''Third line roles'')","access":"free"}]'::jsonb, '2026-10-02')
