insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.8', '["**What it measures.** Whether the organisation can show, from records made at the time, how each AI system came to be approved, on what evidence, by whom, and what has been reviewed since.","**Why it matters.** A person harmed by an AI decision can only have it examined if a record exists of what was decided and why. Without one the mistake cannot be traced, nobody can be held to account, and the board cannot show that it weighed the people affected.","**The UK position.** Every company must record minutes of all proceedings at directors'' meetings; authenticated minutes are evidence of what took place. Directors must have regard to employees, customers and the community, and large companies must report how they did so. No statute gives a safe harbour for good paperwork: a court may, at its discretion, relieve a director who acted honestly and reasonably. In the Business and Property Courts a party must take reasonable steps to preserve documents once it knows it may face proceedings, and a document is defined widely: \"It also extends to metadata, and other embedded data which is not typically visible on screen or a printout.\" A file written up afterwards carries its own date.","**What good looks like.** One file per system: purpose, approval and conditions, risk and impact assessments, supplier checks, test results, incidents, reviews.","**Reading the answer.** Ask for one system''s file and time how long it takes to produce. Scattered records, and records rebuilt after the event, are the two usual failures.","**A defensible figure.** Minutes of directors'' meetings must be kept for at least ten years from the date of the meeting (Companies Act 2006, section 248)."]'::jsonb, false, '[{"title":"Companies Act 2006, section 248: Minutes of directors'' meetings","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/248","locator":"s.248(1)-(4)","access":"free"},{"title":"Companies Act 2006, section 249: Minutes as evidence","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/249","locator":"s.249(1)-(2)","access":"free"},{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a)-(f)","access":"free"},{"title":"Companies Act 2006, section 414CZA: Section 172(1) statement","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CZA","locator":"s.414CZA(1)-(2); note F2 (inserted by S.I. 2018/860)","access":"free"},{"title":"Companies Act 2006, section 1157: Power of court to grant relief in certain cases","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/1157","locator":"s.1157(1)-(2)","access":"free"},{"title":"Practice Direction 57AD: Disclosure in the Business and Property Courts","publisher":"Ministry of Justice","year":2022,"url":"https://www.justice.gov.uk/courts/procedure-rules/civil/rules/part-57a-business-and-property-courts/practice-direction-57ad-disclosure-in-the-business-and-property-courts","locator":"Paras 2.2, 2.5-2.6 (meaning of document), 3.1 (disclosure duties), 4.1-4.5 (preservation), 13.1 (native format, metadata)","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 2 (''ATRS purpose and scope''); sections 5-13 (the template tiers)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 5.1 (GOVERN), document page 22 (page 27 of the PDF); MAP 2.2; MEASURE 3.1","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 8 (''Document your data, models and prompts''), provisions 8.1 and 8.1.1","access":"free"},{"title":"AI Act, Article 26: Obligations of deployers of high-risk AI systems (AI Act Service Desk copy)","publisher":"European Commission","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Article 26(5)-(6); ''About this text'' notice. Article 73 (serious incident reporting) read alongside","access":"free"},{"title":"Explaining decisions made with AI, Part 3: Documentation","publisher":"Information Commissioner''s Office","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-3-what-explaining-ai-means-for-your-organisation/documentation/","locator":"''At a glance'' and ''Checklist''; sections ''What documentation should we provide to demonstrate the explainability of our AI system?'' and ''How should we organise this documentation?''; under-review banner","access":"free"},{"title":"FCA Handbook, SYSC 9.1: General rules on record-keeping","publisher":"Financial Conduct Authority","year":2021,"url":"https://handbook.fca.org.uk/handbook/SYSC/9/1.html","locator":"SYSC 9.1.1R (dated 01/01/2021); SYSC 9.1.1AR and 9.1.1BR (common platform firms: compliance, risk management and internal audit reports to be kept)","access":"free"},{"title":"AI Act, Article 18: Documentation keeping (AI Act Service Desk copy)","publisher":"European Commission","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-18","locator":"Article 18(1)(a)-(e); read with Article 12 (automatic logging over the lifetime of the system)","access":"free"},{"title":"Code of Practice on the management of records issued under section 46 of the Freedom of Information Act 2000","publisher":"The National Archives","year":2021,"url":"https://assets.publishing.service.gov.uk/media/6114c3278fa8f506c4d84100/Freedom_Information_Code_Practice_Web_Accessible.pdf","locator":"Paragraph 1.2.4; paragraph 1.3 (status of the Code); Glossary (''Records'', citing BS ISO 15489-1:2016)","access":"free"},{"title":"SS1/23: Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 3.5 (''Model development documentation''), points (a) and (b); para 1.5 (in effect 17 May 2024)","access":"free"},{"title":"Government Response: Royal Commission into the Robodebt Scheme","publisher":"Australian Government, Department of the Prime Minister and Cabinet","year":2023,"url":"https://www.pmc.gov.au/sites/default/files/resource/download/gov-response-royal-commission-robodebt-scheme.pdf","locator":"Recommendation 23.8 (''Documenting decisions and discussions'') and the Government''s response","access":"free"},{"title":"Reviewable Automated Decision-Making: A Framework for Accountable Algorithmic Systems","publisher":"Jennifer Cobbe, Michelle Seng Ah Lee and Jatinder Singh (arXiv; ACM FAccT 2021)","year":2021,"url":"https://arxiv.org/abs/2102.04201","locator":"Abstract (arXiv:2102.04201v2)","access":"free"},{"title":"Model Cards for Model Reporting","publisher":"Margaret Mitchell and eight co-authors (arXiv; FAT* 2019)","year":2019,"url":"https://arxiv.org/abs/1810.03993","locator":"Abstract (arXiv:1810.03993v2)","access":"free"},{"title":"Datasheets for Datasets","publisher":"Timnit Gebru and six co-authors (arXiv; Communications of the ACM, December 2021)","year":2021,"url":"https://arxiv.org/abs/1803.09010","locator":"Abstract (arXiv:1803.09010v8)","access":"free"}]'::jsonb, '2026-10-02')
