insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.1', '["**What it measures.** Whether every AI system in use, including tools bought in or embedded in other software, has been assigned a risk tier by a written method, with the reasoning kept.","**Why it matters.** A tier decides how much care a system gets. A tool that screens job applicants or scores credit, left unclassified, gets the oversight given to a spellchecker, and the people it sifts bear errors nobody was looking for.","**The UK position.** UK law sets no AI risk tiers. The 2023 white paper said: \"We will not assign rules or risk levels to entire sectors or technologies.\" The Prudential Regulation Authority does expect banks to tier every model, vendor models included. The EU''s AI Act does set classes in law: prohibited practices, and high-risk uses listed in an annex, among them recruitment, credit scoring and education. It reaches organisations outside the Union where a system''s output is used there. Its prohibitions have applied since 2 February 2025, with two more from 2 December 2026. Within the listed areas, a system that profiles people always counts as high-risk.","**What good looks like.** One method applied to the whole register; tier and reasons recorded for each system; procured and embedded tools included; re-tiering when a use or a supplier''s feature changes; independent review of the method.","**Reading the answer.** A claim to have no high-risk AI is a finding only if someone checked. Ask for the recruitment platform''s tier and reasoning.","**A defensible figure.** In the Bank of England and Financial Conduct Authority''s 2024 survey of financial firms (118 responses), a third of AI use cases were third-party implementations; firms rated 62% of use cases low materiality and 16% high."]'::jsonb, true, '[{"title":"Regulation (EU) 2024/1689 (AI Act), Article 6: Classification rules for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-6","locator":"Art. 6(1), (1a)-(1c) (NEW), 6(2), 6(3) and 6(4)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Annex III: High-risk AI systems referred to in Article 6(2)","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/annex-3","locator":"Annex III, points 1 to 8; point 3 (education), point 4(a) (recruitment), point 5(b) (credit)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 5: Prohibited AI practices","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-5","locator":"Art. 5(1)(a)-(h); points (ba) and (bb) and paragraphs 1a and 1b marked NEW","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, third paragraph, points (a) and (c), both marked AMENDED","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 2: Scope","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-2","locator":"Art. 2(1)(a)-(c)","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Section 3.2.2, paragraph 45","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 1.3 ''Model tiering'', points (a)-(e), PDF p.12-13; Principle 1.2 ''Model inventory''; paragraphs 1.2-1.3 (scope) and 1.5 (effective date)","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Executive summary, ''Third-party exposure'' and ''Materiality''; section 1.2 ''Methodology''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 1.2.3 ''Risk Prioritization'', p.7; MAP 4.1 and 4.2, Table 2, p.27; GOVERN 6.1, Table 1, p.24","access":"free"},{"title":"International AI Safety Report 2026","publisher":"International AI Safety Report (chair: Yoshua Bengio)","year":2026,"url":"https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026","locator":"Executive summary, ''Real-world evidence for several risks is growing''; chapter 2 introduction; section 3.2, Table 3.1 and ''Risk thresholds/risk tiers''","access":"free"},{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1) and 35(3)(a)-(c)","access":"free"},{"title":"Data protection impact assessments: When do we need to do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/when-do-we-need-to-do-a-dpia/","locator":"Section ''What does ''likely to result in a high risk'' mean?''; section ''What does the ICO consider likely to result in high risk?'' (innovative technology, denial of service)","access":"free"},{"title":"Use of artificial intelligence in government (HC 612, Session 2023-24)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Part Three, paragraph 3.28; Figure 12","access":"free"},{"title":"General principles for classification of high-risk AI systems (summary of the draft Commission guidelines)","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/general-principles-classification-high-risk-ai-systems","locator":"''Quick classification checklist'', steps 1 to 6","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 7: Amendments to Annex III","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-7","locator":"Art. 7(1)(a)-(b) and 7(2)","access":"free"},{"title":"AI Risk Assessment: A Scenario-Based, Proportional Methodology for the AI Act","publisher":"Digital Society (Springer Nature); C. Novelli, F. Casolari, A. Rotolo, M. Taddeo and L. Floridi","year":2024,"url":"https://link.springer.com/article/10.1007/s44206-024-00095-1","locator":"Abstract; section 1 (Introduction)","access":"free"},{"title":"The AI risk repository: A meta-review, database, and taxonomy of risks from artificial intelligence","publisher":"arXiv (P. Slattery, A. K. Saeri, E. A. C. Grundy and others); stated on the page as published in Patterns (Cell Press), 2026","year":2024,"url":"https://arxiv.org/abs/2408.12622","locator":"Abstract","access":"free"},{"title":"OECD Framework for the Classification of AI Systems (OECD Digital Economy Papers No. 323)","publisher":"Organisation for Economic Co-operation and Development","year":2022,"url":"https://www.oecd.org/content/dam/oecd/en/publications/reports/2022/02/oecd-framework-for-the-classification-of-ai-systems_336a8b57/cb6d9eca-en.pdf","locator":"Executive summary, ''Key dimensions structure AI system characteristics and interactions''; Box 5 ''AI risk-based approaches'' (p.67)","access":"free"},{"title":"NSW AI Assessment Framework","publisher":"NSW Government, Digital NSW","year":2026,"url":"https://www.digital.nsw.gov.au/policy/artificial-intelligence/nsw-artificial-intelligence-assessment-framework","locator":"Opening section; notice ''The AIAF Platform is mandatory from 30 September 2026''","access":"free"}]'::jsonb, '2026-10-02')
