insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.5', '["**What it measures.** Whether every AI risk the organisation has identified carries a recorded decision (reduce it, share it, stop the activity or accept it) with a named person, a date and a check that the action worked.","**Why it matters.** A risk that is written down and then left is a known harm waiting for its victim: the applicant wrongly screened out, the customer wrongly refused credit. A register without decisions shows only that the organisation knew.","**The UK position.** No UK statute prescribes treatment options for AI. The government''s Orange Book lists them: avoiding the risk, changing its likelihood or consequences, sharing it through contracts, or \"retaining the risk by informed decision\". It asks who is accountable for approving each option. The Information Commission (ICO) accepts that not every data protection risk must be eliminated, but a high risk that remains must go to the regulator before processing starts. Sharing has limits. The Equality Act 2010 treats what an agent does with a principal''s authority as done by the principal, and no contract term can exclude the Act; whether this reaches a software supplier is untested. Insurance is uncertain: the Lloyd''s Market Association says cover may turn on the policy''s cyber clause.","**What good looks like.** Each risk has a decision, an owner, a date and a measure of success. Acceptance is signed by someone with authority. Residual risk is reported against appetite.","**Reading the answer.** Pick a risk logged six months ago and ask what changed. Silence is not acceptance.","**A defensible figure.** In a 2025 Lloyd''s Market Association survey (144 responses, mostly underwriters), 18% of responses judged insureds'' AI risk management inadequate. This is opinion, not claims data."]'::jsonb, false, '[{"title":"The Orange Book: Management of Risk, Principles and Concepts","publisher":"HM Treasury and Government Finance Function","year":2023,"url":"https://assets.publishing.service.gov.uk/media/6453acadc33b460012f5e6b8/HMT_Orange_Book_May_2023.pdf","locator":"Section D, paragraphs D6 to D8, p.23 (PDF page 25)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4, MANAGE 1.2 to 1.4, p.32 (PDF page 37); section 1.2.3, p.8","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 9: Risk management system","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-9","locator":"Art. 9(5), first and second subparagraphs","access":"free"},{"title":"Data protection impact assessments: How do we do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/how-do-we-do-a-dpia/","locator":"Sections ''Step 6: How do we identify mitigating measures?'' and ''Step 7: How do we conclude our DPIA?''","access":"free"},{"title":"UK GDPR, Article 36: Prior consultation","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/36","locator":"Art. 36(1)","access":"free"},{"title":"Equality Act 2010, section 109: Liability of employers and principals","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/109","locator":"s.109(1) to (4)","access":"free"},{"title":"Equality Act 2010, section 144: Contracting out","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/144","locator":"s.144(1)","access":"free"},{"title":"Understanding artificial intelligence risk in insurance products: the challenges","publisher":"Lloyd''s Market Association","year":2025,"url":"https://lmalloyds.com/understanding-artificial-intelligence-risk-in-insurance-products-the-challenges/","locator":"Paragraphs under ''What is AI?'' and ''Protective effects and risk mitigation'' (final paragraph)","access":"free"},{"title":"Understanding AI Exposures: AI Loss Scenarios Survey Results","publisher":"Lloyd''s Market Association","year":2025,"url":"https://lmalloyds.com/campaigns/understanding-ai-exposures-ai-loss-scenarios-survey-results/","locator":"Executive summary, ''Are insureds managing the risks (of AI errors causing insured losses) adequately?''; ''Methodology'' (144 responses)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''How do we identify mitigating measures?'', final paragraph; section on outsourcing and third-party AI systems, final paragraph","access":"free"},{"title":"Unfair Contract Terms Act 1977, section 2: Negligence liability","publisher":"legislation.gov.uk","year":1977,"url":"https://www.legislation.gov.uk/ukpga/1977/50/section/2","locator":"s.2(1) and (2)","access":"free"},{"title":"SS2/21: Outsourcing and third party risk management (November 2024 update)","publisher":"Prudential Regulation Authority, Bank of England","year":2024,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2024/ss221-november-2024-update.pdf","locator":"Chapter 4 ''Governance'', paragraph 4.3, p.12","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 4, Provisions 28 and 29","access":"free"},{"title":"Risk Management in the Artificial Intelligence Act","publisher":"European Journal of Risk Regulation (Cambridge University Press); author Jonas Schuett","year":2023,"url":"https://www.cambridge.org/core/journals/european-journal-of-risk-regulation/article/risk-management-in-the-artificial-intelligence-act/2E4D5707E65EFB3251A76E288BA74068","locator":"Section V.2 ''Risk management process, Article 9(2)'', paragraph following Footnote 106","access":"free"},{"title":"Insuring AI: The Role of Insurance in Artificial Intelligence Regulation","publisher":"Harvard Journal of Law & Technology, vol. 35 no. 2; author Anat Lior","year":2022,"url":"https://jolt.law.harvard.edu/assets/articlePDFs/v35/2.-Lior-Insuring-AI.pdf","locator":"Part V.A.4 ''Exceptions and Exclusions'', p.510","access":"free"},{"title":"Post Office Horizon IT Inquiry: Report, Volume 1 (HC 1119)","publisher":"Post Office Horizon IT Inquiry (Sir Wyn Williams)","year":2025,"url":"https://www.postofficehorizoninquiry.org.uk/sites/default/files/2025-07/Post%20Office%20Horizon%20IT%20Inquiry%20Final%20Report%20Volume%201_0.pdf","locator":"Volume 1, Part 1, paragraphs 1.3 to 1.5","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Paragraphs 3.12 and 3.13","access":"free"}]'::jsonb, '2026-10-02')
