insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.6', '["**What it measures.** Whether the organisation would notice an AI system causing harm, has someone with authority to stop it, and knows whom it must tell and how quickly.","**Why it matters.** Every hour a faulty system runs, more people are wrongly refused or put at risk. If only one absent person can switch it off, the harm continues. A late report leaves other users exposed.","**The UK position.** The UK has no AI-specific incident reporting law; existing duties apply by subject. A personal data breach must be reported to the Information Commission (ICO) without undue delay. A producer or distributor who knows a consumer product is unsafe must notify an enforcement authority at once. Under the EU AI Act, where deployers have reason to think a system presents a risk, \"they shall, without undue delay, inform the provider or distributor and the relevant market surveillance authority, and shall suspend the use of that system\". A serious incident is reported first to the provider. The Commission''s consolidated text applies these duties to listed high-risk uses from 2 December 2027.","**What good looks like.** A written procedure names who may suspend each system, and a deputy. Triggers are defined. Reporting duties are mapped in advance. Logs are preserved. Incidents reach the board. The procedure is rehearsed.","**Reading the answer.** Ask who could stop the system tonight, and whether they have ever done so in a test.","**A defensible figure.** The EU AI Act''s outer limit for reporting a serious incident is 15 days after the provider or, where applicable, the deployer becomes aware of it; 10 days after a death; two days for a widespread infringement or irreversible disruption of critical infrastructure (Article 73)."]'::jsonb, false, '[{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(5), first subparagraph; Art. 26(6) and (12)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 73: Reporting of serious incidents","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-73","locator":"Art. 73(2), (3), (4), (5), (6), (9), (10)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 3: Definitions","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-3","locator":"Art. 3, point (49)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, third paragraph, point (c)(i) and (ii) (marked AMENDED)","access":"free"},{"title":"Draft guidance, Article 73 AI Act: incident reporting (high-risk AI systems)","publisher":"European Commission","year":2025,"url":"https://ec.europa.eu/newsroom/dae/redirection/document/119624","locator":"Section 3.2 ''Deployers of high-risk AI Systems'', paragraphs (47) and (48), PDF page 10","access":"free"},{"title":"UK GDPR, Article 33: Notification of a personal data breach","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/33","locator":"Art. 33(1), (2), (4), (5)","access":"free"},{"title":"Personal data breaches: a guide","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/report-a-breach/personal-data-breach/personal-data-breaches-a-guide/","locator":"Opening summary (''At a glance'') and section ''What breaches do we need to notify the ICO about?''","access":"free"},{"title":"The General Product Safety Regulations 2005, regulation 9: Obligations of producers and distributors","publisher":"legislation.gov.uk","year":2005,"url":"https://www.legislation.gov.uk/uksi/2005/1803/regulation/9","locator":"reg. 9(1), (3), (4)","access":"free"},{"title":"Towards a common reporting framework for AI incidents (OECD Artificial Intelligence Papers No. 34)","publisher":"Organisation for Economic Co-operation and Development","year":2025,"url":"https://www.oecd.org/content/dam/oecd/en/publications/reports/2025/02/towards-a-common-reporting-framework-for-ai-incidents_8c488fdb/f326d4ac-en.pdf","locator":"Abstract, p.1; executive summary, p.9; ''Common reporting framework'', p.10; Table 2.2","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4, MANAGE 2.3, 2.4 and 4.3, pp.32-33 (PDF pages 37-38)","access":"free"},{"title":"The Medical Devices (Post-market Surveillance Requirements) (Amendment) (Great Britain) Regulations 2024, regulation 4 (new Part 4A)","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/uksi/2024/1368/regulation/4/made","locator":"Regulation 4, inserted regulation 44ZH(1), (3), (4) and (5); regulation 44ZG","access":"free"},{"title":"FCA Handbook, SUP 15.3: General notification requirements","publisher":"Financial Conduct Authority","year":2026,"url":"https://handbook.fca.org.uk/handbook/SUP/15/3.html","locator":"SUP 15.3.1R; SUP 15.3.7G (Principle 11)","access":"free"},{"title":"The Network and Information Systems Regulations 2018, regulation 11: The duty to notify incidents","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/uksi/2018/506/regulation/11","locator":"reg. 11(1), (2) and (3)(b)(i)","access":"free"},{"title":"In the Matter of Knight Capital Americas LLC: Order Instituting Administrative and Cease-and-Desist Proceedings (Release No. 34-70694)","publisher":"U.S. Securities and Exchange Commission","year":2013,"url":"https://www.sec.gov/files/litigation/admin/2013/34-70694.pdf","locator":"Summary, paragraph 9(D); paragraphs 15 to 21 (events of 1 August 2012)","access":"free"},{"title":"Preventing Repeated Real World AI Failures by Cataloging Incidents: The AI Incident Database","publisher":"arXiv (author''s copy; paper for the Innovative Applications of Artificial Intelligence conference, IAAI-21); author Sean McGregor","year":2020,"url":"https://arxiv.org/abs/2011.08512","locator":"Abstract","access":"free"},{"title":"Deployment Corrections: An incident response framework for frontier AI models","publisher":"arXiv (Institute for AI Policy and Strategy); authors Joe O''Brien, Shaun Ee, Zoe Williams","year":2023,"url":"https://arxiv.org/abs/2310.00328","locator":"Abstract","access":"free"},{"title":"AI incident reporting: Addressing a gap in the UK’s regulation of AI","publisher":"The Centre for Long-Term Resilience; author Tommy Shaffer Shane","year":2024,"url":"https://www.longtermresilience.org/reports/ai-incident-reporting-addressing-a-gap-in-the-uks-regulation-of-ai/","locator":"Executive summary, ''A critical gap''","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 10, provision 10.3; Principle 6, provision 6.5","access":"free"},{"title":"Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile (NIST AI 600-1)","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf","locator":"Suggested actions GV-1.7-001 (GOVERN 1.7) and MG-2.4-001 to MG-2.4-004 (MANAGE 2.4)","access":"free"}]'::jsonb, '2026-10-02')
