insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.8', '["**What it measures.** Whether the depth of risk work matches the organisation''s size and the stakes of each system, and whether there is a record to show for it.","**Why it matters.** With too little, people harmed by a system find that nobody can show what was considered or why. With too much, a small firm spends its effort on paperwork for trivial tools.","**The UK position.** UK GDPR Article 24 scales the duty: measures must reflect the nature, scope, context and purposes of processing and its risks, and the controller must be able to demonstrate compliance. The Information Commission (ICO), in guidance under review, says: \"Your governance and risk management capabilities need to be proportionate to your use of AI.\" Its audit framework says no single approach fits all. Government policy since 2023 is that burdens should not fall disproportionately on smaller companies. In the EU, the AI Act as amended in 2026 lets small and medium-sized enterprises and small mid-caps give technical documentation in a simplified form. The Commission''s form was not found published. Simplification changes the format, not the level of protection.","**What good looks like.** One file per system, as deep as the stakes: what it is, how it was classed and why, the treatment decisions, the controls, incidents and reviews. It is kept current and can be produced on request.","**Reading the answer.** Ask for the file on the highest-stakes system. Lean is fine. Empty or stale is not.","**A defensible figure.** The European Commission estimated that extending small-company relief to small mid-caps would ease implementation for a further 8,250 companies. This was its estimate when the change was proposed."]'::jsonb, false, '[{"title":"UK GDPR, Article 24: Responsibility of the controller","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/24","locator":"Art. 24(1)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''How should we approach AI governance and risk management?'', second paragraph; section on managing trade-offs","access":"free"},{"title":"Data protection audit framework","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/","locator":"Opening section and ''Who can use the framework?''","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Part 2, paragraph 28; Part 3, paragraph 37 (''Proportionate'')","access":"free"},{"title":"SS1/23: Model risk management principles for banks","publisher":"Prudential Regulation Authority, Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Paragraphs 3.3 and 3.4 (''Proportionality''), p.9","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 11: Technical documentation","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-11","locator":"Art. 11(1), second subparagraph (marked AMENDED)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 63: Derogations for specific operators","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-63","locator":"Art. 63(1) (marked AMENDED) and 63(2)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 99: Penalties","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-99","locator":"Art. 99(1) (marked AMENDED), 99(6) and 99(6a) (marked NEW)","access":"free"},{"title":"AI Omnibus enters into force","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/news/ai-omnibus-enters-force","locator":"Bullets ''Support for growing companies'', ''High-risk AI systems in Annex III'' and ''Simplification for SMCs''","access":"free"},{"title":"AI Act Service Desk: Frequently Asked Questions (Digital Omnibus)","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/faq","locator":"Question ''How will these changes benefit to businesses?'' (tagged Digital Omnibus)","access":"free"},{"title":"UK GDPR, Article 30: Records of processing activities","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/30","locator":"Art. 30(1), (4) and (5)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Annex IV: Technical documentation referred to in Article 11(1)","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/annex-4","locator":"Annex IV, opening words and points 1 to 9","access":"free"},{"title":"Guidance for using the AI Management Essentials tool: government response","publisher":"Department for Science, Innovation and Technology","year":2026,"url":"https://www.gov.uk/government/consultations/ai-management-essentials-tool/outcome/guidance-for-using-the-ai-management-essentials-tool-government-response","locator":"Executive summary; ''Key themes and government response'', Proportionality and procurement","access":"free"},{"title":"Risk assessment: Steps needed to manage risk","publisher":"Health and Safety Executive","year":2024,"url":"https://www.hse.gov.uk/simple-health-safety/risk/steps-needed-to-manage-risk.htm","locator":"Sections ''What reasonably practicable means'' and ''Record your findings''","access":"free"},{"title":"Model Cards for Model Reporting","publisher":"arXiv (authors'' copy; Proceedings of the Conference on Fairness, Accountability, and Transparency, FAT* 2019); authors Margaret Mitchell and others","year":2019,"url":"https://arxiv.org/abs/1810.03993","locator":"Abstract","access":"free"},{"title":"Closing the AI Accountability Gap: Defining an End-to-End Framework for Internal Algorithmic Auditing","publisher":"arXiv (authors'' copy; Proceedings of the Conference on Fairness, Accountability, and Transparency, FAT* 2020); authors Inioluwa Deborah Raji and others","year":2020,"url":"https://arxiv.org/abs/2001.00973","locator":"Abstract","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Introduction, ''Scale- and Business-model-agnostic'' (point d), p.10; paragraph 3.13","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Passage headed ''Auditability'' (accountability and responsibility); practical recommendations on model cards","access":"free"},{"title":"Use of artificial intelligence in government (HC 612)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Summary, paragraph 17; Part Three, paragraph 3.20","access":"free"}]'::jsonb, '2026-10-02')
