insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.1', '["**What it measures.** Whether the organisation knows where its AI could treat people worse because of who they are: each AI use set against the protected characteristics it could affect, with a named owner.","**Why it matters.** A model can discriminate without anyone intending it, and without holding any protected data. The Information Commission (ICO) puts it plainly: \"These ''proxy variables'' enable the model to reproduce patterns of discrimination associated with those characteristics, even if the designers did not intend this.\" Removing the sensitive fields does not remove the risk.","**The UK position.** The Equality Act 2010 protects nine characteristics. Indirect discrimination turns on effect, not motive: a practice that puts a protected group at a particular disadvantage is unlawful unless it is a proportionate means of achieving a legitimate aim. The duty sits with the employer or service provider applying the practice, and anything done by an agent with the organisation''s authority is treated as its own act, whether or not it knew. Data protection law adds a separate fairness duty: no unjustified adverse effects on individuals. The regulator has made automated decisions in recruitment a stated priority.","**What good looks like.** A documented map, refreshed when a use changes, reported to the board, independently reviewed, and consulted before purchase or deployment. Government guidance on recruitment expects an impact assessment before procurement and again before deployment.","**Reading the answer.** Awareness confined to HR is the usual weak point; pricing, lending and service triage carry the same exposure. A low answer here limits what the organisation can credibly claim about bias testing and monitoring.","**A defensible figure.** Auditing AI recruitment tools in 2024, the regulator made 296 recommendations to developers and providers; 97% were accepted and 3% partially accepted."]'::jsonb, true, '[{"title":"Equality Act 2010, section 19: Indirect discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/19","locator":"s.19(1)-(3)","access":"free"},{"title":"Equality Act 2010, section 109: Liability of employers and principals","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/109","locator":"s.109(2)-(4)","access":"free"},{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections ''Why might an AI system lead to discrimination?'' and ''Should we just remove all sensitive data?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/action-weve-taken/audits-and-overview-reports/ai-tools-in-recruitment/","locator":"pp. 3-4, 7, 12","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections on assurance mechanisms before procurement and before deployment","access":"free"},{"title":"AI and biometrics strategy","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/about-the-ico/our-information/our-strategies-and-plans/artificial-intelligence-and-biometrics-strategy/","locator":"Priority on automated decision-making","access":"free"},{"title":"Equality Act 2010, section 4: The protected characteristics","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/4","locator":"s.4","access":"free"},{"title":"Equality Act 2010, section 13: Direct discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/13","locator":"s.13(1)-(2)","access":"free"},{"title":"Equality Act 2010, section 29: Provision of services, etc.","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/29","locator":"s.29(1)-(2), (6)","access":"free"},{"title":"Equality Act 2010, section 149: Public sector equality duty","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/149","locator":"s.149(1)-(3), (7)","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division), published by The National Archives (Find Case Law)","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"paras 175-181 and 199-201","access":"free"},{"title":"Review into bias in algorithmic decision-making","publisher":"Centre for Data Ethics and Innovation","year":2020,"url":"https://www.gov.uk/government/publications/cdei-publishes-review-into-bias-in-algorithmic-decision-making/main-report-cdei-review-into-bias-in-algorithmic-decision-making","locator":"Executive summary, ''Guidance to organisation leaders and boards''; section 2.4 on proxies and direct discrimination","access":"free"},{"title":"Algorithms: How they can reduce competition and harm consumers","publisher":"Competition and Markets Authority","year":2021,"url":"https://www.gov.uk/government/publications/algorithms-how-they-can-reduce-competition-and-harm-consumers/algorithms-how-they-can-reduce-competition-and-harm-consumers","locator":"Section 2, ''Algorithmic discrimination'', subsection ''Geographic targeting''","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"''Using AI safely and responsibly'', Ethics: Fairness, bias and discrimination, practical recommendations","access":"free"},{"title":"EU AI Act (Regulation (EU) 2024/1689), Article 27: Fundamental rights impact assessment for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-27","locator":"Art. 27(1)(c)-(d)","access":"free"},{"title":"Tax Administration fined for discriminatory and unlawful data processing","publisher":"Autoriteit Persoonsgegevens (Dutch Data Protection Authority)","year":2021,"url":"https://www.autoriteitpersoonsgegevens.nl/en/current/tax-administration-fined-for-discriminatory-and-unlawful-data-processing","locator":"Sections ''Unlawful processing'' and ''Discriminatory processing''","access":"free"},{"title":"Discrimination in the Age of Algorithms (NBER Working Paper 25548)","publisher":"Jon Kleinberg, Jens Ludwig, Sendhil Mullainathan and Cass R. Sunstein; National Bureau of Economic Research","year":2019,"url":"https://www.nber.org/papers/w25548","locator":"Abstract (issue date February 2019)","access":"free"},{"title":"Why Fairness Cannot Be Automated: Bridging the Gap Between EU Non-Discrimination Law and AI","publisher":"Sandra Wachter, Brent Mittelstadt and Chris Russell (arXiv preprint)","year":2020,"url":"https://arxiv.org/abs/2005.05906","locator":"Abstract","access":"free"},{"title":"Protected Grounds and the System of Non-Discrimination Law in the Context of Algorithmic Decision-Making and Artificial Intelligence","publisher":"Janneke Gerards and Frederik Zuiderveen Borgesius (arXiv; Colorado Technology Law Journal, 2022)","year":2022,"url":"https://arxiv.org/abs/2509.08837","locator":"Abstract","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology (US)","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 2, MAP 5 and MAP 5.1 (p. 27); section 3.7, ''Fair - with Harmful Bias Managed'' (p. 17)","access":"free"}]'::jsonb, '2026-10-05')
