insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.2', '["**What it measures.** Whether data is examined for inherited unfairness before it informs decisions about people: where it came from, who is missing, and which ordinary-looking fields stand in for protected characteristics.","**Why it matters.** A system trained on past decisions repeats them. Where past lending was prejudiced against women, the Information Commission (ICO) warns, \"any model based on such training data is likely to reproduce the same pattern of discrimination.\" A thinly represented group is served worse. Those harmed are people already disadvantaged, refused again by a process that looks neutral. Deleting the sensitive column is no remedy: occupation, working hours or postcode can carry the same signal.","**The UK position.** Indirect discrimination under the Equality Act 2010 turns on effect; a biased dataset is no defence. Checking for bias often needs sensitive data. The Data Protection Act 2018 permits processing of data on race, religion, health and sexual orientation to keep equality of opportunity under review, provided it is necessary, is not used for decisions about a particular person, and a policy document is in place. Guessing is no substitute: the regulator found gender and ethnicity inferred from names too inaccurate to monitor bias.","**What good looks like.** A documented screening step covering provenance, representation and proxies, completed before the data is used; results logged and repeated as data changes; the method independently assured; the legal condition for bias-monitoring data recorded.","**Reading the answer.** Removing the sensitive fields alone is a low answer, not a high one. Buyers should ask suppliers how training data was checked.","**A defensible figure.** No defensible figure was found."]'::jsonb, false, '[{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections ''Why might an AI system lead to discrimination?'', ''Should we just remove all sensitive data?'', ''Can we process special category data to assess and address discrimination in AI systems?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 3, 12, 18-20, 22","access":"free"},{"title":"Data Protection Act 2018, Schedule 1, paragraph 8: Equality of opportunity or treatment","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/schedule/1/paragraph/8","locator":"Sch.1 para 8(1)-(5); see also para 5 (appropriate policy document)","access":"free"},{"title":"Equality Act 2010, section 19: Indirect discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/19","locator":"s.19(1)-(2)","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections 3.2 (during procurement), 4.1 (before deployment), Annex A (screening)","access":"free"},{"title":"UK GDPR, Article 9: Processing of special categories of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/9","locator":"Art. 9(1) and 9(2)(g)","access":"free"},{"title":"Data Protection Act 2018, Schedule 1, Part 4: Appropriate policy document and additional safeguards","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/schedule/1/part/4","locator":"Sch.1 paras 38-39","access":"free"},{"title":"EU AI Act (Regulation (EU) 2024/1689), Article 10: Data and data governance","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-10","locator":"Art. 10(2)(f)-(g) and 10(3)","access":"free"},{"title":"EU AI Act (Regulation (EU) 2024/1689), Article 4a: Processing of special categories of personal data for bias detection and correction","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-4a","locator":"Art. 4a(1)(a)-(f) and 4a(2)","access":"free"},{"title":"Guidance on AI and data protection: Annex A, Fairness in the AI lifecycle","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/annex-a-fairness-in-the-ai-lifecycle/","locator":"Sections 3 (Data collection) and 4 (Data analysis and pre-processing), ''What is statistical bias?''","access":"free"},{"title":"Research Note: A literature review on bias in supervised machine learning","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/publication/research-notes/literature-review-bias-in-supervised-machine-learning.pdf","locator":"PDF p. 11 (proxies; training only on accepted applicants, p. 12); numbered findings, PDF p. 7","access":"free"},{"title":"Review into bias in algorithmic decision-making","publisher":"Centre for Data Ethics and Innovation","year":2020,"url":"https://www.gov.uk/government/publications/cdei-publishes-review-into-bias-in-algorithmic-decision-making/main-report-cdei-review-into-bias-in-algorithmic-decision-making","locator":"Chapter 2, summary box (''Fairness through unawareness is often not enough to prevent bias''); Recommendation 6","access":"free"},{"title":"Enabling responsible access to demographic data to make AI systems fairer","publisher":"Centre for Data Ethics and Innovation","year":2023,"url":"https://www.gov.uk/government/publications/enabling-responsible-access-to-demographic-data-to-make-ai-systems-fairer/report-enabling-responsible-access-to-demographic-data-to-make-ai-systems-fairer","locator":"Section 1, Executive summary (proxies)","access":"free"},{"title":"Ensuring statistical models command public confidence: Learning lessons from the approach to developing models for awarding grades in the UK in 2020","publisher":"Office for Statistics Regulation","year":2021,"url":"https://osr.statisticsauthority.gov.uk/publication/ensuring-statistical-models-command-public-confidence/","locator":"Findings, ''Understanding the impact of historical patterns of performance in the underlying data on results''","access":"free"},{"title":"Equity in Medical Devices: Independent Review","publisher":"Department of Health and Social Care (independent review chaired by Professor Dame Margaret Whitehead)","year":2024,"url":"https://assets.publishing.service.gov.uk/media/65e89e9e62ff48001a87b2d8/equity-in-medical-devices-independent-review-report-web-accessible.pdf","locator":"Executive summary, Recommendation 10 (PDF p. 19); chair''s foreword (PDF pp. 6-7)","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 11, Development Data Specification, ''What are sensitive attributes?''","access":"free"},{"title":"Towards a Standard for Identifying and Managing Bias in Artificial Intelligence (Special Publication 1270)","publisher":"National Institute of Standards and Technology (US)","year":2022,"url":"https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.1270.pdf","locator":"''Statistical and Computational'' bias (PDF p. 18); systemic bias (PDF p. 15); proxies (PDF p. 25)","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Info-communications Media Development Authority (IMDA) and Personal Data Protection Commission (PDPC), Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Section 3, Operations management: ''Data for model development'', ''Minimising inherent bias'' (PDF pp. 38-39)","access":"free"},{"title":"Using sensitive data to prevent discrimination by artificial intelligence: Does the GDPR need a new exception?","publisher":"Marvin van Bekkum and Frederik Zuiderveen Borgesius (arXiv; Computer Law & Security Review 48 (2023) 105770)","year":2023,"url":"https://arxiv.org/abs/2206.03262","locator":"Abstract","access":"free"},{"title":"Gender Shades: Intersectional Accuracy Disparities in Commercial Gender Classification","publisher":"Joy Buolamwini and Timnit Gebru; Proceedings of Machine Learning Research 81 (Conference on Fairness, Accountability and Transparency)","year":2018,"url":"https://proceedings.mlr.press/v81/buolamwini18a.html","locator":"Abstract (pp. 77-91)","access":"free"},{"title":"A Framework for Understanding Sources of Harm throughout the Machine Learning Life Cycle","publisher":"Harini Suresh and John V. Guttag (arXiv; ACM EAAMO 2021)","year":2021,"url":"https://arxiv.org/abs/1901.10002","locator":"Abstract","access":"free"},{"title":"Datasheets for Datasets","publisher":"Timnit Gebru and others (arXiv; published in Communications of the ACM, December 2021)","year":2021,"url":"https://arxiv.org/abs/1803.09010","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-05')
