insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.3', '["**What it measures.** Whether the organisation checks what its AI does to different groups: outcomes compared across groups, against thresholds set beforehand, recorded, and repeated after launch.","**Why it matters.** Without testing, the first sign of unfairness is a complaint, by which time people have already been refused a job, a loan or a service because of who they are. Testing also depends on sound group data. Auditing recruitment tools that guessed candidates'' gender and ethnicity from their names, the Information Commission (ICO) found: \"This inferred information is not accurate enough to monitor bias effectively.\"","**The UK position.** No UK statute sets a numerical test. The Equality Act 2010 asks whether a practice puts a protected group at a particular disadvantage and whether it is a proportionate means of achieving a legitimate aim. Numbers are evidence towards that question, not the answer. The regulator''s guidance, under review since the Data (Use and Access) Act 2025, expects performance to be evaluated group by group and monitored after deployment, as often as the impact warrants. Government assurance guidance calls this a bias audit and expects it repeated.","**What good looks like.** Thresholds chosen and justified in advance. Tests before launch, on a schedule and before each change. Group data collected lawfully, not guessed. Results and remedial action kept and reported to senior management.","**Reading the answer.** Common weak points: a single launch check, and tests covering only sex, ethnicity and age because nothing else is recorded. Small groups may be too few to measure.","**A defensible figure.** Many audited recruitment-tool providers used a four-fifths rule as a minimum: each group''s selection rate at least 80% of the highest group''s. It comes from United States employment guidelines, not UK law."]'::jsonb, false, '[{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 3, 20-24","access":"free"},{"title":"Equality Act 2010, section 19: Indirect discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/19","locator":"s.19(2)(b) and (d)","access":"free"},{"title":"Guidance on AI and data protection: Annex A, Fairness in the AI lifecycle","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/annex-a-fairness-in-the-ai-lifecycle/","locator":"Sections ''Model evaluation'' and ''Deployment and monitoring''","access":"free"},{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections on technical approaches to mitigating discrimination and on processing special category data to assess discrimination","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections 3.2 (during procurement) and 4.2 (live operation)","access":"free"},{"title":"Towards a Standard for Identifying and Managing Bias in Artificial Intelligence (Special Publication 1270)","publisher":"National Institute of Standards and Technology (US)","year":2022,"url":"https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.1270.pdf","locator":"PDF pp. 13-14 (legal context, footnote 9) and p. 41 (fairness metrics)","access":"free"},{"title":"Essop and others v Home Office (UK Border Agency); Naeem v Secretary of State for Justice [2017] UKSC 27","publisher":"UK Supreme Court, published by The National Archives (Find Case Law)","year":2017,"url":"https://caselaw.nationalarchives.gov.uk/uksc/2017/27","locator":"paras 9, 24-28 and 30-33 (Lady Hale)","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division), published by The National Archives (Find Case Law)","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"paras 199-201 (Ground 5)","access":"free"},{"title":"Equality Act 2010, section 136: Burden of proof","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/136","locator":"s.136(2)-(3)","access":"free"},{"title":"EU AI Act (Regulation (EU) 2024/1689), Article 9: Risk management system","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-9","locator":"Art. 9(6)-(8)","access":"free"},{"title":"Uniform Guidelines on Employee Selection Procedures (1978), 29 CFR 1607.4: Information on impact","publisher":"US Equal Employment Opportunity Commission; Code of Federal Regulations, US Government Publishing Office (govinfo.gov)","year":2024,"url":"https://www.govinfo.gov/content/pkg/CFR-2024-title29-vol4/pdf/CFR-2024-title29-vol4-sec1607-4.pdf","locator":"s.1607.4(D), ''Adverse impact and the four-fifths rule'' (p. 222 of the 1 July 2024 edition)","access":"free"},{"title":"Automated Employment Decision Tools (AEDT): Local Law 144 of 2021","publisher":"New York City Department of Consumer and Worker Protection","year":2023,"url":"https://www.nyc.gov/site/dca/about/automated-employment-decision-tools.page","locator":"Opening paragraph and enforcement note","access":"free"},{"title":"Universal Credit Advances Model: Fairness Assessment (1 April 2024 to 31 March 2025)","publisher":"Department for Work and Pensions","year":2025,"url":"https://www.gov.uk/government/publications/fairness-assessment-including-statistical-analysis-of-the-universal-credit-advances-machine-learning-model-1-april-2024-to-31-march-2025/universal-credit-advances-model-fairness-assessment","locator":"Executive summary; paras 14-23","access":"free"},{"title":"Summary: accuracy and equitability evaluation of Cognitec FaceVACS-DBScan ID v5.5 (National Physical Laboratory testing of the facial recognition algorithm used to search the Police National Database)","publisher":"Home Office","year":2025,"url":"https://www.gov.uk/government/publications/facial-recognition-technology-tests-national-physical-laboratory/summary-accuracy-and-equitability-evaluation-of-cognitec-facevacs-dbscan-id-v55","locator":"Sections on what the testing found and how policing and the Home Office responded","access":"free"},{"title":"Review into bias in algorithmic decision-making","publisher":"Centre for Data Ethics and Innovation","year":2020,"url":"https://www.gov.uk/government/publications/cdei-publishes-review-into-bias-in-algorithmic-decision-making/main-report-cdei-review-into-bias-in-algorithmic-decision-making","locator":"Section 3.2 (Recruitment: findings)","access":"free"},{"title":"Introduction to AI assurance","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/introduction-to-ai-assurance/introduction-to-ai-assurance","locator":"Sections 4.2 (AI assurance mechanisms) and 5.6 (Bias audit)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology (US)","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 3, MEASURE 2.11 (p. 30)","access":"free"},{"title":"IEEE 7003-2024: IEEE Standard for Algorithmic Bias Considerations","publisher":"IEEE Standards Association","year":2025,"url":"https://standards.ieee.org/ieee/7003/11357/","locator":"Standard summary on the IEEE Standards Association page","access":"free summary"},{"title":"Research Note: A literature review on bias in supervised machine learning","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/publication/research-notes/literature-review-bias-in-supervised-machine-learning.pdf","locator":"Numbered findings, point 2 (PDF p. 7)","access":"free"},{"title":"Inherent Trade-Offs in the Fair Determination of Risk Scores","publisher":"Jon Kleinberg, Sendhil Mullainathan and Manish Raghavan (arXiv; Innovations in Theoretical Computer Science 2017)","year":2016,"url":"https://arxiv.org/abs/1609.05807","locator":"Abstract","access":"free"},{"title":"The four-fifths rule is not disparate impact: a woeful tale of epistemic trespassing in algorithmic fairness","publisher":"Elizabeth Anne Watkins, Michael McKenna and Jiahao Chen (arXiv preprint)","year":2022,"url":"https://arxiv.org/abs/2202.09519","locator":"Abstract","access":"free"},{"title":"Fairness Under Unawareness: Assessing Disparity When Protected Class Is Unobserved","publisher":"Jiahao Chen, Nathan Kallus, Xiaojie Mao, Geoffry Svacha and Madeleine Udell (arXiv; ACM Conference on Fairness, Accountability, and Transparency 2019)","year":2018,"url":"https://arxiv.org/abs/1811.11154","locator":"Abstract","access":"free"},{"title":"Mitigating Bias in Algorithmic Hiring: Evaluating Claims and Practices","publisher":"Manish Raghavan, Solon Barocas, Jon Kleinberg and Karen Levy (arXiv; related DOI 10.1145/3351095.3372828)","year":2019,"url":"https://arxiv.org/abs/1906.09208","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-05')
