insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.4', '["**What it measures.** Whether the organisation stops sensitive personal data from driving automated decisions about people unless a lawful exception applies, and whether that rule is enforced.","**Why it matters.** Health, ethnicity, religion, sexual orientation, trade union membership and biometric identifiers are the facts most easily turned into discrimination. When a system decides a job, a loan or a service on them with nobody looking, the person may never learn why, and the harm falls on those already most exposed.","**The UK position.** Since 5 February 2026 the UK GDPR has allowed most automated decisions, subject to safeguards. Sensitive data is the exception: \"A significant decision based entirely or partly on processing described in Article 9(1) (processing of special categories of personal data) may not be taken based solely on automated processing, unless one of the following conditions is met.\" The conditions are explicit consent, or a decision necessary for a contract or required or authorised by law, each of the last two also needing a substantial public interest condition. The regulator''s draft guidance, not yet final, applies the rule even to a small amount of such data, including inferred data.","**What good looks like.** A documented rule; every automated decision checked for sensitive data, inferred data included; technical blocks where possible; and an exceptions register, each entry recording its condition, reviewed by the board.","**Reading the answer.** The usual gap is inference. A system with no field marked health can still treat people differently on a health inference, which the regulator counts as special category data however uncertain the inference.","**A defensible figure.** The regulator''s draft guidance counts 23 substantial public interest conditions; one must apply wherever the contract or legal-authority route is used."]'::jsonb, false, '[{"title":"UK GDPR, Article 22B: Restrictions on automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22B","locator":"Art. 22B(1)-(4); textual amendment note F1","access":"free"},{"title":"Data (Use and Access) Act 2025, section 80: Automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/section/80","locator":"s.80(1); commencement notes I1, I2","access":"free"},{"title":"The Data (Use and Access) Act 2025 (Commencement No. 6 and Transitional and Saving Provisions) Regulations 2026 (S.I. 2026/82)","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/uksi/2026/82/regulation/2/made","locator":"reg. 2(j); saving in reg. 5","access":"free"},{"title":"UK GDPR, Article 9: Processing of special categories of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/9","locator":"Art. 9(1) and 9(2)(g)","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): When can we use special category data in our ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/when-can-we-use-special-category-data-in-our-adm/","locator":"Sections ''What is special category data?'' and ''What are the special category data conditions for ADM?''","access":"free"},{"title":"Special category data: What is special category data?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/special-category-data/what-is-special-category-data/","locator":"Section ''What about inferences?'' (updated 9 April 2024)","access":"free"},{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Art. 22A(1)-(2); textual amendment note F1","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1)-(2)","access":"free"},{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(3)(a)-(b)","access":"free"},{"title":"Data Protection Act 2018, section 10: Special categories of personal data and criminal convictions etc data","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/10","locator":"s.10(1)(b) and (3)","access":"free"},{"title":"Data Protection Act 2018, Schedule 1, Part 2: Substantial public interest conditions","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/schedule/1/part/2","locator":"Sch.1 para 5 (policy document) and paras 6-28 (the conditions)","access":"free"},{"title":"Data (Use and Access) Act 2025: Explanatory Notes","publisher":"Department for Science, Innovation and Technology and other departments; published by TSO on legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/pdfs/ukpgaen_20250018_en.pdf","locator":"Section 80, paras 634-641 (pp. 84-85; PDF p. 87)","access":"free"},{"title":"The Data Use and Access Act 2025 (DUAA): what does it mean for organisations?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/legislation-we-cover/data-use-and-access-act-2025/the-data-use-and-access-act-2025-what-does-it-mean-for-organisations/","locator":"Summary of what the Act changes, ''Automated decision-making''","access":"free"},{"title":"Special category data: What are the substantial public interest conditions?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/special-category-data/what-are-the-substantial-public-interest-conditions/","locator":"Section ''What substantial public interest conditions are available?'' and the table of conditions","access":"free"},{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections ''What about special category data, discrimination and automated decision-making?'' and ''What if we accidentally infer special category data through our use of AI?''","access":"free"},{"title":"Enabling responsible access to demographic data to make AI systems fairer","publisher":"Centre for Data Ethics and Innovation","year":2023,"url":"https://www.gov.uk/government/publications/enabling-responsible-access-to-demographic-data-to-make-ai-systems-fairer/report-enabling-responsible-access-to-demographic-data-to-make-ai-systems-fairer","locator":"Section 1, Executive summary (proxies)","access":"free"},{"title":"EU AI Act (Regulation (EU) 2024/1689), Article 5: Prohibited AI practices","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-5","locator":"Art. 5(1)(g)","access":"free"},{"title":"Guidelines on Automated individual decision-making and Profiling for the purposes of Regulation 2016/679 (WP251rev.01)","publisher":"Article 29 Data Protection Working Party (European Commission)","year":2018,"url":"https://ec.europa.eu/newsroom/article29/redirection/document/49826","locator":"Chapter III, special categories of data (PDF p. 15); Chapter IV.D, Article 22(4) (PDF p. 24)","access":"free"},{"title":"A Right to Reasonable Inferences: Re-Thinking Data Protection Law in the Age of Big Data and AI","publisher":"Sandra Wachter and Brent Mittelstadt; Columbia Business Law Review, vol. 2019 no. 2","year":2019,"url":"https://journals.library.columbia.edu/index.php/CBLR/article/view/3424","locator":"Abstract","access":"free"},{"title":"Blind Justice: Fairness with Encrypted Sensitive Attributes","publisher":"Niki Kilbertus, Adrià Gascón, Matt J. Kusner, Michael Veale, Krishna P. Gummadi and Adrian Weller (arXiv; Proceedings of the 35th International Conference on Machine Learning, PMLR 80, 2018)","year":2018,"url":"https://arxiv.org/abs/1806.03281","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
