insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.5', '["**What it measures.** Whether the people who review AI-supported decisions can change them: competent to judge the output, authorised to overrule it, and able to see how it was reached.","**Why it matters.** A reviewer who passes on the system''s proposal protects no one. The person refused a job or a loan believes someone considered their case when nobody did. The regulator calls the cause automation bias: people trust the output and stop using their own judgement.","**The UK position.** Since February 2026 the UK GDPR has said \"a decision is based solely on automated processing if there is no meaningful human involvement in the taking of the decision\". The statute does not define meaningful; it requires only that the extent of profiling be weighed. The practical test is the Information Commission (ICO)''s: can the reviewer exercise real influence before the decision is applied, with the authority, discretion and competence to alter it? Access to the system''s reasoning is not in the statute; the regulator treats outputs reviewers cannot interpret as a risk that review becomes empty. Where a significant decision has no meaningful involvement, the person must be told and able to make representations, obtain human intervention and contest it.","**What good looks like.** Reviewers trained and authorised in writing to overrule; reasons and inputs visible to them; acceptance and rejection rates monitored; reviews sampled and re-checked; results fed into training and design.","**Reading the answer.** Reviewers who routinely agree and cannot show they assessed the case may be treated as absent. Reviewing only high scorers is a common gap.","**A defensible figure.** For its March 2026 recruitment report the regulator contacted 37 employers and judged 16 likely to be using automated decision-making on candidates."]'::jsonb, false, '[{"title":"Data (Use and Access) Act 2025, section 80: Automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/section/80","locator":"s.80(1), inserting UK GDPR Articles 22A-22D","access":"free"},{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Art. 22A(1)(a) and 22A(2)","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(2)(a)-(d); textual amendment note F1","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What is the role of human oversight?'' through ''What monitoring should we undertake?''","access":"free"},{"title":"Recruitment rewired: an update on the ICO''s work on the fair and responsible use of automation in recruitment","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/meaningful-human-involvement/","locator":"Executive summary (parent page) and section ''Meaningful human involvement''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"''Human reviews in AI'', pp. 32-34","access":"free"},{"title":"Recruitment rewired: Introduction","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/introduction-what-is-adm-and-why-are-we-focusing-on-it-in-recruitment/","locator":"Section ''How we''ve examined automated recruitment practices''","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): What does the UK GDPR say about ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-does-the-uk-gdpr-say-about-adm/","locator":"Section ''What is a ''solely'' automated decision?'', paragraph after the five criteria for meaningful human involvement","access":"free"},{"title":"Data protection audit framework, artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure and its ''Ways to meet our expectations'' list; second control measure","access":"free"},{"title":"Guidelines on Automated individual decision-making and Profiling for the purposes of Regulation 2016/679 (WP251rev.01)","publisher":"Article 29 Data Protection Working Party (European Commission)","year":2018,"url":"https://ec.europa.eu/newsroom/article29/redirection/document/49826","locator":"Chapter IV, section B, PDF p.21","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 14: Human oversight","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-14","locator":"Art. 14(4)(a)-(d)","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Section ''Determining the level of human involvement in AI-augmented decision-making'', paras 3.14-3.17, PDF pp.30-31","access":"free"},{"title":"The Flaws of Policies Requiring Human Oversight of Government Algorithms","publisher":"Ben Green, Computer Law & Security Review 45 (author''s copy on arXiv)","year":2022,"url":"https://arxiv.org/abs/2109.05067","locator":"Abstract","access":"free"},{"title":"Human-AI Interactions in Public Sector Decision Making: ''Automation Bias'' and ''Selective Adherence'' to Algorithmic Advice","publisher":"Saar Alon-Barkat and Madalina Busuioc, Journal of Public Administration Research and Theory (published version, authors'' copy on arXiv)","year":2022,"url":"https://arxiv.org/pdf/2103.02381","locator":"Abstract, p.1 (study 1 N = 605, study 2 N = 904, study 3 N = 1,345)","access":"free"},{"title":"Does the Whole Exceed its Parts? The Effect of AI Explanations on Complementary Team Performance","publisher":"Gagan Bansal and others, CHI 2021 (authors'' copy on arXiv)","year":2021,"url":"https://arxiv.org/abs/2006.14779","locator":"Abstract","access":"free"},{"title":"When combinations of humans and AI are useful: A systematic review and meta-analysis","publisher":"Michelle Vaccaro, Abdullah Almaatouq and Thomas Malone, Nature Human Behaviour 8","year":2024,"url":"https://www.nature.com/articles/s41562-024-02024-1","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-05')
