insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.6', '["**What it measures.** Whether there is a defined point before deployment where ethical concerns are heard, and where the reviewers can require changes or refuse outright.","**Why it matters.** The people harmed by a poor AI deployment (customers scored, staff monitored, applicants filtered out) are rarely in the room when it is approved. A gate is how their interests are weighed before the harm, not after. Without power to refuse, review only records concerns about a decision already made.","**The UK position.** No UK law requires an ethics committee, but the law does supply one hard gate. Where processing of personal data is likely to result in a high risk to people, the controller must assess the impact before processing begins. If a high risk cannot be reduced, the regulator must be consulted first. Its guidance is blunt: \"You cannot go ahead with the processing until you have consulted us.\" The regulator may then limit or ban the processing. Breach of these duties can attract a fine of up to £8,700,000 or 2% of worldwide turnover, whichever is higher. That gate covers data protection only. Wider ethical questions are left to the organisation; government''s framework for public bodies accepts that sometimes the right choice is not to use a system at all.","**What good looks like.** Written criteria, a rule that in-scope uses pass through, minutes of what was weighed, board visibility, and outside input on contested calls. UNESCO''s 2021 recommendation asks states to introduce ethical impact assessment for AI.","**Reading the answer.** Ask whether the gate has ever refused or changed anything, and who can overrule it.","**A defensible figure.** On prior consultation the regulator has up to eight weeks to give written advice, extendable by six."]'::jsonb, false, '[{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1), (3), (7)","access":"free"},{"title":"UK GDPR, Article 36: Prior consultation","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/36","locator":"Art. 36(1)-(2)","access":"free"},{"title":"Data protection impact assessments: Do we need to consult the ICO?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/do-we-need-to-consult-the-ico/","locator":"Sections ''When do we need to consult the ICO?'', ''How long does it take?'' and ''What are the possible outcomes?''","access":"free"},{"title":"UK GDPR, Article 83: General conditions for imposing administrative fines","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/83","locator":"Art. 83(4)(a)","access":"free"},{"title":"Data and AI Ethics Framework","publisher":"Government Digital Service / Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/data-ethics-framework/data-and-ai-ethics-framework","locator":"Accountability principle; passage on human oversight (''the right choice might be to not use the system at all'')","access":"free"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","year":2021,"url":"https://www.unesco.org/en/legal-affairs/recommendation-ethics-artificial-intelligence","locator":"Policy Area 1: Ethical impact assessment, paras 50-53","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division), published by Courts and Tribunals Judiciary","year":2020,"url":"https://www.judiciary.uk/wp-content/uploads/2020/08/R-Bridges-v-CC-South-Wales-ors-Judgment.pdf","locator":"Paras 152-154 (data protection impact assessment); paras 199-201 (public sector equality duty), PDF pp.33 and 42-43","access":"free"},{"title":"Equality Act 2010, section 149: Public sector equality duty","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/149","locator":"s.149(1)-(2)","access":"free"},{"title":"Data protection impact assessments: When do we need to do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/when-do-we-need-to-do-a-dpia/","locator":"List of processing operations requiring a DPIA, item ''Innovative technology''; section ''What does ''innovative technologies'' mean?''","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Section ''Governance'', paragraphs on the AI governance board and the ethics committee","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 27: Fundamental rights impact assessment for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-27","locator":"Art. 27(1) and 27(3)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology (US)","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4, MANAGE 1.1, p.32 (PDF p.37); Part 1 section on go/no-go decisions","access":"free"},{"title":"How to design an AI ethics board","publisher":"Jonas Schuett, Anka Reuel and Alexis Carlier (arXiv preprint 2304.07249)","year":2023,"url":"https://arxiv.org/abs/2304.07249","locator":"Abstract","access":"free"},{"title":"Closing the AI Accountability Gap: Defining an End-to-End Framework for Internal Algorithmic Auditing","publisher":"Inioluwa Deborah Raji and others, ACM FAT* 2020 (authors'' copy on arXiv)","year":2020,"url":"https://arxiv.org/abs/2001.00973","locator":"Abstract","access":"free"},{"title":"Walking the Walk of AI Ethics: Organizational Challenges and the Individualization of Risk among Ethics Entrepreneurs","publisher":"Sanna J. Ali and others, ACM FAccT 2023 (authors'' copy on arXiv)","year":2023,"url":"https://arxiv.org/abs/2305.09573","locator":"Abstract","access":"free"},{"title":"Algorithmic impact assessment: a case study in healthcare","publisher":"Ada Lovelace Institute","year":2022,"url":"https://www.adalovelaceinstitute.org/report/algorithmic-impact-assessment-case-study-healthcare/","locator":"Section ''Proposed process'', step 2 ''Application filtering''; Annex 2, Data Access Committee terms of reference","access":"free"},{"title":"West Midlands Police Data, Technology and Operational Ethics Panel","publisher":"West Midlands Police and Crime Commissioner","year":2026,"url":"https://www.westmidlands-pcc.gov.uk/ethics-committee/","locator":"Section ''What is the West Midlands Police Data, Technology and Operational Ethics Panel?''","access":"free"}]'::jsonb, '2026-10-02')
