insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.7', '["**What it measures.** Whether a supplier''s statement that its AI is fair is tested before the organisation relies on it: evidence asked for, read, re-checked, and backed by contract terms that give a right to look.","**Why it matters.** The people affected are applicants, customers and staff scored or filtered by a tool the organisation did not build and cannot see inside. If the tool treats a group worse, they bear the harm, and they have no dealings with the supplier. The evidence sits with the vendor; the decision sits with the buyer.","**The UK position.** The Equality Act 2010 places the duty not to discriminate on the employer and the service provider. Whether a software supplier counts as their agent is untested, so buying a tool should not be assumed to move the duty. Data protection law requires a controller to be able to demonstrate fair processing, to use only processors giving sufficient guarantees, and to hold a contract allowing audits and inspections. That audit right covers data protection compliance; a wider fairness warranty has to be negotiated.","**What good looks like.** The Information Commission (ICO) tells recruiters: \"Request test results or reports and evidence of actions AI providers have taken to address fairness, accuracy, or bias issues in AI tools or outputs.\" Government guidance adds a pilot on the organisation''s own data before deployment.","**Reading the answer.** The usual weak point is evidence requested and filed unread. A high answer needs someone able to judge the test results, and a record of what was done when the supplier last changed the model.","**A defensible figure.** Auditing providers of AI recruitment tools, the regulator made 296 recommendations; 97% were accepted in full and 3% in part."]'::jsonb, false, '[{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 12, 19, 24, 40, 44-45, 47","access":"free"},{"title":"Thinking of using AI to assist recruitment? Our key data protection considerations","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/media-centre/news-and-blogs/2024/11/thinking-of-using-ai-to-assist-recruitment-our-key-data-protection-considerations/","locator":"Questions 3 and 4","access":"free"},{"title":"UK GDPR, Article 28: Processor","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/28","locator":"Art. 28(1) and 28(3)(h)","access":"free"},{"title":"Equality Act 2010, section 109: Liability of employers and principals","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/109","locator":"s.109(2)-(3); read with s.29(1)-(2) and s.39(1)-(2)","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections 3.2 (during procurement), 4.1 (before deployment), 4.2 (ongoing monitoring; iterative bias audits)","access":"free"},{"title":"Guidelines for AI procurement","publisher":"Office for Artificial Intelligence (UK government)","year":2020,"url":"https://www.gov.uk/government/publications/guidelines-for-ai-procurement/guidelines-for-ai-procurement","locator":"Sections ''Selection, evaluation and award'' and ''Contract implementation and ongoing management''","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division), published by Courts and Tribunals Judiciary","year":2020,"url":"https://www.judiciary.uk/wp-content/uploads/2020/08/R-Bridges-v-CC-South-Wales-ors-Judgment.pdf","locator":"Paras 193-201, PDF pp.41-43","access":"free"},{"title":"Review into bias in algorithmic decision-making","publisher":"Centre for Data Ethics and Innovation","year":2020,"url":"https://www.gov.uk/government/publications/cdei-publishes-review-into-bias-in-algorithmic-decision-making/main-report-cdei-review-into-bias-in-algorithmic-decision-making","locator":"Executive summary and Part III, passage on public sector procurement and the supply chain (before Recommendation 16); chapter 3, Recruitment","access":"free"},{"title":"Data protection audit framework, artificial intelligence toolkit: Contracts and third parties","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/contracts-and-third-parties/","locator":"Second control measure (due diligence before procuring), list ''Ways to meet our expectations''","access":"free"},{"title":"SS1/23: Model risk management principles for banks","publisher":"Prudential Regulation Authority, Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.6, ''Use of externally developed models, third-party vendor products'', points (a)-(b), PDF p.19","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 13: Transparency and provision of information to deployers","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-13","locator":"Art. 13(3)(b)(v)-(vi)","access":"free"},{"title":"Automated Employment Decision Tools (Local Law 144 of 2021)","publisher":"New York City Department of Consumer and Worker Protection","year":2023,"url":"https://www.nyc.gov/site/dca/about/automated-employment-decision-tools.page","locator":"Opening paragraph and enforcement note","access":"free"},{"title":"Auditing Work: Exploring the New York City algorithmic bias audit regime","publisher":"Lara Groves and others (arXiv preprint 2402.08101)","year":2024,"url":"https://arxiv.org/abs/2402.08101","locator":"Abstract","access":"free"},{"title":"Mitigating Bias in Algorithmic Hiring: Evaluating Claims and Practices","publisher":"Manish Raghavan, Solon Barocas, Jon Kleinberg and Karen Levy (authors'' copy on arXiv 1906.09208; published version DOI 10.1145/3351095.3372828)","year":2020,"url":"https://arxiv.org/abs/1906.09208","locator":"Abstract","access":"free"},{"title":"What does it mean to ''solve'' the problem of discrimination in hiring? Social, technical and legal perspectives from the UK on automated hiring systems","publisher":"Javier Sánchez-Monedero, Lina Dencik and Lilian Edwards (authors'' copy on arXiv 1910.06144)","year":2020,"url":"https://arxiv.org/abs/1910.06144","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-05')
