insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.8', '["**What it measures.** Whether, when AI is found to have treated people unfairly, the organisation corrects the system, re-examines the decisions it influenced and puts the affected people right.","**Why it matters.** Fixing a model helps the next applicant, not the one already refused a job, a loan or a service. Left untold, that person keeps the harm and cannot use the remedies the law provides. A quiet fix leaves the cost of the error with the people least able to detect it.","**The UK position.** The 2023 white paper made contestability and redress one of five principles, but said: \"The UK’s initial non-statutory approach will not create new rights or new routes to redress at this stage.\" Redress therefore runs through existing law. For a significant decision taken solely by automated processing, the person must be given information and be able to make representations, obtain human intervention and contest it. Anyone who suffers damage from a data protection infringement has a right to compensation. Under the Equality Act, a tribunal can award compensation and recommend steps to reduce the adverse effect on the complainant. Since 19 June 2026 controllers must also respond to data protection complaints and report the outcome.","**What good looks like.** A written process covering all three steps, with time to remedy measured, repeat faults tracked, independent assessment, and a public commitment that is kept.","**Reading the answer.** The usual gap is the middle step: nobody works out who was affected. None of the provisions read requires an organisation to seek out affected people unprompted; that is a commitment the board chooses.","**A defensible figure.** A controller must acknowledge a data protection complaint within 30 days of receipt (Data Protection Act 2018, section 164A(3))."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1)-(2)(a)-(d)","access":"free"},{"title":"Data (Use and Access) Act 2025, section 103: Complaints by data subjects","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/section/103","locator":"s.103(2), inserting Data Protection Act 2018 s.164A(2)-(5); commencement note I2","access":"free"},{"title":"UK GDPR, Article 82: Right to compensation and liability","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/82","locator":"Art. 82(1)-(4)","access":"free"},{"title":"Equality Act 2010, section 124: Remedies: general","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/124","locator":"s.124(2)-(7); see also s.119(4) for county court awards including injured feelings","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Section 3.2.3, box ''Principle: Contestability and redress'' (after para 52)","access":"free"},{"title":"OECD AI Principles, 1.3: Transparency and explainability","publisher":"OECD","year":2024,"url":"https://oecd.ai/en/dashboards/ai-principles/P7","locator":"Principle 1.3, final bullet","access":"free"},{"title":"FCA Handbook, DISP 1.3: Complaints handling rules","publisher":"Financial Conduct Authority","year":2019,"url":"https://handbook.fca.org.uk/handbook/DISP/1/3.html","locator":"DISP 1.3.3R (dated 03/01/2018) and DISP 1.3.6G (dated 01/04/2019)","access":"free"},{"title":"FG22/5: Final non-Handbook Guidance for firms on the Consumer Duty","publisher":"Financial Conduct Authority","year":2022,"url":"https://www.fca.org.uk/publication/finalised-guidance/fg22-5.pdf","locator":"Paras 5.15-5.17, PDF pp.30-31","access":"free"},{"title":"How to deal with data protection complaints","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/how-to-deal-with-data-protection-complaints/","locator":"Opening summary and ''Latest updates'' (published 12 February 2026, updated 8 May 2026)","access":"free"},{"title":"UK GDPR, Article 16: Right to rectification","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/16","locator":"Art. 16","access":"free"},{"title":"Equality Act 2010, section 119: Remedies","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/119","locator":"s.119(2)-(6)","access":"free"},{"title":"Principles for remedy","publisher":"Parliamentary and Health Service Ombudsman","year":2009,"url":"https://www.ombudsman.org.uk/sites/default/files/page/principles_for_remedy_0.pdf","locator":"Principle 5, ''Putting things right'', PDF p.5","access":"free"},{"title":"Post Office Horizon IT Inquiry Report: Volume 1 (human impact and redress)","publisher":"Post Office Horizon IT Inquiry (Sir Wyn Williams)","year":2025,"url":"https://www.postofficehorizoninquiry.org.uk/sites/default/files/2025-07/Post%20Office%20Horizon%20IT%20Inquiry%20Final%20Report%20Volume%201_0.pdf","locator":"Para 3.1, PDF p.12; Recommendation 2, section 2; section 6 on ''full and fair'' redress and delay","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 86: Right to explanation of individual decision-making","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-86","locator":"Art. 86(1)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 20: Corrective actions and duty of information","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-20","locator":"Art. 20(1)","access":"free"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","year":2021,"url":"https://www.unesco.org/en/legal-affairs/recommendation-ethics-artificial-intelligence","locator":"Para 29 (fairness and non-discrimination); para 35 (attributing responsibility in cases of remedy)","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): What are the ADM safeguards?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Sections ''What is ''human intervention''?'' and ''How do we enable people to contest decisions?''","access":"free"},{"title":"Conceptualising Contestability: Perspectives on Contesting Algorithmic Decisions","publisher":"Henrietta Lyons, Eduardo Velloso and Tim Miller (authors'' copy on arXiv 2103.01774; published version DOI 10.1145/3449180)","year":2021,"url":"https://arxiv.org/abs/2103.01774","locator":"Abstract","access":"free"},{"title":"Contestable AI by Design: Towards a Framework","publisher":"Kars Alfrink, Ianus Keller, Gerd Kortuem and Neelke Doorn, Minds and Machines 33","year":2022,"url":"https://link.springer.com/article/10.1007/s11023-022-09611-z","locator":"Abstract; section 5.1 (method: literature published 2016 to 2021)","access":"free"}]'::jsonb, '2026-10-02')
