insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.1', '["**What it measures.** Whether people are told, at the point of contact, that they are dealing with an AI system and not a person, under a written standard covering every channel.","**Why it matters.** People who think a person is listening disclose more and trust more. Letting that belief stand is deception by silence, and it falls hardest on children, older people and anyone in distress. The Competition and Markets Authority puts the test simply: \"if the fact they are dealing with AI rather than a person might affect people’s decisions then you should tell them.\"","**The UK position.** No UK statute names a duty to disclose AI. The duty arises from consumer law: leaving out information the average consumer needs to take an informed decision is a misleading omission, and the business answers for its AI agent even where a supplier built it. Fines can reach £300,000 or, if higher, 10% of turnover. Transparency is one of the government''s five non-statutory AI principles. In the EU, an explicit duty has applied since 2 August 2026. It falls on the system''s provider, and the exception for obvious cases is read restrictively.","**What good looks like.** Disclosure at the first exchange, in the interface or spoken aloud, in plain words. A line in the terms and conditions is not enough. Coverage is checked across web chat, voice, messaging and email, and the wording is tested with users.","**Reading the answer.** The usual gap is the channel nobody listed. A fluent assistant handling complaints is where disclosure matters most.","**A defensible figure.** In a March 2024 survey for the UK''s AI Safety Institute, 68% agreed that a customer service chatbot should make clear whether the agent is human or artificial; 16% disagreed."]'::jsonb, true, '[{"title":"Complying with consumer law when using AI agents","publisher":"Competition and Markets Authority","year":2026,"url":"https://www.gov.uk/government/publications/complying-with-consumer-law-when-using-ai-agents/complying-with-consumer-law-when-using-ai-agents","locator":"Sections ''Tell your customers if you use an AI agent'' and ''When it comes to dealing with your customers, the same rules apply whether using AI or human agents''","access":"free"},{"title":"Digital Markets, Competition and Consumers Act 2024, section 227: Misleading omissions","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/227","locator":"s.227(1), (2) and (4); read with s.225(4)(a) and s.226(1)(b)","access":"free"},{"title":"AI Act (Regulation (EU) 2024/1689), Article 50: Transparency obligations for providers and deployers of certain AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-50","locator":"Article 50(1) and 50(5); application date from Article 113 on the same site","access":"free"},{"title":"Guidelines on the implementation of the transparency obligations for certain AI systems under Article 50 of the AI Act, C(2026) 5054 final, Annex","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/library/guidelines-transparency-obligations-providers-and-deployers-ai-systems","locator":"Section 3: paragraphs 30, 34-40 (pp. 11-15) and 42-45 with examples (pp. 16-18)","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Paragraphs 10-11; section 3.2.3, ''Principle: Appropriate transparency and explainability''","access":"free"},{"title":"Should AI systems behave like people?","publisher":"AI Security Institute (then AI Safety Institute)","year":2024,"url":"https://www.aisi.gov.uk/blog/should-ai-systems-behave-like-people","locator":"Section on transparency, first bullet; survey description above it; Figure 1 caption","access":"free"},{"title":"OECD AI Principles: Transparency and explainability (Principle 1.3)","publisher":"OECD (OECD.AI Policy Observatory)","year":2019,"url":"https://oecd.ai/en/dashboards/ai-principles/P7","locator":"Principle 1.3, second indent","access":"free"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","year":2021,"url":"https://www.unesco.org/en/legal-affairs/recommendation-ethics-artificial-intelligence","locator":"Paragraph 127 (policy area on communication and information / human-AI interaction); see also paragraph 38, last sentence","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Paragraph 3.46, ''General disclosure'' (p. 53)","access":"free"},{"title":"California Business and Professions Code, section 17941 (Bots)","publisher":"California Legislative Information","year":2018,"url":"https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=BPC&sectionNum=17941","locator":"s.17941(a) and (b); added by Stats. 2018, Ch. 892 (SB 1001), operative 1 July 2019","access":"free"},{"title":"California Senate Bill No. 243 (Companion chatbots), Chapter 677, Statutes of 2025","publisher":"California Legislative Information","year":2025,"url":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202520260SB243","locator":"Section 1, adding Business and Professions Code s.22602(a)","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 7: You are open and collaborative","access":"free"},{"title":"Digital Markets, Competition and Consumers Act 2024, section 226: Misleading actions","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/226","locator":"s.226(1)(b)","access":"free"},{"title":"Frontiers: Machines vs. Humans: The Impact of Artificial Intelligence Chatbot Disclosure on Customer Purchases","publisher":"Luo, Tong, Fang and Qu, Marketing Science 38(6)","year":2019,"url":"https://www.fox.temple.edu/sites/fox/files/Frontiers-Machines-versus-Humans-The-Impact-of-Artificial-Intelligence-Chatbot-Disclosure-on-Customer-Purchases.pdf","locator":"Abstract (p. 937)","access":"free"},{"title":"Trust me, I''m a bot: repercussions of chatbot disclosure in different service frontline settings","publisher":"Mozafari, Weiger and Hammerschmidt, Journal of Service Management","year":2021,"url":"https://www.uni-goettingen.de/de/document/download/0a0cb34d6c10c02ed20eca822f57db4f.pdf/10-1108_JOSM-10-2020-0380.pdf","locator":"Abstract, ''Findings''","access":"free"},{"title":"Large Language Models Pass the Turing Test","publisher":"Jones and Bergen, arXiv:2503.23674","year":2025,"url":"https://arxiv.org/abs/2503.23674","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
