insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.2', '["**What it measures.** Whether text, images, audio and video produced by the organisation''s AI carry a mark that software can detect, and a visible label where the law requires one.","**Why it matters.** Synthetic content that passes as real deceives the person who sees it and harms the person depicted: fraud, false endorsement, words never spoken. A caption is lost when the content is copied on. The European code of practice asks providers for \"at least two layers of machine-readable marking\": signed metadata and an imperceptible watermark.","**The UK position.** There is no general UK duty. The government said in March 2026 that the UK does not regulate how AI-generated content is labelled, and proposed to work with industry. The advertising regulator says there is no blanket requirement to disclose AI in adverts, though the rules on misleading content still apply. The EU duty reaches organisations outside the Union whose systems are sold there or whose output is used there. It applies from 2 August 2026; systems already on the market have until 2 December 2026. Those who publish must disclose deepfakes, and AI-written text on matters of public interest that no editor has reviewed.","**What good looks like.** An inventory of systems that generate content; signed metadata and watermarking on their output; checks that the marks survive the organisation''s publishing process; a record of what was feasible and what was chosen.","**Reading the answer.** Visible labels alone are the common middle answer; they are not marking. A high answer should rest on test evidence, not a supplier''s assurance.","**A defensible figure.** In 2025 Ofcom tested three openly available watermarking tools against 26 types of edit; some edits, such as cropping, removed the watermark."]'::jsonb, false, '[{"title":"Code of Practice on Transparency of AI-Generated Content","publisher":"European Commission (AI Office); drafted by independent chairs","year":2026,"url":"https://ec.europa.eu/newsroom/dae/redirection/document/129555","locator":"Section 1, Measure 1.1 (p. 8); Sub-measures 1.1.1 to 1.1.3 (pp. 9-10); Measure 3.3 (pp. 17-18)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 50: Transparency obligations for providers and deployers of certain AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-50","locator":"Article 50(2) and 50(4); see also Article 2(1)(a) and (c) on the same site","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 111: AI systems already placed on the market","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-111","locator":"Article 111(4), marked NEW; with Article 113 (general application from 2 August 2026)","access":"free"},{"title":"Deepfake Defences 2: The Attribution Toolkit","publisher":"Ofcom","year":2025,"url":"https://www.ofcom.org.uk/siteassets/resources/documents/online-safety/information-for-industry/deepfake-defences-2/deepfake-defences-2---the-attribution-toolkit.pdf?v=402066","locator":"Key takeaways 5 and 8 (pp. 6-7); Box 2 (p. 14); survey findings (pp. 25-26)","access":"free"},{"title":"Report on Copyright and Artificial Intelligence","publisher":"Department for Science, Innovation and Technology and Intellectual Property Office","year":2026,"url":"https://www.gov.uk/government/publications/report-and-impact-assessment-on-copyright-and-artificial-intelligence/report-on-copyright-and-artificial-intelligence","locator":"Section E: Output transparency (Overview; Conclusions and proposals); summary under ''Labelling of AI and human-created content''","access":"free"},{"title":"Disclosure of AI in Advertising: Striking the Balance Between Creativity and Responsibility","publisher":"Advertising Standards Authority and Committee of Advertising Practice","year":2025,"url":"https://www.asa.org.uk/news/disclosure-of-ai-in-advertising-striking-the-balance-between-creativity-and-responsibility.html","locator":"Whole article (dated 29 May 2025)","access":"free"},{"title":"Guidelines on the implementation of the transparency obligations for certain AI systems under Article 50 of the AI Act, C(2026) 5054 final, Annex","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/newsroom/dae/redirection/document/131215","locator":"Section 4.2, paragraph 70; marking obligation defined at 4.2.1, paragraph 71","access":"free"},{"title":"California Senate Bill No. 942 (California AI Transparency Act), Chapter 291, Statutes of 2024","publisher":"California Legislative Information","year":2024,"url":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240SB942","locator":"Section 1, adding Business and Professions Code s.22757.3(b)","access":"free"},{"title":"Reducing Risks Posed by Synthetic Content: An Overview of Technical Approaches to Digital Content Transparency (NIST AI 100-4)","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-4.pdf","locator":"Section 7, Conclusion","access":"free"},{"title":"Content Credentials: C2PA Technical Specification, version 2.4","publisher":"Coalition for Content Provenance and Authenticity (C2PA)","year":2026,"url":"https://spec.c2pa.org/specifications/specifications/2.4/specs/C2PA_Specification.html","locator":"Section 2.3.2, ''Claim'' (glossary); version history at 5.3.1","access":"free"},{"title":"Public content provenance for organisations","publisher":"National Cyber Security Centre and Canadian Centre for Cyber Security","year":2025,"url":"https://www.ncsc.gov.uk/files/public-content-provenance-for-organisations.pdf","locator":"Section 3.2.5, ''Digital watermarking'' (p. 15)","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 7 (You are open and collaborative), practical recommendations","access":"free"},{"title":"A Watermark for Large Language Models","publisher":"Kirchenbauer, Geiping, Wen, Katz, Miers and Goldstein, arXiv:2301.10226 (ICML 2023)","year":2023,"url":"https://arxiv.org/abs/2301.10226","locator":"Abstract","access":"free"},{"title":"Scalable watermarking for identifying large language model outputs","publisher":"Dathathri et al., Nature 634, 818-823","year":2024,"url":"https://www.nature.com/articles/s41586-024-08025-4","locator":"Abstract","access":"free"},{"title":"Can AI-Generated Text be Reliably Detected?","publisher":"Sadasivan, Kumar, Balasubramanian, Wang and Feizi, arXiv:2303.11156","year":2023,"url":"https://arxiv.org/abs/2303.11156","locator":"Abstract","access":"free"},{"title":"Invisible Image Watermarks Are Provably Removable Using Generative AI","publisher":"Zhao et al., arXiv:2306.01953 (NeurIPS 2024)","year":2023,"url":"https://arxiv.org/abs/2306.01953","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
