insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.3', '["**What it measures.** Whether the organisation can tell a person why an AI-supported decision about them came out as it did: the factors that mattered in their case, in plain words.","**Why it matters.** Someone refused a loan or a job who gets a standard paragraph cannot tell whether the decision was wrong or what to dispute. Their right to challenge exists on paper only. The regulator''s draft guidance says of the information owed: \"This is decision-specific information about the actual outcome, rather than simply repeating information you provide in your privacy notice\".","**The UK position.** Where a significant decision is solely automated, the UK GDPR requires safeguards that include giving the person information about that decision, fully in force since February 2026. Privacy notices and replies to access requests must separately give meaningful information about the logic involved. The statute does not say how much detail is owed; the regulator''s reading is still a consultation draft. Its earlier guidance with the Alan Turing Institute, now under review, names six types of explanation and separates explaining the process from explaining the outcome.","**What good looks like.** For each kind of significant decision, an agreed explanation format completed case by case: contributing factors, data used, who to ask for a review. Explanations sampled for accuracy and tested with the people who receive them.","**Reading the answer.** Privacy-notice wording alone is the usual weak answer. An organisation that cannot see why a bought-in system decided as it did cannot explain it, yet stays responsible.","**A defensible figure.** Research for the explanation guidance used two citizens'' juries, 36 people in all; most thought explanations important in recruitment and criminal justice, less so in healthcare (interim report, pages 10 and 15)."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and 22C(2)(a); textual amendment note F1","access":"free"},{"title":"UK GDPR, Article 15: Right of access by the data subject","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/15","locator":"Art. 15(1)(h); note F4. Same wording at Art. 13(2)(f) and Art. 14(2)(g)","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): What are the ADM safeguards?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Section ''What ''information about decisions'' do we have to provide?''","access":"free"},{"title":"Explaining decisions made with AI, Part 1: What goes into an explanation?","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-1-the-basics-of-explaining-ai/what-goes-into-an-explanation/","locator":"''At a glance'' and section ''Process-based vs outcome-based explanations''","access":"free"},{"title":"Explaining decisions made with AI, Part 3: Organisational roles and functions for explaining AI","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-3-what-explaining-ai-means-for-your-organisation/organisational-roles-and-functions-for-explaining-ai/","locator":"Section ''What if we use an AI system supplied by a third party?''","access":"free"},{"title":"Project explAIn: interim report","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2019,"url":"https://ico.org.uk/media2/migrated/2615039/project-explain-20190603.pdf","locator":"p. 10 (jury design: 18 jurors in Manchester, 18 in Coventry); p. 15 (findings by scenario)","access":"free"},{"title":"AI Act (Regulation (EU) 2024/1689), Article 86: Right to explanation of individual decision-making","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-86","locator":"Article 86(1); limits at 86(2) and 86(3)","access":"free"},{"title":"Regulation B (Equal Credit Opportunity Act), 12 CFR 1002.9: Notifications","publisher":"Consumer Financial Protection Bureau","year":2026,"url":"https://www.consumerfinance.gov/rules-policy/regulations/1002/9/","locator":"s.1002.9(b)(2), ''Statement of specific reasons'', with official interpretation of paragraph 9(b)(2)","access":"free"},{"title":"AI Update","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/publication/corporate/ai-update.pdf","locator":"Paragraphs 3.34 to 3.37, ''Appropriate transparency and explainability'' (pp. 15-16)","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Section 2.7, ''Explainability''; executive summary, ''Understanding of AI systems''","access":"free"},{"title":"Machine learning explainability in finance: an application to default risk analysis (Staff Working Paper No. 816)","publisher":"Bank of England (Bracke, Datta, Jung and Sen)","year":2019,"url":"https://www.bankofengland.co.uk/working-paper/2019/machine-learning-explainability-in-finance-an-application-to-default-risk-analysis","locator":"Abstract on the working paper''s page","access":"free"},{"title":"Four Principles of Explainable Artificial Intelligence (NISTIR 8312)","publisher":"National Institute of Standards and Technology","year":2021,"url":"https://nvlpubs.nist.gov/nistpubs/ir/2021/NIST.IR.8312.pdf","locator":"Abstract (p. i)","access":"free"},{"title":"Ethics, Transparency and Accountability Framework for Automated Decision-Making","publisher":"Department for Science, Innovation and Technology, Centre for Data Ethics and Innovation, Cabinet Office and Office for Artificial Intelligence","year":2023,"url":"https://www.gov.uk/government/publications/ethics-transparency-and-accountability-framework-for-automated-decision-making/ethics-transparency-and-accountability-framework-for-automated-decision-making","locator":"Point 5, ''Help users and citizens understand how it impacts them'', under ''Context''","access":"free"},{"title":"OECD AI Principles: Transparency and explainability (Principle 1.3)","publisher":"OECD (OECD.AI Policy Observatory)","year":2019,"url":"https://oecd.ai/en/dashboards/ai-principles/P7","locator":"Principle 1.3, third indent","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Paragraph 3.48, ''Policy for explanation'' (p. 53)","access":"free"},{"title":"Counterfactual Explanations without Opening the Black Box: Automated Decisions and the GDPR","publisher":"Wachter, Mittelstadt and Russell, arXiv:1711.00399 (Harvard Journal of Law & Technology, 2018)","year":2017,"url":"https://arxiv.org/abs/1711.00399","locator":"Abstract","access":"free"},{"title":"Explainable Machine Learning in Deployment","publisher":"Bhatt et al., arXiv:1909.06342 (ACM FAT* 2020)","year":2019,"url":"https://arxiv.org/abs/1909.06342","locator":"Abstract","access":"free"},{"title":"Fooling LIME and SHAP: Adversarial Attacks on Post hoc Explanation Methods","publisher":"Slack, Hilgard, Jia, Singh and Lakkaraju, arXiv:1911.02508","year":2019,"url":"https://arxiv.org/abs/1911.02508","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
