insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.4', '["**What it measures.** Whether a person affected by a significant automated decision can put their side, have a person look at it again and challenge the outcome, by a route that works in practice.","**Why it matters.** Even an accurate system gets individual cases wrong, and the person affected may be the only one placed to see the error. Without a working route, someone refused credit, a job or a service carries a mistake they cannot correct, with nobody answerable to them.","**The UK position.** Since February 2026 the UK GDPR requires safeguards wherever a significant decision is taken solely by automated processing of personal data: information about the decision, and the means to make representations, obtain human intervention and contest it. The Information Commission''s (ICO) draft guidance, still a consultation draft, says of human intervention: \"You must ensure this involves a review of the decision, with the possibility that you could change it.\" The reviewer needs discretion and authority to alter the decision. Spot checks do not count, because the review must be one the person can start.","**What good looks like.** People are told how to challenge when the decision is given; one simple route covers all three steps; the reviewer sees the original data and whatever the person adds; each review is recorded; outcomes are analysed and fed back into the system.","**Reading the answer.** A general complaints line that cannot reopen the decision is the usual gap. Frequent reversals may point to a fault in the system, not in the route.","**A defensible figure.** The organisation must act on such a request within one month, extendable by two further months for complex or numerous requests (UK GDPR Article 12A)."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and 22C(2)(b)-(d); textual amendment note F1","access":"free"},{"title":"UK GDPR, Articles 12 and 12A: time limits for acting on rights requests","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/chapter/III/section/1","locator":"Art. 12(3)-(4); Art. 12A(1), (3) and (4); textual amendment notes F4, F5, F20","access":"free"},{"title":"Automated decision-making, including profiling: What are the ADM safeguards? (draft guidance for consultation)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Sections ''How do we enable people to make representations?'', ''What is human intervention?'', ''How do we enable people to contest decisions?'' and ''What do we do if someone exercises their rights under the ADM provisions?''","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What steps should we take to fulfil rights related to automated decision-making?''","access":"free"},{"title":"Explaining decisions made with AI, Part 1: What goes into an explanation?","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-1-the-basics-of-explaining-ai/what-goes-into-an-explanation/","locator":"''Challenging a decision'' paragraphs under the rationale, responsibility, data and fairness explanations","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Section 3.2.3, box ''Principle: Contestability and redress''; Annex A","access":"free"},{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Art. 22A(1)(a) and (b)","access":"free"},{"title":"AI Update","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/publication/corporate/ai-update.pdf","locator":"Paragraphs 3.44 to 3.47, ''Contestability and redress'' (p. 18)","access":"free"},{"title":"Ethics, Transparency and Accountability Framework for Automated Decision-Making","publisher":"Department for Science, Innovation and Technology, Centre for Data Ethics and Innovation, Cabinet Office and Office for Artificial Intelligence","year":2023,"url":"https://www.gov.uk/government/publications/ethics-transparency-and-accountability-framework-for-automated-decision-making/ethics-transparency-and-accountability-framework-for-automated-decision-making","locator":"Point 5, ''Help users and citizens understand how it impacts them'', ''Context'' and ''Practical steps''","access":"free"},{"title":"Ensuring statistical models command public confidence: learning lessons from the approach to developing models for awarding grades in the UK in 2020","publisher":"Office for Statistics Regulation","year":2021,"url":"https://osr.statisticsauthority.gov.uk/publication/ensuring-statistical-models-command-public-confidence/","locator":"Executive summary, findings: ''Quality Assurance''; see also the principle on ''timing and grounds for appeal''","access":"free"},{"title":"Post Office Horizon IT Inquiry, Report Volume 1 (HC 1119)","publisher":"Post Office Horizon IT Inquiry (Sir Wyn Williams)","year":2025,"url":"https://www.postofficehorizoninquiry.org.uk/sites/default/files/2025-07/Post%20Office%20Horizon%20IT%20Inquiry%20Final%20Report%20Volume%201_0.pdf","locator":"Chapter 1, paragraph 1.4","access":"free"},{"title":"Use of automated decision-making by government: consultation paper","publisher":"Attorney-General''s Department, Australian Government","year":2024,"url":"https://consultations.ag.gov.au/integrity/adm/user_uploads/consultation-paper-use-of-automated-decision-making-by-government.pdf","locator":"Section on ''Merits review rights'' (pp. 30-31); Royal Commission recommendation 17.1 quoted in the introduction","access":"free"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","year":2021,"url":"https://www.unesco.org/en/legal-affairs/recommendation-ethics-artificial-intelligence","locator":"Paragraph 38 (Transparency and explainability)","access":"free"},{"title":"OECD AI Principles: Transparency and explainability (Principle 1.3)","publisher":"OECD (OECD.AI Policy Observatory)","year":2019,"url":"https://oecd.ai/en/dashboards/ai-principles/P7","locator":"Principle 1.3, final indent","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"MEASURE 3.3 (table of categories and subcategories for the MEASURE function)","access":"free"},{"title":"Conceptualising Contestability: Perspectives on Contesting Algorithmic Decisions","publisher":"Lyons, Velloso and Miller, arXiv:2103.01774","year":2021,"url":"https://arxiv.org/abs/2103.01774","locator":"Abstract","access":"free"},{"title":"The Flaws of Policies Requiring Human Oversight of Government Algorithms","publisher":"Green, arXiv:2109.05067 (Computer Law & Security Review, 2022)","year":2021,"url":"https://arxiv.org/abs/2109.05067","locator":"Abstract","access":"free"},{"title":"Contestable AI by Design: Towards a Framework","publisher":"Alfrink, Keller, Kortuem and Doorn, Minds and Machines 33, 613-639","year":2022,"url":"https://link.springer.com/article/10.1007/s11023-022-09611-z","locator":"Abstract","access":"free"},{"title":"The Right to Contest AI","publisher":"Kaminski and Urban, Columbia Law Review 121(7)","year":2021,"url":"https://columbialawreview.org/content/the-right-to-contest-ai/","locator":"Abstract on the journal''s page","access":"free"}]'::jsonb, '2026-10-05')
