insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.5', '["**What it measures.** Whether the ability to explain an AI system''s outputs is settled before the system is bought or built: written into the specification and the contract, and kept current.","**Why it matters.** A person refused a job, a loan or a service by a system nobody in the organisation can explain cannot be told why, and so cannot challenge a wrong or unfair result. The harm falls on that person, not the supplier. The regulator''s guidance is direct: \"you as the data controller have the primary responsibility for ensuring that the AI system you use is capable of producing an appropriate explanation for the decision recipient.\"","**The UK position.** Data protection law requires safeguards to be built in when the means of processing are chosen, not only afterwards. Where a significant decision is taken solely by automated means, the person must be given information about it and be able to make representations, obtain human intervention and contest it. Both duties sit with the organisation as controller. Regulator guidance, currently under review, says requirements should be specified at the procurement stage; government buyers are told to put explainability in the invitation to tender.","**What good looks like.** Explainability as a selection criterion; supplier documentation obtained before adoption and sufficient for the organisation''s own explanations; a contractual right to updates when the model changes; a recorded justification wherever an opaque model is chosen; the same standard for systems built in-house.","**Reading the answer.** The usual weak point is a tool chosen on accuracy and price, the explanation question first asked after a complaint.","**A defensible figure.** Of the widely used algorithmic techniques the regulator''s guidance lists, it classes 11 as largely interpretable and four as broadly opaque."]'::jsonb, false, '[{"title":"Explaining decisions made with AI, Part 3: Organisational roles and functions for explaining AI","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-3-what-explaining-ai-means-for-your-organisation/organisational-roles-and-functions-for-explaining-ai/","locator":"Section ''What if we use an AI system supplied by a third party?''","access":"free"},{"title":"Explaining decisions made with AI, Part 2, Task 3: Build your system to ensure you are able to extract relevant information","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-2-explaining-ai-in-practice/task-3-build/","locator":"Sections ''Select an appropriately explainable model'' and ''What types of models are we choosing between?''","access":"free"},{"title":"UK GDPR, Article 25: Data protection by design and by default","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/25","locator":"Art. 25(1)","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1)-(2); read with Art. 22A(1)-(2)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''Outsourcing and third-party AI systems''","access":"free"},{"title":"Guidelines for AI procurement","publisher":"Office for Artificial Intelligence","year":2020,"url":"https://www.gov.uk/government/publications/guidelines-for-ai-procurement/guidelines-for-ai-procurement","locator":"Top 10 considerations, no. 8 ''Avoid Black Box algorithms and vendor lock in''; section on drafting the invitation to tender","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 13: Transparency and provision of information to deployers","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-13","locator":"Art. 13(1); see also 13(2)-(3) on instructions for use","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Contracts and third parties","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/contracts-and-third-parties/","locator":"Control measure ''Before procuring AI systems, datasets or coding, there has been appropriate due diligence...'', list ''Ways to meet our expectations''","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 3.5 ''Model development documentation'', point (a), PDF p.24; see also Principle 2.6 on vendor models","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Executive summary, ''Understanding of AI systems'' and ''Third-party exposure''","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Section ''Transparency and explainability'' (under using AI safely and responsibly)","access":"free"},{"title":"Commentary: Model Contractual Clauses for the public procurement of AI (MCC-AI)","publisher":"European Commission, Public Buyers Community (Community of Practice on Public Procurement of AI)","year":2025,"url":"https://public-buyers-community.ec.europa.eu/system/files/2025-05/Commentary.pdf","locator":"Section 1 (Background), PDF p.3; Article 14 commentary, PDF pp.11-12","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 3.5 ''Explainable and Interpretable'', p.16 (PDF p.21); Table 3, MEASURE 2.9; Table 1, GOVERN 6","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Info-communications Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Section 3 ''Operations management'', ''Explainability'', paras 3.26 onwards, PDF p.45","access":"free"},{"title":"Stop Explaining Black Box Machine Learning Models for High Stakes Decisions and Use Interpretable Models Instead","publisher":"Cynthia Rudin (arXiv; published in Nature Machine Intelligence, 2019)","year":2019,"url":"https://arxiv.org/abs/1811.10154","locator":"Abstract","access":"free"},{"title":"Model Cards for Model Reporting","publisher":"Margaret Mitchell and others (arXiv; published in Proceedings of FAT* 2019)","year":2019,"url":"https://arxiv.org/abs/1810.03993","locator":"Abstract","access":"free"},{"title":"The 2024 Foundation Model Transparency Index","publisher":"Rishi Bommasani and others, Stanford Center for Research on Foundation Models (arXiv)","year":2024,"url":"https://arxiv.org/abs/2407.12929","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
