insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.6', '["**What it measures.** Whether the organisation can describe its own AI: a complete, current record of each system: purpose, a plain summary of how it works, data used, named owner.","**Why it matters.** Every explanation given to a customer, employee or regulator draws on what the organisation knows about itself. Where that is partial, people are told things nobody has checked, and faults go uncorrected in systems nobody knows are there. The regulator''s audit framework for AI states the risk: \"Without fully understanding how information is processed, neither provider nor deployer can assure themselves that they have an effective information governance regime in place.\"","**The UK position.** No UK law requires an AI register by name. Data protection law comes closest: a controller must keep a written record of its processing of personal data, including purposes and categories of data, though not how a system works or who owns it. Central government goes further: since February 2024 departments must publish a record of each algorithmic tool that significantly influences decisions affecting the public. For listed companies, the governance code asks boards to declare whether material controls are effective, for financial years beginning from 1 January 2026.","**What good looks like.** One register covering every system, including tools staff adopted without approval, written so the owner can explain each entry aloud, reviewed on a set cycle and independently checked.","**Reading the answer.** The usual weak points are knowledge held in individuals'' heads and unapproved tools no register sees.","**A defensible figure.** The record-keeping duty applies in full at 250 or more staff; smaller organisations are exempt only where processing is occasional, poses no likely risk to people''s rights and involves no special category or criminal offence data."]'::jsonb, false, '[{"title":"UK GDPR, Article 30: Records of processing activities","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/30","locator":"Art. 30(1), (3), (4), (5)","access":"free"},{"title":"UK GDPR, Article 5: Principles relating to processing of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/5","locator":"Art. 5(2)","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Governance and accountability in AI","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/governance-and-accountability-in-ai/","locator":"Control measure ''Information flows across the entire supply chain have been comprehensively mapped'', under ''Risk''","access":"free"},{"title":"Algorithmic Transparency Recording Standard (ATRS) Mandatory Scope and Exemptions Policy","publisher":"Government Digital Service","year":2024,"url":"https://www.gov.uk/government/publications/algorithmic-transparency-recording-standard-mandatory-scope-and-exemptions-policy/algorithmic-transparency-recording-standard-atrs-mandatory-scope-and-exemptions-policy","locator":"Sections 2 (Introduction), 3.1 (Overall scope) and 4.2","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Provision 29 and footnote 9 (PDF p. 14); application paragraph in the Introduction (PDF p. 6)","access":"free"},{"title":"The hidden risks of shadow AI","publisher":"National Cyber Security Centre","year":2026,"url":"https://www.ncsc.gov.uk/blogs/the-hidden-risks-of-shadow-ai","locator":"Sections ''What is shadow AI?'' and ''What are the cyber security risks of shadow AI?''","access":"free"},{"title":"Use of artificial intelligence in government (HC 612, Session 2023-24)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Part One, para 1.10 (PDF p.22); see also para 3.20 on the transparency standard","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 1.2 ''Model inventory'', points (a)-(b), PDF pp.11-12","access":"free"},{"title":"Data protection audit framework, Accountability toolkit: Records of processing and lawful basis","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/accountability/records-of-processing-and-lawful-basis/","locator":"First control measure (''Comprehensive data mapping exercises are carried out...''), ''Risk'' and ''Ways to meet our expectations''","access":"free"},{"title":"AI Management Essentials tool","publisher":"Department for Science, Innovation and Technology","year":2026,"url":"https://www.gov.uk/government/consultations/ai-management-essentials-tool/ai-management-essentials-tool-accessible","locator":"Section 1 ''AI system record'', questions 1.1 onwards and the definition that follows","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 6 ''Owner and responsibility (Tier 2)''","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Governance section, ''Creating an AI systems inventory''","access":"free"},{"title":"PPN 017: Improving transparency of AI use in procurement","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-017-improving-transparency-of-ai-use-in-procurement/ppn-017-improving-transparency-of-ai-use-in-procurement-html","locator":"Paragraph 11 and Annex B (example disclosure questions)","access":"free"},{"title":"AI Adoption Research","publisher":"Department for Science, Innovation and Technology","year":2026,"url":"https://www.gov.uk/government/publications/ai-adoption-research/ai-adoption-research","locator":"Executive summary, methodology paragraph (3,500 telephone interviews, 12 February to 2 May 2025)","access":"free"},{"title":"M-25-21, Accelerating Federal Use of AI through Innovation, Governance, and Public Trust","publisher":"Executive Office of the President, Office of Management and Budget (United States)","year":2025,"url":"https://www.whitehouse.gov/wp-content/uploads/2025/02/M-25-21-Accelerating-Federal-Use-of-AI-through-Innovation-Governance-and-Public-Trust.pdf","locator":"Section 3, item ''v. Update AI Use Case Inventories'', PDF p.12","access":"free"},{"title":"Closing the AI Accountability Gap: Defining an End-to-End Framework for Internal Algorithmic Auditing","publisher":"Inioluwa Deborah Raji and others (arXiv; published in Proceedings of FAT* 2020)","year":2020,"url":"https://arxiv.org/abs/2001.00973","locator":"Abstract","access":"free"},{"title":"Trust, attitudes and use of artificial intelligence: A global study 2025","publisher":"University of Melbourne and KPMG International","year":2025,"url":"https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/2025/05/trust-attitudes-and-use-of-ai-global-report.pdf","locator":"Section on AI use at work, text accompanying Figure 44 (PDF p.77)","access":"free"}]'::jsonb, '2026-10-02')
