insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.7', '["**What it measures.** Whether people are told, promptly and plainly, that a significant decision about them was made by a machine, and what they can do about it.","**Why it matters.** A person who does not know a system refused their loan, job application or claim cannot ask for a human to look again, correct a wrong fact or challenge the result. The decision stands because nobody knew to question it; those least able to push back lose most.","**The UK position.** Since 5 February 2026, where a significant decision is taken solely by automated processing of personal data, the controller must have safeguards that \"provide the data subject with information about decisions described in paragraph 1 taken in relation to the data subject\". This adds to the privacy notice, which must already disclose, in plain language, that such decision-making exists. The Information Commissioner''s Office, in draft guidance not yet final, reads the safeguard as information about the actual decision, given with the outcome, with the routes to human review and challenge. The EU AI Act separately requires deployers of certain high-risk systems to tell people they are subject to them.","**What good looks like.** A notice with each decision: that it was automated, which factors counted, and how to seek review. Coverage is counted and the wording tested with real readers.","**Reading the answer.** A line in the terms and conditions is the usual weak answer. The regulator found employers treating a privacy notice as enough and telling candidates nothing about their own decision.","**A defensible figure.** In 2025 the regulator contacted 37 employers it thought likely to be using automated recruitment tools, and concluded that 16 were likely to be making automated decisions about candidates."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and (2)(a); note F1","access":"free"},{"title":"UK GDPR, Article 13: Information to be provided where personal data are collected from the data subject","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/13","locator":"Art. 13(1) and 13(2)(f); note F7","access":"free"},{"title":"Automated decision-making, including profiling: What are the ADM safeguards?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Section ''What ''information about decisions'' do we have to provide?''","access":"free"},{"title":"Recruitment rewired: Transparency and safeguards","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/transparency-and-safeguards/","locator":"Sections ''Our findings about transparency and safeguards'' and ''Discussion''","access":"free"},{"title":"Recruitment rewired: Introduction","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/introduction-what-is-adm-and-why-are-we-focusing-on-it-in-recruitment/","locator":"Section ''How we''ve examined automated recruitment practices''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(11)","access":"free"},{"title":"UK GDPR, Article 12: Transparent information, communication and modalities for the exercise of the rights of the data subject","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/12","locator":"Art. 12(1); note F1","access":"free"},{"title":"Data Protection Act 2018, section 50C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/50C","locator":"s.50C(1)-(4); note F1","access":"free"},{"title":"Automated decision-making, including profiling: What rights do people have?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-rights-do-people-have/","locator":"Sections ''What do we need to tell people under the ADM safeguards?'' and ''How should we deliver the information?''","access":"free"},{"title":"AI tools in recruitment: Audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"Executive summary, ''Recommendation: Transparency and explainability'', PDF p.7","access":"free"},{"title":"Guidelines on Automated individual decision-making and Profiling for the purposes of Regulation 2016/679 (WP251rev.01)","publisher":"Article 29 Data Protection Working Party","year":2018,"url":"https://ec.europa.eu/newsroom/article29/redirection/document/49826","locator":"Chapter IV, section E ''Right to be informed'', PDF p.25","access":"free"},{"title":"Ethics, Transparency and Accountability Framework for Automated Decision-Making","publisher":"Department for Science, Innovation and Technology, Centre for Data Ethics and Innovation, Cabinet Office and Office for Artificial Intelligence","year":2023,"url":"https://www.gov.uk/government/publications/ethics-transparency-and-accountability-framework-for-automated-decision-making/ethics-transparency-and-accountability-framework-for-automated-decision-making","locator":"Point 5, ''Help users and citizens understand how it impacts them''","access":"free"},{"title":"OECD AI Principles: Transparency and explainability (Principle 1.3)","publisher":"Organisation for Economic Co-operation and Development","year":2024,"url":"https://oecd.ai/en/dashboards/ai-principles/P7","locator":"Principle 1.3, second and fourth indents","access":"free"},{"title":"''It''s Reducing a Human Being to a Percentage''; Perceptions of Justice in Algorithmic Decisions","publisher":"Reuben Binns and others (arXiv; published in Proceedings of CHI 2018)","year":2018,"url":"https://arxiv.org/abs/1801.10408","locator":"Abstract","access":"free"},{"title":"Counterfactual Explanations without Opening the Black Box: Automated Decisions and the GDPR","publisher":"Sandra Wachter, Brent Mittelstadt and Chris Russell (arXiv; published in Harvard Journal of Law & Technology, 2018)","year":2018,"url":"https://arxiv.org/abs/1711.00399","locator":"Abstract","access":"free"},{"title":"How do people feel about AI? 2025 survey: Key findings","publisher":"Ada Lovelace Institute and The Alan Turing Institute","year":2025,"url":"https://attitudestoai.uk/findings-2025/key-findings","locator":"Key findings, paragraph on laws, regulation and appeal procedures; methodology page for the sample","access":"free"}]'::jsonb, '2026-10-02')
