insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.8', '["**What it measures.** Whether public statements about the organisation''s AI (marketing, bids, investor material, the annual report) are checked against what the systems really do before publication, and who signs that off.","**Why it matters.** An overstated AI claim is an untruth told to people who cannot check it. Customers pay for a capability that is not there, investors price the company on it, and people are told a human reviews decisions when none does. The harm is to their ability to choose on accurate information.","**The UK position.** No rule is specific to AI; the general law on misleading statements applies. For consumers, unfair commercial practices are prohibited, including an overall presentation likely to deceive even where each statement is true. Since 6 April 2025 the Competition and Markets Authority can itself fine up to £300,000 or, if higher, 10% of turnover. Misleading advertising to business buyers is a separate criminal offence. The advertising regulator''s advice on AI products: \"Hold evidence to back up any objective claims about what your product can do\". Issuers of traded securities must compensate investors for published statements a senior manager knew were misleading, or was reckless about.","**What good looks like.** Each claim traced to evidence before release, a named sign-off, re-checks as systems change, published corrections, and independent assurance at the top level.","**Reading the answer.** Claims about governance (audited, human-reviewed, compliant) are the easiest to disprove from the organisation''s own records. A claim true at publication can become false after a system change.","**A defensible figure.** The Advertising Standards Authority identified around 16,000 unique online adverts using AI as a marketing term between July and September 2024; 68% were for business-to-business products."]'::jsonb, false, '[{"title":"Digital Markets, Competition and Consumers Act 2024, section 226: Misleading actions","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/226","locator":"s.226(1)-(3); read with s.225(1), (3)-(4) and s.227","access":"free"},{"title":"Digital Markets, Competition and Consumers Act 2024, section 182: Final infringement notice","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/182","locator":"s.182(1)-(2), (6), (8)","access":"free"},{"title":"Regulating the Illusion of Intelligence in Ads","publisher":"Committee of Advertising Practice (ASA | CAP)","year":2026,"url":"https://www.asa.org.uk/news/regulating-the-illusion-of-intelligence-in-ads.html","locator":"Section ''Human Advice vs Machine Learning'' (CAP News, 27 Aug 2026)","access":"free"},{"title":"''AI'' as a Marketing Term: A Quantitative Review of Usage in UK Advertising","publisher":"Advertising Standards Authority","year":2024,"url":"https://asa.org.uk/static/eb77bee0-a147-49b8-81856c3c83586bf2/AI-as-a-Marketing-Term-Report.pdf","locator":"pp. 3-5","access":"free"},{"title":"The Business Protection from Misleading Marketing Regulations 2008, regulation 3","publisher":"legislation.gov.uk","year":2008,"url":"https://www.legislation.gov.uk/uksi/2008/1276/regulation/3","locator":"reg.3(1)-(4); offence at reg.6","access":"free"},{"title":"Financial Services and Markets Act 2000, Schedule 10A: Liability of issuers in connection with published information","publisher":"legislation.gov.uk","year":2000,"url":"https://www.legislation.gov.uk/ukpga/2000/8/schedule/10A","locator":"paras 1-3 (given effect by s.90A)","access":"free"},{"title":"Companies Act 2006, section 463: Liability for false or misleading statements in reports and statements","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/463","locator":"s.463(1)-(4)","access":"free"},{"title":"Economic Crime and Corporate Transparency Act 2023, section 199: Failure to prevent fraud","publisher":"legislation.gov.uk","year":2023,"url":"https://www.legislation.gov.uk/ukpga/2023/56/section/199","locator":"s.199(1), (4); commencement note I2; fraud offences listed in Schedule 13","access":"free"},{"title":"Unfair commercial practices (CMA207)","publisher":"Competition and Markets Authority","year":2025,"url":"https://www.gov.uk/government/publications/unfair-commercial-practices-cma207/unfair-commercial-practices","locator":"Chapter ''Misleading actions'', ''Misleading action type 2: Overall deceptive presentation'' and its example","access":"free"},{"title":"UK Code of Non-broadcast Advertising and Direct & Promotional Marketing (CAP Code), Section 3: Misleading advertising","publisher":"Committee of Advertising Practice (ASA | CAP)","year":2026,"url":"https://www.asa.org.uk/type/non_broadcast/code_section/03.html","locator":"Rules 3.1 and 3.7 (Substantiation)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 4, Principles M and N (PDF p.13); Provision 25 on the audit committee''s review","access":"free"},{"title":"Alan Bates and Others v Post Office Limited, Judgment (No.6) ''Horizon Issues'' [2019] EWHC 3408 (QB)","publisher":"High Court of Justice, Queen''s Bench Division (Courts and Tribunals Judiciary)","year":2019,"url":"https://www.judiciary.uk/wp-content/uploads/2022/07/bates-v-post-office-judgment-1.pdf","locator":"Paras 518-519, 529-533 and 936 (PDF p.160 for para 533)","access":"free"},{"title":"SEC Charges Two Investment Advisers with Making False and Misleading Statements About Their Use of Artificial Intelligence (press release 2024-36)","publisher":"U.S. Securities and Exchange Commission","year":2024,"url":"https://www.sec.gov/newsroom/press-releases/2024-36","locator":"Opening paragraphs and Chair''s statement","access":"free"},{"title":"FTC Announces Crackdown on Deceptive AI Claims and Schemes (Operation AI Comply)","publisher":"Federal Trade Commission","year":2024,"url":"https://www.ftc.gov/news-events/news/press-releases/2024/09/ftc-announces-crackdown-deceptive-ai-claims-schemes","locator":"Opening paragraphs and Chair''s statement","access":"free"},{"title":"Public Statement on the use of Artificial Intelligence (AI) in the provision of retail investment services (ESMA35-335435667-5924)","publisher":"European Securities and Markets Authority","year":2024,"url":"https://www.esma.europa.eu/sites/default/files/2024-05/ESMA35-335435667-5924__Public_Statement_on_AI_and_investment_services.pdf","locator":"Paragraph 8 (PDF p.4)","access":"free"},{"title":"Trusted third-party AI assurance roadmap","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/trusted-third-party-ai-assurance-roadmap/trusted-third-party-ai-assurance-roadmap","locator":"Introduction and the section on professionalisation (auditing)","access":"free"},{"title":"The Fallacy of AI Functionality","publisher":"Inioluwa Deborah Raji, I. Elizabeth Kumar, Aaron Horowitz and Andrew D. Selbst (arXiv; published in FAccT 2022)","year":2022,"url":"https://arxiv.org/abs/2206.09511","locator":"Abstract","access":"free"},{"title":"Are Companies Taking AI Risks Seriously? A Systematic Analysis of Companies'' AI Risk Disclosures in SEC 10-K forms","publisher":"Lucas G. Uberti-Bona Marin, Bram Rijsbosch, Gerasimos Spanakis and Konrad Kollnig (arXiv preprint; to appear in the ECML PKDD SoGood workshop proceedings)","year":2025,"url":"https://arxiv.org/abs/2508.19313","locator":"Abstract","access":"free"},{"title":"AI Washing and the Erosion of Digital Legitimacy: A Socio-Technical Perspective on Responsible Artificial Intelligence in Business","publisher":"Nelly Elsayed (arXiv preprint)","year":2026,"url":"https://arxiv.org/abs/