insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.2', '["**What it measures.** Whether the four safeguards the law attaches to significant, solely automated decisions exist as working processes, each with an owner, a route, a record and a test.","**Why it matters.** A right printed in a privacy notice that nobody is resourced to answer is a broken promise to someone just refused a job, a loan or a service. The mistake stands and nobody is answerable to that person.","**The UK position.** Article 22C of the UK GDPR puts the duty on the controller, which must ensure safeguards are in place: information about the decision, and the means to make representations, obtain human intervention and contest. Article 24 requires it to be able to demonstrate compliance. On recruitment, the Information Commission (ICO) reported: \"We also didn’t see widespread evidence that candidates were able to make representations, obtain human intervention or contest decisions.\" One employer told candidates of the right to human intervention but had no method for handling a request. Its guidance, still a consultation draft, says safeguards must be applied consistently, not at discretion.","**What good looks like.** A named person or team owns each route; a recorded process covers every decision in scope; requests and reviewer overrides are logged with reasons; the process is tested on a sample of cases; results reach senior management.","**Reading the answer.** Ask to see the log. An organisation that cannot show one request and who handled it has a policy, not a safeguard. Monitoring a system''s accuracy is not human intervention.","**A defensible figure.** A breach of Article 22C falls in the higher penalty tier: up to £17,500,000 or, for an undertaking, 4% of total worldwide annual turnover, whichever is higher (UK GDPR Article 83(5))."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and 22C(2)(a)-(d); note F1","access":"free"},{"title":"UK GDPR, Article 24: Responsibility of the controller","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/24","locator":"Art. 24(1); note F1 (Art. 24(3) amended 20 August 2025)","access":"free"},{"title":"UK GDPR, Article 83: General conditions for imposing administrative fines","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/83","locator":"Art. 83(5), point (ba); notes F8 and F10","access":"free"},{"title":"Data Protection Act 2018, section 146: Assessment notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/146","locator":"s.146(1) and (2)(a)-(k)","access":"free"},{"title":"Automated decision-making, including profiling: What are the ADM safeguards? (draft guidance for consultation)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Sections ''What are the safeguards in the ADM provisions?'', ''What is human intervention?'' and ''How do we enable people to contest decisions?''","access":"free"},{"title":"Automated decision-making, including profiling: What else do we need to consider? (draft guidance for consultation)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-else-do-we-need-to-consider/","locator":"Sections ''Do we have to do a data protection impact assessment (DPIA)?'' and ''Do we need to make any other changes to our systems?'', final paragraph","access":"free"},{"title":"Recruitment rewired: Transparency and safeguards","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/transparency-and-safeguards/","locator":"Section ''Our findings about transparency and safeguards'', sub-section ''Safeguards'', including the third case study (chatbot screening interviews), and ''Expectations''","access":"free"},{"title":"Data protection audit framework, Accountability toolkit: Information rights","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/accountability/information-rights/","locator":"Final control measure but one: ''People’s rights related to automated decision-making and profiling are protected''; also the control measures on resources, logging and monitoring of requests","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure, ''Ways to meet our expectations''; second control measure, ''Ways to meet our expectations'' and ''Options to consider''","access":"free"},{"title":"Guidelines on Automated individual decision-making and Profiling for the purposes of Regulation 2016/679 (WP251rev.01)","publisher":"Article 29 Data Protection Working Party (endorsed by the European Data Protection Board, 25 May 2018)","year":2018,"url":"https://ec.europa.eu/newsroom/article29/redirection/document/49826","locator":"Chapter IV, section F ''Establishing appropriate safeguards'', p.27; Annex 1 good practice recommendations, row ''Appropriate safeguards'', p.32","access":"free"},{"title":"Data Protection Act 2018, section 50C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/50C","locator":"s.50C(1), (2)(a)-(d) and (3)-(4); note F1","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section on completing Tier 2, ''What information is relevant for the appeals and review field?''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 3, MEASURE 3.3 (p. 30); see also Table 4, MANAGE 4.1 (p. 32)","access":"free"},{"title":"Regulation (EU) 2024/1689 (Artificial Intelligence Act), Article 86: Right to explanation of individual decision-making","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-86","locator":"Art. 86(1) to (3)","access":"free"},{"title":"Ensuring statistical models command public confidence: learning lessons from the approach to developing models for awarding grades in the UK in 2020","publisher":"Office for Statistics Regulation","year":2021,"url":"https://osr.statisticsauthority.gov.uk/publication/ensuring-statistical-models-command-public-confidence/","locator":"Executive summary, findings on quality assurance and on meeting the need; the full report is a download from the same page","access":"free"},{"title":"The Right to Contest AI","publisher":"Margot E. Kaminski and Jennifer M. Urban, Columbia Law Review vol. 121 no. 7","year":2021,"url":"https://columbialawreview.org/content/the-right-to-contest-ai/","locator":"Abstract and Introduction on the journal''s own page","access":"free"},{"title":"Conceptualising Contestability: Perspectives on Contesting Algorithmic Decisions","publisher":"Henrietta Lyons, Eduardo Velloso and Tim Miller, Proceedings of the ACM on Human-Computer Interaction (CSCW), authors'' copy on arXiv","year":2021,"url":"https://arxiv.org/abs/2103.01774","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
