insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.3', '["**What it measures.** Whether the organisation can name a valid legal ground for each use of personal data in its AI: training, the data fed in, and what the system says about people.","**Why it matters.** People whose records or images are absorbed into a model seldom know, so cannot object. Processing without a valid ground is unlawful, and the harm falls on people who never had a say.","**The UK position.** UK GDPR Article 6 lists the lawful bases; at least one must apply. The Information Commission (ICO), in guidance under review, says: \"You must break down and separate each distinct processing operation, and identify the purpose and an appropriate lawful basis for each one\". Legitimate interests requires a three-part test of purpose, necessity and balance. For training generative models on web-scraped data the regulator regards it as the only basis available, and hard to meet. Since 5 February 2026 a further basis, recognised legitimate interests, covers listed purposes such as crime prevention and emergencies; it may not support a significant decision taken solely by automated processing. Reuse that is compatible still needs its own basis.","**What good looks like.** A record per purpose showing the basis chosen before processing began, the balancing assessment where one is needed, and a fresh review whenever the purpose changes.","**Reading the answer.** Legitimate interests claimed for everything, with no assessment on file, is the usual weak answer; the regulator says it cannot be a default. A basis chosen after launch is another.","**A defensible figure.** In May 2022 the regulator fined a facial recognition company £7,552,800 for, among other failings, scraping people''s images with no lawful basis. At its last update, in December 2025, the case was still before the courts."]'::jsonb, false, '[{"title":"UK GDPR, Article 6: Lawfulness of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/6","locator":"Art. 6(1)(a) to (f), 6(5) and 6(11); notes F3 and F14","access":"free"},{"title":"UK GDPR, Article 22B: Restrictions on automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22B","locator":"Art. 22B(4); note F1","access":"free"},{"title":"UK GDPR, Annex 1: Lawfulness of processing: recognised legitimate interests","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/annex/1","locator":"Annex 1, paras 1 to 8; note F1","access":"free"},{"title":"UK GDPR, Article 8A: Purpose limitation: further processing","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/8A","locator":"Art. 8A(2) and (3); note F1. Read with Art. 5(1)(b) and 5(3)","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure lawfulness in AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-lawfulness-in-ai/","locator":"Section ''What should we consider when deciding lawful bases?''; also ''How should we distinguish purposes between AI development and deployment?'' and ''Can we rely on legitimate interests?''","access":"free"},{"title":"Information Commissioner''s Office response to the consultation series on generative AI: The lawful basis for web scraping to train generative AI models","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/what-we-do/our-work-on-artificial-intelligence/response-to-the-consultation-series-on-generative-ai/the-lawful-basis-for-web-scraping-to-train-generative-ai-models/","locator":"''In brief'' box and section ''Our response''","access":"free"},{"title":"Legitimate interests: What is the ''legitimate interests'' basis?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/legitimate-interests/what-is-the-legitimate-interests-basis/","locator":"Section ''What is the three-part test?''","access":"free"},{"title":"A guide to lawful basis: Recognised legitimate interest","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/a-guide-to-lawful-basis/recognised-legitimate-interest/","locator":"''At a glance'' and section ''When can we use recognised legitimate interest?''","access":"free"},{"title":"Opinion 28/2024 on certain data protection aspects related to the processing of personal data in the context of AI models","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-12/edpb_opinion_202428_ai-models_en.pdf","locator":"Paras 60 and 66; executive summary pp. 2 to 3 (three-step test; scenarios on unlawfully trained models)","access":"free"},{"title":"Monetary Penalty Notice: Clearview AI Inc","publisher":"Information Commissioner''s Office","year":2022,"url":"https://ico.org.uk/media2/migrated/4020436/clearview-ai-inc-mpn-20220518.pdf","locator":"Para 3 (amount), para 4(ii) and para 68 (p. 29) on lawful basis","access":"free"},{"title":"Enforcement Notice: Serco Leisure Operating Limited","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/woalogoc/20240219-serco-leisure-operating-limited-en.pdf","locator":"Paras 29 to 33 and 39 (lawful basis); background sub-paragraph (e) on the timing of the legitimate interests assessment","access":"free"},{"title":"The Information Commissioner v Clearview AI Incorporated [2025] UKUT 319 (AAC)","publisher":"Upper Tribunal (Administrative Appeals Chamber)","year":2025,"url":"https://caselaw.nationalarchives.gov.uk/ukut/aac/2025/319","locator":"Summary of decision; Decision; the description of the system ending at para 43","access":"free"},{"title":"Guidelines 1/2024 on processing of personal data based on Article 6(1)(f) GDPR (version 1.0, for public consultation)","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-10/edpb_guidelines_202401_legitimateinterest_en.pdf","locator":"Para 9; executive summary, p. 2 (three cumulative conditions)","access":"free"},{"title":"Relying on the legal basis of legitimate interests to develop an AI system","publisher":"Commission Nationale de l''Informatique et des Libertés (CNIL)","year":2026,"url":"https://www.cnil.fr/en/relying-legal-basis-legitimate-interests-develop-ai-system","locator":"Opening summary; section on the three conditions (legitimate interest, necessity, balance)","access":"free"},{"title":"Guidance on privacy and developing and training generative AI models","publisher":"Office of the Australian Information Commissioner","year":2024,"url":"https://www.oaic.gov.au/privacy/privacy-guidance-for-organisations-and-government-agencies/guidance-on-privacy-and-developing-and-training-generative-ai-models","locator":"''Top five takeaways'', second and third points","access":"free"},{"title":"Advisory Guidelines on Use of Personal Data in AI Recommendation and Decision Systems","publisher":"Personal Data Protection Commission, Singapore","year":2024,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/advisory-guidelines/advisory-guidelines-on-the-use-of-personal-data-in-ai-recommendation-and-decision-systems.pdf","locator":"Part I, executive summary (p. 3); Part III, sections 4 to 6 (pp. 5-9)","access":"free"},{"title":"UK GDPR, Article 13: Information to be provided where personal data are collected from the data subject","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/13","locator":"Art. 13(1)(c) and (d)","access":"free"},{"title":"A Common Pool of Privacy Problems: Legal and Technical Lessons from a Large-Scale Web-Scraped Machine Learning Dataset","publisher":"Rachel Hong and five co-authors (University of Washington and others), arXiv","year":2025,"url":"https://arxiv.org/pdf/2506.17185","locator":"Section 7.3.1 ''Lawful basis / consent''; contributions list in section 1","access":"free"},{"title":"Generative AI in EU Law: Liability, Privacy, Intellectual Property, and Cybersecurity","publisher":"Claudio Novelli, Federico Casolari, Philipp Hacker, Giorgio Spedicato and Luciano Floridi, arXiv","year":2024,"url":"https://arxiv.org/pdf/2401.07348","locator":"Privacy and data protection section, list of seven problems and sub-section 1 ''Legal basis for AI training on personal data''","access":"free"}]'::jsonb, '2026-10-02')
