insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.4', '["**What it measures.** Whether data protection impact assessments are triggered when they should be, done in depth, and acted on: findings change the design, and the assessment is revisited when the system changes.","**Why it matters.** It is where someone must write down what an AI system could do to the people whose data it uses: the applicant wrongly screened out, the teenager confiding in a chatbot, the worker tracked. Done late or thinly, those people carry risks nobody weighed.","**The UK position.** UK GDPR Article 35 requires an assessment before any processing likely to result in a high risk to people. The Data (Use and Access) Act 2025 left that duty unchanged. The Information Commission (ICO) says the great majority of AI uses will meet the trigger; a decision not to assess must be documented. In 2024 the regulator said one firm''s early assessments of an AI chatbot contained \"a cursory and higher-level risk assessment, in tabular format\", with no reasons given. The controller must also review when the risk changes. Failure can bring a fine.","**What good looks like.** Every AI use screened; assessment begun early in design; risks described for the people affected, not the organisation; each mitigation owned and checked as working; senior sign-off; review on material change.","**Reading the answer.** Ask for the assessment''s date against the go-live date, and for one design change it caused. The regulator''s audit of AI recruitment tools found some assessments completed retrospectively, and most not regularly reviewed after launch.","**A defensible figure.** In the chatbot case the regulator saw five versions. It described the first four as cursory on risk and accepted the fifth, dated 22 November 2023, almost nine months after launch on 27 February 2023."]'::jsonb, false, '[{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1), (3), (7), (11)","access":"free"},{"title":"UK GDPR, Article 83: General conditions for imposing administrative fines","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/83","locator":"Art. 83(4)(a)","access":"free"},{"title":"Data protection impact assessments: What is a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/what-is-a-dpia/","locator":"Section ''How are DPIAs used?''","access":"free"},{"title":"Data protection impact assessments: When do we need to do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/when-do-we-need-to-do-a-dpia/","locator":"Sections ''What other factors might indicate likely high risk?'' and ''What does the ICO consider likely to result in high risk?''","access":"free"},{"title":"Data protection impact assessments: How do we do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/how-do-we-do-a-dpia/","locator":"Sections ''Step 7: How do we conclude our DPIA?'' and ''What happens next?''","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''What do we need to consider when undertaking data protection impact assessments for AI?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"''DPIAs and risk management'', pp. 34-37","access":"free"},{"title":"Decision of the Information Commissioner: Snap Inc. and Snap Group Limited","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4029988/snap-my-ai-non-confidential-decision-21-may-2024-20240619-redacted.pdf","locator":"Paras 1-8, 28, 31, 123-124 and 153","access":"free"},{"title":"Guidelines on Data Protection Impact Assessment (DPIA) and determining whether processing is \"likely to result in a high risk\" for the purposes of Regulation 2016/679 (WP 248 rev.01)","publisher":"Article 29 Data Protection Working Party (European Commission)","year":2017,"url":"https://ec.europa.eu/newsroom/just/document.cfm?doc_id=47711","locator":"Section III.D(a), p. 14; nine criteria at pp. 9-11; Annex 2 (criteria for an acceptable DPIA)","access":"free"},{"title":"Regulation (EU) 2024/1689 (Artificial Intelligence Act), Article 27: Fundamental rights impact assessment for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-27","locator":"Art. 27(1), (2), (4)","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division)","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"Ground 3, paras 145 to 154; quote at para 153; order, para 1","access":"free"},{"title":"Data Protection Act 2018, section 64: Data protection impact assessment","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/64","locator":"s.64(1) to (4)","access":"free"},{"title":"UK GDPR, Article 36: Prior consultation","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/36","locator":"Art. 36(1) and (2)","access":"free"},{"title":"Age appropriate design: a code of practice for online services. 2. Data protection impact assessments","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/childrens-information/childrens-code-guidance-and-resources/age-appropriate-design-a-code-of-practice-for-online-services/2-data-protection-impact-assessments/","locator":"Standard 2, opening statement and ''What do you mean by a DPIA?''; ''When do we need to do a DPIA?''","access":"free"},{"title":"Reprimand: Chelmer Valley High School","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4030350/20240702-cvhs-reprimand.pdf","locator":"Paras 1.2, 1.5 to 1.9 and 2.3 to 2.4","access":"free"},{"title":"Carrying out a data protection impact assessment if necessary (AI how-to sheets)","publisher":"Commission Nationale de l''Informatique et des Libertés (CNIL)","year":2024,"url":"https://www.cnil.fr/en/carrying-out-protection-impact-assessment-if-necessary","locator":"Introduction and section ''The realisation of a DPIA for the development of AI systems''","access":"free"},{"title":"Guide to undertaking privacy impact assessments","publisher":"Office of the Australian Information Commissioner","year":2021,"url":"https://www.oaic.gov.au/privacy/privacy-guidance-for-organisations-and-government-agencies/privacy-impact-assessments/guide-to-undertaking-privacy-impact-assessments","locator":"Section ''When to do a PIA''; footnote 3 on the Australian Government Agencies Privacy Code","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 2, MAP 5 and MAP 5.1 (p. 26)","access":"free"},{"title":"Fairness and Data Protection Impact Assessments","publisher":"Atoosa Kasirzadeh and Damian Clifford, AIES ''21: Proceedings of the 2021 AAAI/ACM Conference on AI, Ethics, and Society (authors'' copy on arXiv)","year":2021,"url":"https://arxiv.org/abs/2109.06309","locator":"Abstract","access":"free"},{"title":"An Institutional View of Algorithmic Impact Assessments","publisher":"Andrew D. Selbst, Harvard Journal of Law & Technology vol. 35 no. 1","year":2021,"url":"https://jolt.law.harvard.edu/assets/articlePDFs/v35/Selbst-An-Institutional-View-of-Algorithmic-Impact-Assessments.pdf","locator":"Abstract, p. 117 of the volume (first page of the PDF)","access":"free"},{"title":"Towards An Automated AI Act FRIA Tool That Can Reuse GDPR''s DPIA","publisher":"Tytti Rintamaki and Harshvardhan J. Pandit, arXiv (presented at the CLAIRvoyant workshop 2024)","year":2024,"url":"https://arxiv.org/abs/2501.14756","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
