insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.5', '["**What it measures.** Whether the organisation knows where sensitive personal data enters its AI systems (at collection, in training data and in what a system infers) and whether each use rests on a documented lawful condition.","**Why it matters.** Health, ethnicity, religion, politics, sexual orientation and a person''s face or fingerprint are the facts most easily used to exclude or expose them. A system can infer them from ordinary data without anyone deciding it should. The harm falls on the person profiled, who is rarely told.","**The UK position.** Article 9 of the UK GDPR prohibits processing special category data unless one of ten exceptions applies. Several also need a condition in Schedule 1 to the Data Protection Act 2018, many requiring an appropriate policy document. The Information Commission (ICO) says: \"If your purpose is not covered by any of the conditions, and you cannot obtain valid explicit consent, you cannot process the special category data.\" Biometric data is caught when used to identify someone. An inference is caught where the organisation intends to draw it, or to treat someone differently because of it. Criminal offence data has separate, similar rules. The ICO''s guidance is under review.","**What good looks like.** Every sensitive data flow mapped, including training data, inferences and supplier products; a named condition and policy document for each; technical blocks; an exceptions log the board reviews.","**Reading the answer.** Deleting a labelled field is not compliance if the inference remains. Consent is weak where people cannot refuse, as at work.","**A defensible figure.** In February 2024 the ICO ordered Serco Leisure to stop using facial recognition and fingerprint scanning to record attendance: 2,283 employees across 38 facilities, with no valid condition and no appropriate policy document."]'::jsonb, false, '[{"title":"UK GDPR, Article 9: Processing of special categories of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/9","locator":"Art. 9(1), 9(2)(a)-(j), 9(5); notes F1-F19","access":"free"},{"title":"UK GDPR, Article 11A: Further provision about processing of special categories of personal data","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/11A","locator":"Art. 11A(1)-(4); note F1","access":"free"},{"title":"Data Protection Act 2018, Schedule 1, Part 4: Appropriate policy document and additional safeguards","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/schedule/1/part/4","locator":"Sch. 1 paras 38-41; read with s.10 and Sch. 1 paras 1 and 5","access":"free"},{"title":"Special category data: What are the rules on special category data?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/special-category-data/what-are-the-rules-on-special-category-data/","locator":"Sections ''What does the UK GDPR say?'', ''How do the conditions work?'', ''What does ''necessary'' mean?'', ''Do we need to do a DPIA?''","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure lawfulness in AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-lawfulness-in-ai/","locator":"Sections ''What about special category data and data about criminal offences?'' and ''Using AI systems to make inferences'' (page updated 28 October 2024)","access":"free"},{"title":"Biometric data guidance: Biometric recognition. How do we process biometric data lawfully?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/biometric-data-guidance-biometric-recognition/how-do-we-process-biometric-data-lawfully/","locator":"''At a glance''; sections ''Can we use consent and explicit consent?'' and ''How do we determine our lawful basis and special category condition?''","access":"free"},{"title":"Enforcement Notice: Serco Leisure Operating Limited","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/woalogoc/20240219-serco-leisure-operating-limited-en.pdf","locator":"paras 17, 26(i)-(j), 27, 34-38 (pp. 7, 11-12, 15-16); Annex 1","access":"free"},{"title":"The Information Commissioner v Clearview AI Incorporated [2025] UKUT 319 (AAC)","publisher":"Upper Tribunal (Administrative Appeals Chamber)","year":2025,"url":"https://caselaw.nationalarchives.gov.uk/ukut/aac/2025/319","locator":"Summary of decision; Decision; paras 8-9, 367","access":"free"},{"title":"The Ryder Review: Independent legal review of the governance of biometric data in England and Wales","publisher":"Ada Lovelace Institute","year":2022,"url":"https://www.adalovelaceinstitute.org/report/ryder-review-biometrics/","locator":"Chapter 2 (Executive summary and recommendations), Recommendations 1-2; Chapter 5, ''Data protection law''","access":"free"},{"title":"Opinion 28/2024 on certain data protection aspects related to the processing of personal data in the context of AI models","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-12/edpb_opinion_202428_ai-models_en.pdf","locator":"para 17, first bullet (p.10), with footnotes 11-13","access":"free"},{"title":"UK GDPR, Article 10: Processing of personal data relating to criminal convictions and offences","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/10","locator":"Art. 10(1)-(2); notes F1-F5","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division)","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"paras 48-50, 155-162, 209; Annex A paras 25-28","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"p. 22 (example on inferred characteristics); see also pp. 27 and 43","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 4a: Processing of special categories of personal data for bias detection and correction","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-4a","locator":"Art. 4a(1)(a)-(f) and 4a(2); all marked NEW","access":"free"},{"title":"A Right to Reasonable Inferences: Re-Thinking Data Protection Law in the Age of Big Data and AI","publisher":"Oxford University Research Archive (S. Wachter and B. Mittelstadt; Columbia Business Law Review 2019(2))","year":2019,"url":"https://ora.ox.ac.uk/objects/uuid:d53f7b6a-981c-4f87-91bc-743067d10167/files/m11a3a4ceea760eb2cd96110e6e823a5f","locator":"Abstract, journal p. 495 (PDF p. 2); Part V.D ''Protections Against Sensitive Inferences'', pp. 560-568","access":"free"},{"title":"Using sensitive data to prevent discrimination by artificial intelligence: Does the GDPR need a new exception?","publisher":"arXiv (M. van Bekkum and F. Zuiderveen Borgesius)","year":2022,"url":"https://arxiv.org/abs/2206.03262","locator":"Abstract (version 3, 28 November 2022)","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.6', '["**What it measures.** Whether data fed to AI systems meets a written standard: relevant to the purpose, representative of the people decided about, accurate, and no more than the purpose requires.","**Why it matters.** Every unnecessary field can leak, be misused or tilt a decision; out-of-date records produce wrong outcomes for people. The Information Commission (ICO) is blunt: \"You must not collect personal data on the off-chance that it might be useful in the future\". The opposite failure harms too: strip out too much and a system may serve some groups worse than others.","**The UK position.** UK GDPR Article 5 requires personal data to be adequate, relevant and limited to what is necessary; accurate and, where necessary, kept up to date; and kept in identifiable form no longer than necessary. Article 25 requires that, by default, only data necessary for each purpose is processed. Adequacy cuts both ways: enough data, and no more. ICO guidance, under review since the Data (Use and Access) Act 2025, accepts that minimisation may need balancing against statistical accuracy and non-discrimination. These duties cover personal data only.","**What good looks like.** For each system, a written list of data fields allowed in and kept out, with reasons; a retention schedule with evidence of deletion; checks that data stays current and representative; quality measures tracked with alerts and passed to fairness testing.","**Reading the answer.** Cleaning data only when errors cost money scores low. Ask who decided what each system needs, and when anything was last deleted.","**A defensible figure.** The regulator''s 2024 audits of AI recruitment tools found candidate data was usually kept for one or two years after the vacancy closed (page 15); several providers meant to keep their databases indefinitely."]'::jsonb, false, '[{"title":"UK GDPR, Article 5: Principles relating to processing of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/5","locator":"Art. 5(1)(c) data minimisation, 5(1)(d) accuracy, 5(1)(e) storage limitation, 5(2) accountability","access":"free"},{"title":"UK GDPR, Article 25: Data protection by design and by default","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/25","locator":"Art. 25(1)-(2)","access":"free"},{"title":"Guidance on AI and data protection: How should we assess security and data minimisation in AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-should-we-assess-security-and-data-minimisation-in-ai/","locator":"Sections ''What considerations about the data minimisation principle do we need to make?'', ''How should we minimise personal data in the training stage?'', ''How should we balance data minimisation and statistical accuracy?''","access":"free"},{"title":"Guidance on AI and data protection: What do we need to know about accuracy and statistical accuracy?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-do-we-need-to-know-about-accuracy-and-statistical-accuracy/","locator":"Sections ''What is the difference between accuracy in data protection law and statistical accuracy in AI?'' and ''What should we do about statistical accuracy post-deployment?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 13-17, ''Data minimisation and purpose limitation''","access":"free"},{"title":"Data protection audit framework, artificial intelligence toolkit: Data minimisation","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/data-minimisation/","locator":"Three control measures: review of relevance at each stage; ongoing monitoring and testing; documented retention policy and schedule","access":"free"},{"title":"A guide to the data protection principles. Principle (c): Data minimisation","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/data-protection-principles/a-guide-to-the-data-protection-principles/data-minimisation/","locator":"''At a glance''; sections ''How do we decide what is adequate, relevant and limited?'' and ''When could we be processing inadequate personal data?''","access":"free"},{"title":"Information Commissioner''s Office response to the consultation series on generative AI: Accuracy of training data and model outputs","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/what-we-do/our-work-on-artificial-intelligence/response-to-the-consultation-series-on-generative-ai/accuracy-of-training-data-and-model-outputs/","locator":"Sections ''Original call for evidence'' and ''Key points from the responses''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 3.6 ''Privacy-Enhanced'', p.17; see also MAP 2.3 (p.27) and Appendix B (p.38)","access":"free"},{"title":"Operationalizing the Legal Principle of Data Minimization for Personalization","publisher":"arXiv (paper in Proceedings of the 43rd International ACM SIGIR Conference); A. J. Biega, P. Potash, H. Daumé III, F. Diaz, M. Finck","year":2020,"url":"https://arxiv.org/abs/2005.13718","locator":"Abstract","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 10: Data and data governance","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-10","locator":"Art. 10(1)-(4) and (6); para 5 shown as deleted","access":"free"},{"title":"Supervisory Statement SS1/23: Model risk management principles for banks","publisher":"Prudential Regulation Authority, Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 3.2 ''The use of data'' (a)-(c), PDF p. 21; Principle 2.3 ''Policies and procedures'' (data quality management procedures), PDF pp. 15-17; para 1.5","access":"free"},{"title":"The Government Data Quality Framework","publisher":"Government Data Quality Hub (UK Government)","year":2020,"url":"https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework","locator":"''Data quality principles'' 1-2; ''The data lifecycle''; ''Data quality dimensions''","access":"free"},{"title":"Use of artificial intelligence in government (HC 612)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"para 3.13, p. 36 (PDF p. 38); summary para 16, p. 10; paras 3.12-3.14","access":"free"},{"title":"Gender Shades: Intersectional Accuracy Disparities in Commercial Gender Classification","publisher":"Proceedings of Machine Learning Research, vol. 81 (J. Buolamwini and T. Gebru)","year":2018,"url":"https://proceedings.mlr.press/v81/buolamwini18a/buolamwini18a.pdf","locator":"Abstract, p. 1; Introduction, p. 2","access":"free"},{"title":"\"Everyone wants to do the model work, not the data work\": Data Cascades in High-Stakes AI","publisher":"Google Research (N. Sambasivan and others; ACM SIGCHI 2021)","year":2021,"url":"https://research.google/pubs/everyone-wants-to-do-the-model-work-not-the-data-work-data-cascades-in-high-stakes-ai/","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.7', '["**What it measures.** Whether the organisation can find, correct, delete or stop using a person''s data when they ask, including data in AI training sets, outputs, profiles and suppliers'' systems, within the legal time limit.","**Why it matters.** These rights are how a person checks what is held about them, corrects it and withdraws from uses they did not choose. If AI puts their data beyond the organisation''s reach, the right exists on paper only: the person stays profiled or wrongly described.","**The UK position.** The UK GDPR gives rights of access, rectification, erasure and objection, with no exception for AI. Since the Data (Use and Access) Act 2025, access extends to what a reasonable and proportionate search can find. Erasure and objection are not absolute, except objection to direct marketing. Guidance from the Information Commission (ICO), under review, says: \"When procuring an AI service, you must choose one which allows individual rights to be protected and enabled, in order to meet your obligations as a controller.\" The regulator has said output filters may not be enough, because they do not remove data from a model.","**What good looks like.** Rights procedures name each AI system and where its personal data sits; supplier contracts require help with requests; deletion and suppression routes are tested; turnaround and completeness are measured.","**Reading the answer.** The usual gap is a sound general process never tried against an AI system. Ask for the last request that touched one.","**A defensible figure.** No UK figure was found. In Europe, 764 controllers answered the European Data Protection Board''s 2025 coordinated action on erasure; the first recurring issue was no documented, current procedure for handling requests (report, pages 2 and 3)."]'::jsonb, false, '[{"title":"UK GDPR, Article 15: Right of access by the data subject","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/15","locator":"Art. 15(1)(h), 15(1A) and 15(3); textual amendment notes F4, F5 and F8","access":"free"},{"title":"UK GDPR, Article 17: Right to erasure (''right to be forgotten'')","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/17","locator":"Art. 17(1)(a)-(g), 17(2) and 17(3)","access":"free"},{"title":"UK GDPR, Article 21: Right to object","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/21","locator":"Art. 21(1)-(4); textual amendment note F1","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Sections ''How should we ensure individual rights requests for training data?'', ''How should we ensure individual rights requests for AI outputs?'' and ''How do individual rights relate to data contained in the model itself?''","access":"free"},{"title":"Response to the consultation series on generative AI: Engineering individual rights into generative AI models","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/our-work-on-artificial-intelligence/response-to-the-consultation-series-on-generative-ai/engineering-individual-rights-into-generative-ai-models/","locator":"Section ''Our response''; also ''In brief'' and ''Key points from the responses''","access":"free"},{"title":"Right of access: How do we find and retrieve the relevant information?","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/right-of-access/how-do-we-find-and-retrieve-the-relevant-information/","locator":"Sections ''What efforts do we need to make to find information?'', ''What about archived information and backup records?'' and ''What about personal information in big datasets?''","access":"free"},{"title":"Data protection audit framework, artificial intelligence toolkit: Contracts and third parties","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/contracts-and-third-parties/","locator":"List beginning ''Include terms or clauses stating that''","access":"free"},{"title":"Opinion 28/2024 on certain data protection aspects related to the processing of personal data in the context of AI models","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-12/edpb_opinion_202428_ai-models_en.pdf","locator":"Para. 43 (p. 16); also para. 65 (p. 21) and the lists of mitigating measures on pp. 29-30 and para. 114 (p. 32)","access":"free"},{"title":"2025 Coordinated Enforcement Action: Implementation of the right to erasure by controllers","publisher":"European Data Protection Board","year":2026,"url":"https://www.edpb.europa.eu/system/files/2026-02/edpb_cef-report_2025_right-to-erasure_en.pdf","locator":"Executive summary, pp. 2-3; section 3.1, p. 9","access":"free"},{"title":"Machine Unlearning Doesn''t Do What You Think: Lessons for Generative AI Policy and Research","publisher":"arXiv (Cooper and others; NeurIPS 2025)","year":2024,"url":"https://arxiv.org/abs/2412.06966","locator":"Abstract","access":"free"},{"title":"UK GDPR, Article 12A: Meaning of \"applicable time period\"","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/12A.","locator":"Art. 12A(1)-(4); note F1; read with Art. 12(3)-(4)","access":"free"},{"title":"Data Protection Act 2018, section 164A: Complaints by data subjects to controllers","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/164A","locator":"s.164A(1)-(5); note F1","access":"free"},{"title":"UK GDPR, Article 19: Notification obligation regarding rectification or erasure of personal data or restriction of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/19","locator":"Art. 19 (single paragraph)","access":"free"},{"title":"Enforcement Notice: Bristol City Council","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/media2/tacptiie/bristol-city-council-enforcement-notice.pdf","locator":"paras 12-17 (pp. 4-5); Annex 1","access":"free"},{"title":"AI how-to sheets: Ensuring and facilitating the exercise of data subjects'' rights","publisher":"Commission Nationale de l''Informatique et des Libertés (CNIL)","year":2026,"url":"https://www.cnil.fr/en/ensuring-and-facilitating-exercise-data-subjects-rights","locator":"Sections on rights over training datasets and over AI models; passage beginning ''the CNIL identifies, to date, two main techniques''","access":"free"},{"title":"2024 Coordinated Enforcement Action: Implementation of the right of access by controllers","publisher":"European Data Protection Board","year":2025,"url":"https://www.edpb.europa.eu/system/files/2025-01/edpb_cef-report-2024_20250116_rightofaccess_en.pdf","locator":"Executive summary, p. 2; section 3.1, p. 9; section 4.2.3 ''Lack of documented internal procedures'', pp. 18-19","access":"free"},{"title":"NIST Privacy Framework: A Tool for Improving Privacy through Enterprise Risk Management, Version 1.0","publisher":"National Institute of Standards and Technology","year":2020,"url":"https://nvlpubs.nist.gov/nistpubs/CSWP/NIST.CSWP.01162020.pdf","locator":"Appendix A, Table 2, Control-P, ''Data Processing Management (CT.DM-P)'', p. 24 (PDF p. 28); p. 17 (PDF p. 21)","access":"free"},{"title":"Algorithms that Remember: Model Inversion Attacks and Data Protection Law","publisher":"arXiv (M. Veale, R. Binns and L. Edwards; Philosophical Transactions of the Royal Society A 376, 2018)","year":2018,"url":"https://arxiv.org/abs/1807.04644","locator":"Abstract (version 2, 15 October 2018)","access":"free"},{"title":"Extracting Training Data from Large Language Models","publisher":"arXiv (N. Carlini and others)","year":2020,"url":"https://arxiv.org/abs/2012.07805","locator":"Abstract (version 2, 15 June 2021)","access":"free"}]'::jsonb, '2026-10-02')
