insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.8', '["**What it measures.** Whether the organisation can prove, from records made at the time, how each AI system uses personal data: scope, legal basis, risk assessment, safeguards and decisions taken.","**Why it matters.** A person refused a loan or a job by an AI system can only have that outcome checked if someone can show what was done and why. Without records, mistakes cannot be traced or put right, and nobody outside can confirm the person was treated fairly. The regulator warns: \"if you can’t show good data protection practices, it may leave you open to fines and reputational damage.\"","**The UK position.** Data protection law makes the organisation responsible for compliance and for being able to demonstrate it. The Information Commission (ICO) can require information and, since August 2025, documents, and can inspect premises and equipment. Since February 2026 it can also require a report, by a person it approves, at the organisation''s expense and, where it suspects a breach, call current or former staff and managers to answer questions. Ignoring a notice can itself be fined. Ordinary cooperation earns no reduction in a fine: the regulator treats it as required by law.","**What good looks like.** One file per system, kept current, in a known place, which someone other than its author can produce. The regulator''s auditors ask first for policies, risk registers and records of processing, then test whether practice matches.","**Reading the answer.** The usual weak point is evidence that exists but is scattered, or assembled only when a request arrives.","**A defensible figure.** An urgent information notice can require documents 24 hours after it is given; an urgent assessment notice, seven days. In 2025/26 the regulator completed 85 audits, risk reviews and follow-ups."]'::jsonb, false, '[{"title":"UK GDPR, Article 5: Principles relating to processing of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/5","locator":"Art. 5(2)","access":"free"},{"title":"Data Protection Act 2018, section 142: Information notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/142","locator":"s.142(1), (5)-(7); notes F2-F13","access":"free"},{"title":"Data Protection Act 2018, section 146: Assessment notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/146","locator":"s.146(2)(a)-(k), (3A), (8), (9), (11A); section 146A","access":"free"},{"title":"Data Protection Act 2018, section 148A: Interview notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/148A","locator":"s.148A(1)-(3), (8)","access":"free"},{"title":"Data Protection Act 2018, section 155: Penalty notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/155","locator":"s.155(1)(b)-(c), (3)(d), (3)(f); section 157(4)","access":"free"},{"title":"Data Protection Fining Guidance: Relevant aggravating or mitigating factors","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/our-information/policies-and-procedures/data-protection-fining-guidance/circumstances-in-which-the-commissioner-would-consider-it-appropriate-to-issue-a-penalty-notice/relevant-aggravating-or-mitigating-factors/","locator":"Sections ''The degree of responsibility of the controller or processor'' and ''The degree of cooperation with the Commissioner''; footnotes 69-71","access":"free"},{"title":"Guide to accountability and governance","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/guide-to-accountability-and-governance/","locator":"Sections ''Why is accountability important?'', ''What do we need to do?'' and ''What documentation should we maintain?''; checklist","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Governance and accountability in AI","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/governance-and-accountability-in-ai/","locator":"Control measures on the privacy management framework, the DPIA, the audit programme and change management","access":"free"},{"title":"A guide to ICO audits (version 1.5)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/media2/pyophl0h/guide-to-data-protection-audits.pdf","locator":"pp. 3-4 (executive summary, compulsory audits), p. 7 (''Document review''), p. 8","access":"free"},{"title":"Information Commissioner''s Annual Report and Financial Statements 2025/26 (HC 274)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/media2/ybsi5n0j/ico-annual-report-202527.pdf","locator":"p. 65 (''Regulatory Assurance audits''); table p. 67; pp. 34, 59, 62-63","access":"free"},{"title":"UK GDPR, Article 30: Records of processing activities","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/30","locator":"Art. 30(1)(a)-(g), (2), (4), (5); notes F1-F4","access":"free"},{"title":"Data Protection Act 2018, section 148: Destroying or falsifying information and documents etc","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/148","locator":"s.148(1)-(3); notes F1-F5","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 12: Record-keeping","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-12","locator":"Art. 12(1)-(3); read with Art. 18 (documentation kept for 10 years) and Art. 19 (logs kept at least six months)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"''At a glance''; section ''What do we need to consider when undertaking data protection impact assessments for AI?''","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division)","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"paras 145-154 (Ground 3); declaration at para 210(2)","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 2 ''ATRS purpose and scope''; sections 5-13 (the template fields); section 14","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Info-communications Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"p. 44 (documenting model training and selection); para 3.13, p. 29; p. 37 (data provenance record); p. 48 (traceability)","access":"free"},{"title":"Reviewable Automated Decision-Making: A Framework for Accountable Algorithmic Systems","publisher":"arXiv (J. Cobbe, M. S. A. Lee and J. Singh; ACM FAccT 2021)","year":2021,"url":"https://arxiv.org/abs/2102.04201","locator":"Abstract (version 2, 10 February 2021)","access":"free"},{"title":"Closing the AI Accountability Gap: Defining an End-to-End Framework for Internal Algorithmic Auditing","publisher":"arXiv (I. D. Raji and others; ACM FAT* 2020)","year":2020,"url":"https://arxiv.org/abs/2001.00973","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.1', '["**What it measures.** Whether the organisation knows the ways an AI system can be attacked that ordinary software cannot, and has written down which of them apply to each system it runs.","**Why it matters.** A poisoned model or a hijacked assistant still looks as if it is working. The people harmed are those it decides about or acts for: the applicant scored by a manipulated screening tool, the customer whose records an assistant is tricked into disclosing. They cannot see the attack, and often nor can the organisation.","**The UK position.** No UK statute requires an AI threat model. The government''s voluntary Code of Practice for the Cyber Security of AI, published in January 2025, says developers and operators shall analyse threats to their systems, and that \"Threat modelling should include regular reviews and updates and address AI-specific attacks, such as data poisoning, model inversion, and membership inference.\" The National Cyber Security Centre warns that language models do not separate instructions from data, so injected instructions may never be fully prevented.","**What good looks like.** A threat model for each system, covering poisoned data, crafted inputs, injected instructions, theft of the model and leakage of what it learned. It includes systems bought from suppliers, is refreshed as new attacks are reported, and is tested by people trying to break the system.","**Reading the answer.** The weak answer is that AI is covered by the existing cyber programme. Ask to see the document, its date, and what last changed because of it.","**A defensible figure.** In a public competition reported by the AI Security Institute, participants submitted 1.8 million prompt-injection attacks against 22 AI agents; over 60,000 succeeded in making an agent break its rules."]'::jsonb, true, '[{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 3, provisions 3.1, 3.1.1 and 3.2","access":"free"},{"title":"Prompt injection is not SQL injection (it may be worse)","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/blog-post/prompt-injection-is-not-sql-injection","locator":"Opening section; ''No data, no instructions'' and ''Developer and organisation awareness''","access":"free"},{"title":"Guidelines for secure AI system development: Secure design","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-design","locator":"Sections ''Raise staff awareness of threats and risks'' and ''Model the threats to your system''","access":"free"},{"title":"Adversarial Machine Learning: A Taxonomy and Terminology of Attacks and Mitigations (NIST AI 100-2e2025)","publisher":"National Institute of Standards and Technology","year":2025,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf","locator":"Section 4.2.5 ''Risk Management in Light of AML'', p. 60 (PDF p. 73)","access":"free"},{"title":"LLM01:2025 Prompt Injection","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm01-prompt-injection/","locator":"Description; ''Prevention and Mitigation Strategies''","access":"free"},{"title":"Security Challenges in AI Agent Deployment: Insights from a Large Scale Public Competition","publisher":"AI Security Institute","year":2025,"url":"https://www.aisi.gov.uk/research/security-challenges-in-ai-agent-deployment-insights-from-a-large-scale-public-competition","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"Guidance on AI and data protection: How should we assess security and data minimisation in AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-should-we-assess-security-and-data-minimisation-in-ai/","locator":"Sections ''What security risks does AI introduce?'' and ''What types of privacy attacks apply to AI models?''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 15: Accuracy, robustness and cybersecurity","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-15","locator":"Art. 15(5)","access":"free"},{"title":"Impact of AI on cyber threat from now to 2027","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/report/impact-ai-cyber-threat-now-2027","locator":"Key judgements","access":"free"},{"title":"Machine learning principles: 1.2 Model the threats to your system","publisher":"National Cyber Security Centre","year":2024,"url":"https://www.ncsc.gov.uk/collection/machine-learning-principles/secure-design/model-threats","locator":"Part 1: Secure design, principle 1.2, ''Why is this important?'' and ''Create a high-level threat model for the ML system''","access":"free"},{"title":"Cyber security risks to artificial intelligence","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/research-on-the-cyber-security-of-ai/cyber-security-risks-to-artificial-intelligence","locator":"Executive summary; section 4 (findings of the risk assessment); section 5 (list of case studies)","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(2)","access":"free"},{"title":"Financial Stability in Focus: Artificial intelligence in the financial system","publisher":"Bank of England, Financial Policy Committee","year":2025,"url":"https://www.bankofengland.co.uk/financial-stability-in-focus/2025/april-2025","locator":"Section headed ''Changing external cyber threat environment''","access":"free"},{"title":"Not what you''ve signed up for: Compromising Real-World LLM-Integrated Applications with Indirect Prompt Injection","publisher":"arXiv (Greshake, Abdelnabi, Mishra, Endres, Holz and Fritz)","year":2023,"url":"https://arxiv.org/abs/2302.12173","locator":"Abstract on the arXiv record (version 2, 5 May 2023)","access":"free"},{"title":"Poisoning Web-Scale Training Datasets is Practical","publisher":"arXiv (Carlini, Jagielski, Choquette-Choo, Paleka, Pearce, Anderson, Terzis, Thomas and Tramèr)","year":2023,"url":"https://arxiv.org/abs/2302.10149","locator":"Abstract on the arXiv record (version 2, 6 May 2024)","access":"free"},{"title":"Lessons From Red Teaming 100 Generative AI Products","publisher":"arXiv (Bullwinkel and 25 others, Microsoft)","year":2025,"url":"https://arxiv.org/abs/2501.07238","locator":"Abstract on the arXiv record","access":"free"},{"title":"Guidelines on Securing AI Systems","publisher":"Cyber Security Agency of Singapore","year":2024,"url":"https://isomer-user-content.by.gov.sg/36/42140c27-030f-4bb9-b4c7-b543ad2ddad4/guidelines-on-securing-ai-systems_2024-10-15.pdf","locator":"Section 3 ''Securing AI'', opening paragraph, PDF p. 7; section 2 ''Understanding AI threats'', p. 5; guideline 1.2, p. 10","access":"free"}]'::jsonb, '2026-10-02')
