insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.2', '["**What it measures.** Whether there is a written security standard that every AI system must meet, both those the organisation builds and those it buys, and whether anyone checks that it is met.","**Why it matters.** Many organisations buy their AI rather than build it. If the supplier''s security is taken on trust, the people whose data passes through the system, and those its outputs affect, carry a risk nobody examined. They did not choose the supplier and cannot inspect it.","**The UK position.** The National Cyber Security Centre''s 2023 guidelines cover secure design, development, deployment and operation. The government''s Code of Practice of January 2025 builds on them, and an ETSI specification of April 2025 carries the same provisions. On buying, the Code says an organisation that works with an external provider \"shall undertake a due diligence assessment and should ensure that the provider is adhering to this Code of Practice\". The Code is voluntary. The binding rule is narrower: where personal data is processed, UK GDPR requires security appropriate to the risk, regularly tested. A Cyber Security and Resilience Bill is before Parliament and is not yet law.","**What good looks like.** Security requirements written into development practice and into contracts. Suppliers give evidence of testing, not assurances. Systems are tested before release and again when the model changes; consequential ones are tested independently.","**Reading the answer.** A supplier questionnaire that nobody reads is the common weak answer. Ask what was last rejected, or changed, because of a security finding.","**A defensible figure.** In a 2024 government survey of 350 UK businesses using or planning to use AI, 47% of those already using it had no cyber security practices specifically for AI."]'::jsonb, false, '[{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 2, provisions 2.4 and 2.7; Principle 7; Principle 9, provisions 9.1 to 9.2.1; Terminology table","access":"free"},{"title":"Implementation Guide for the AI Cyber Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://assets.publishing.service.gov.uk/media/679cae441d14e76535afb630/Implementation_Guide_for_the_AI_Cyber_Security_Code_of_Practice.pdf","locator":"Principle 2, PDF p. 14","access":"free"},{"title":"ETSI TS 104 223 V1.1.1: Securing Artificial Intelligence (SAI); Baseline Cyber Security Requirements for AI Models and Systems","publisher":"ETSI","year":2025,"url":"https://www.etsi.org/deliver/etsi_ts/104200_104299/104223/01.01.01_60/ts_104223v010101p.pdf","locator":"Provisions 5.1.2-7, 5.2.5-2 and 5.2.5-2.1","access":"free"},{"title":"Guidelines for secure AI system development","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development","locator":"Executive summary and ''About the guidelines''","access":"free"},{"title":"Guidelines for secure AI system development: Secure development","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-development","locator":"Section ''Secure your supply chain''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1), in particular (1)(d)","access":"free"},{"title":"AI cyber security survey: main report","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/research-on-the-cyber-security-of-ai/ai-cyber-security-survey-main-report","locator":"Executive summary","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Introduction (modular approach to codes of practice); Principle A (risk management), action on suppliers","access":"free"},{"title":"LLM03:2025 Supply Chain","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm032025-supply-chain/","locator":"Description","access":"free"},{"title":"Cyber Security and Resilience Bill (collection)","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/collections/cyber-security-and-resilience-bill","locator":"Overview and Background","access":"free"},{"title":"UK GDPR, Article 28: Processor","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/28","locator":"Art. 28(1) and 28(3)(h)","access":"free"},{"title":"ETSI EN 304 223 V2.1.1: Securing Artificial Intelligence (SAI); Baseline Cyber Security Requirements for AI Models and Systems","publisher":"ETSI","year":2025,"url":"https://www.etsi.org/deliver/etsi_en/304200_304299/304223/02.01.01_60/en_304223v020101p.pdf","locator":"Foreword, PDF p. 4 (status and adoption date); provisions 5.1.2-4 and 5.1.2-7, PDF pp. 10-11","access":"free"},{"title":"Machine learning principles: 2.1 Secure your supply chain","publisher":"National Cyber Security Centre","year":2024,"url":"https://www.ncsc.gov.uk/collection/machine-learning-principles/secure-development/secure-supply-chain","locator":"Part 2: Secure development, principle 2.1, Goals and ''Verify any third-party inputs are from sources you trust''","access":"free"},{"title":"Software Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/software-security-code-of-practice/software-security-code-of-practice","locator":"''Voluntary Software Security Code of Practice'', theme 1 (principles 1.1 to 1.4) and theme 4","access":"free"},{"title":"SS2/21 Outsourcing and third party risk management","publisher":"Prudential Regulation Authority","year":2024,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2024/ss221-november-2024-update.pdf","locator":"Chapter 8 ''Access, audit, and information rights'', para 8.3, PDF p. 31","access":"free"},{"title":"Government cyber resilience (HC 546, Session 2024-25)","publisher":"National Audit Office","year":2025,"url":"https://www.nao.org.uk/wp-content/uploads/2025/01/government-cyber-resilience.pdf","locator":"Summary, paras 15 and 19, PDF pp. 11 and 13","access":"free"},{"title":"BadNets: Identifying Vulnerabilities in the Machine Learning Model Supply Chain","publisher":"arXiv (Gu, Dolan-Gavitt and Garg)","year":2017,"url":"https://arxiv.org/abs/1708.06733","locator":"Abstract on the arXiv record (version 2, 11 March 2019)","access":"free"},{"title":"An Empirical Study of Pre-Trained Model Reuse in the Hugging Face Deep Learning Model Registry","publisher":"arXiv (Jiang, Synovic, Hyatt, Schorlemmer, Sethi, Lu, Thiruvathukal and Davis)","year":2023,"url":"https://arxiv.org/abs/2303.02552","locator":"Abstract on the arXiv record","access":"free"},{"title":"Guidelines on Securing AI Systems","publisher":"Cyber Security Agency of Singapore","year":2024,"url":"https://isomer-user-content.by.gov.sg/36/42140c27-030f-4bb9-b4c7-b543ad2ddad4/guidelines-on-securing-ai-systems_2024-10-15.pdf","locator":"Section 3.3, guideline 2.1 ''Secure the supply chain'', PDF p. 11","access":"free"}]'::jsonb, '2026-10-02')
