insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.3', '["**What it measures.** Whether the organisation knows who can change what an AI system does (its model, prompts, training data and data pipelines), limits that to those who need it, and keeps a record of every change.","**Why it matters.** A change to a prompt or a data source can alter decisions about many people at once, with no change to any code. If nobody can say who made the change, or when, the people harmed cannot get an explanation, and the organisation cannot put it right or show it was not deliberate.","**The UK position.** No UK law is specific to AI here. The government''s voluntary Code of Practice on AI cyber security says developers and operators shall review their access controls and secure models, data and pipelines, and that developers should keep \"an audit log of changes to system prompts or other model configuration (including prompts) that affect the underlying working of the systems\". Operators shall log system and user actions. Where personal data is involved, UK GDPR requires appropriate security, and that anyone with access to the data acts only on the controller''s instructions.","**What good looks like.** Named individuals, not shared log-ins, each with no more access than the role needs. Changes to prompts, models and data sources are versioned, attributable and, for consequential systems, approved before release. Suppliers give notice of their changes. Access is reviewed on a schedule.","**Reading the answer.** Ask who last changed the system prompt, and when. A slow or uncertain answer is the finding.","**A defensible figure.** Research published by the AI Security Institute found that 250 poisoned documents were enough to plant a hidden trigger in a language model, at every model and dataset size tested."]'::jsonb, false, '[{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Provisions 2.3, 5.2, 6.1, 6.3, 7.4, 8.3 and 12.1","access":"free"},{"title":"ETSI TS 104 223 V1.1.1: Securing Artificial Intelligence (SAI); Baseline Cyber Security Requirements for AI Models and Systems","publisher":"ETSI","year":2025,"url":"https://www.etsi.org/deliver/etsi_ts/104200_104299/104223/01.01.01_60/ts_104223v010101p.pdf","locator":"Provisions 5.2.2-1, 5.2.2-3 and 5.2.4-3","access":"free"},{"title":"Guidelines for secure AI system development: Secure deployment","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-deployment","locator":"Sections ''Secure your infrastructure'' and ''Protect your model continuously''","access":"free"},{"title":"Guidelines for secure AI system development: Secure development","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-development","locator":"Section ''Identify, track and protect your assets''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1)(b), 32(2) and 32(4)","access":"free"},{"title":"Cyber Essentials: Requirements for IT infrastructure v3.2","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/files/cyber-essentials-requirements-for-it-infrastructure-v3-2.pdf","locator":"Section 4 ''User access control'', pp. 19-20","access":"free"},{"title":"Implementation Guide for the AI Cyber Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://assets.publishing.service.gov.uk/media/679cae441d14e76535afb630/Implementation_Guide_for_the_AI_Cyber_Security_Code_of_Practice.pdf","locator":"Provision 5.4, PDF p. 27, ''Implement Strong Data Access Controls''","access":"free"},{"title":"Poisoning Attacks on LLMs Require a Near-constant Number of Poison Samples","publisher":"AI Security Institute","year":2025,"url":"https://www.aisi.gov.uk/research/poisoning-attacks-on-llms-require-a-near-constant-number-of-poison-samples","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"LLM07:2025 System Prompt Leakage","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm072025-system-prompt-leakage/","locator":"Description","access":"free"},{"title":"Guidance on AI and data protection: How should we assess security and data minimisation in AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-should-we-assess-security-and-data-minimisation-in-ai/","locator":"Section ''How should we ensure training data is secure?''","access":"free"},{"title":"Bates and Others v Post Office Limited (No 6: Horizon Issues) [2019] EWHC 3408 (QB)","publisher":"High Court of Justice, Queen''s Bench Division (Courts and Tribunals Judiciary)","year":2019,"url":"https://www.judiciary.uk/wp-content/uploads/2019/12/bates-v-post-office-judgment.pdf","locator":"Paras 1007-1013 (answers to Horizon Issues 11 and 12), PDF pp. 308-309","access":"free"},{"title":"Penalty Notice: Capita plc and Capita Pension Solutions Limited","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/media2/pv5nhks4/capita-plc-and-cpsl-monetary-penalty-notice.pdf","locator":"Para 7(iii), PDF p. 7; paras 80 and 90 on privileged access management","access":"free"},{"title":"Data Protection Act 2018, section 62: Logging","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/62","locator":"s. 62(1) and (2)(b)","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.3 ''Policies and procedures'', item (c)(viii), PDF p. 17; Principle 3.3(c) on testing material model changes","access":"free"},{"title":"Machine learning principles: 2.3 Manage the full life cycle of models and datasets","publisher":"National Cyber Security Centre","year":2024,"url":"https://www.ncsc.gov.uk/collection/machine-learning-principles/secure-development/manage-life-cycle","locator":"Part 2: Secure development, principle 2.3, ''Use version-control tools to track and control changes to your software, dataset and resulting model''","access":"free"},{"title":"Managing the cyber risk of agentic AI","publisher":"National Cyber Security Centre","year":2026,"url":"https://www.ncsc.gov.uk/blogs/managing-the-cyber-risk-of-agentic-ai","locator":"Consideration 4(e) ''Assign and limit an agent''s access to credentials'' and consideration 5 ''Observability''","access":"free"},{"title":"Software Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/software-security-code-of-practice/software-security-code-of-practice","locator":"''Voluntary Software Security Code of Practice'', theme 2 ''Build environment security'', principles 2.1 and 2.2","access":"free"},{"title":"How is ChatGPT''s behavior changing over time?","publisher":"arXiv (Chen, Zaharia and Zou)","year":2023,"url":"https://arxiv.org/abs/2307.09009","locator":"Abstract on the arXiv record (version 3, 31 October 2023)","access":"free"},{"title":"Hidden Technical Debt in Machine Learning Systems","publisher":"Advances in Neural Information Processing Systems 28 (Sculley and others, Google)","year":2015,"url":"https://proceedings.neurips.cc/paper_files/paper/2015/file/86df7dcfd896fcaf2674f757a2463eba-Paper.pdf","locator":"Section 2, ''Entanglement'', PDF p. 2","access":"free"},{"title":"Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile (NIST AI 600-1)","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf","locator":"Suggested action MS-2.8-003 under MEASURE 2.8, PDF p. 38; MANAGE 4.1 (change management)","access":"free"}]'::jsonb, '2026-10-02')
