insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.4', '["**What it measures.** Whether each AI system can be stopped quickly, by people who have the authority to do it and know how, and whether that has been tried.","**Why it matters.** A system that goes wrong keeps going until someone stops it. Each further hour means more wrong decisions, disclosed data or unwanted actions, against people who have no means of stopping it themselves. Systems that act, rather than advise, do this faster.","**The UK position.** No general UK law requires an off switch for AI. One sector has such a rule: firms engaged in algorithmic trading must be able to cancel unexecuted orders immediately in an emergency. The government''s voluntary Code of Practice on AI cyber security says developers and operators shall create, test and maintain incident and recovery plans, and that operators should be able to restore a known good state. The EU AI Act will require high-risk systems to let a person \"interrupt the system through a ''stop'' button or a similar procedure that allows the system to come to a halt in a safe state\".","**What good looks like.** For each system: the conditions that trigger a stop, the roles allowed to order it, the technical means, and what the business does meanwhile. More than one person can do it. It is rehearsed and timed. Systems that take actions get a containment design before going live.","**Reading the answer.** The weak answer is that one person knows how. Ask when it was last tried and how long it took.","**A defensible figure.** The AI Security Institute, examining 177,436 publicly available tools for AI agents, found that tools which take actions rose from 27% to 65% of usage in 16 months."]'::jsonb, false, '[{"title":"Commission Delegated Regulation (EU) 2017/589, Article 12: Kill functionality","publisher":"legislation.gov.uk","year":2017,"url":"https://www.legislation.gov.uk/eur/2017/589/article/12","locator":"Art. 12(1) and (3)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 14: Human oversight","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-14","locator":"Art. 14(4)(e)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4, MANAGE 2.4, p. 32; Table 1, GOVERN 1.7, p. 23","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Provisions 4.1, 4.3, 5.3, 5.3.1 and 6.5","access":"free"},{"title":"Implementation Guide for the AI Cyber Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://assets.publishing.service.gov.uk/media/679cae441d14e76535afb630/Implementation_Guide_for_the_AI_Cyber_Security_Code_of_Practice.pdf","locator":"Provision 5.3, PDF p. 26; Principle 4, PDF p. 21","access":"free"},{"title":"Guidelines for secure AI system development: Secure design","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-design","locator":"Section ''Design your system for security as well as functionality and performance''","access":"free"},{"title":"LLM06:2025 Excessive Agency","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm062025-excessive-agency/","locator":"''Prevention and Mitigation Strategies''","access":"free"},{"title":"How are AI agents used? Evidence from 177,000 MCP tools","publisher":"AI Security Institute","year":2026,"url":"https://www.aisi.gov.uk/research/how-are-ai-agents-used-evidence-from-177-000-mcp-tools","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Principle D (incident planning, response and recovery)","access":"free"},{"title":"Quantifying Frontier LLM Capabilities for Container Sandbox Escape","publisher":"AI Security Institute","year":2026,"url":"https://www.aisi.gov.uk/research/quantifying-frontier-llm-capabilities-for-container-sandbox-escape","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"Managing the cyber risk of agentic AI","publisher":"National Cyber Security Centre","year":2026,"url":"https://www.ncsc.gov.uk/blogs/managing-the-cyber-risk-of-agentic-ai","locator":"Consideration 7, ''Emergency shutdown: maintain the ability to ''pull the plug''''; consideration 3, ''Set the right level of oversight''","access":"free"},{"title":"Thinking carefully before adopting agentic AI","publisher":"National Cyber Security Centre","year":2026,"url":"https://www.ncsc.gov.uk/blogs/thinking-carefully-before-adopting-agentic-ai","locator":"Section ''Insist on human accountability''","access":"free"},{"title":"SS5/18 Algorithmic trading","publisher":"Prudential Regulation Authority","year":2018,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2018/ss518.pdf","locator":"Para 3.5, PDF p. 7; para 2.3(e) on ownership of kill-switch controls","access":"free"},{"title":"Final Notice: Citigroup Global Markets Limited","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/publication/final-notices/citigroup-global-markets-limited-2024.pdf","locator":"Paras 2.4 to 2.7, PDF pp. 3-4","access":"free"},{"title":"In the Matter of Knight Capital Americas LLC, Securities Exchange Act Release No. 70694","publisher":"US Securities and Exchange Commission","year":2013,"url":"https://www.sec.gov/litigation/admin/2013/34-70694.pdf","locator":"Paras 17 and 21, PDF pp. 6-7","access":"free"},{"title":"The Provision and Use of Work Equipment Regulations 1998, regulation 16: Emergency stop controls","publisher":"legislation.gov.uk","year":1998,"url":"https://www.legislation.gov.uk/uksi/1998/2306/regulation/16","locator":"Reg. 16(1) and (2)","access":"free"},{"title":"The Off-Switch Game","publisher":"arXiv (Hadfield-Menell, Dragan, Abbeel and Russell)","year":2016,"url":"https://arxiv.org/abs/1611.08219","locator":"Abstract on the arXiv record (version 3, 16 June 2017)","access":"free"},{"title":"Safely Interruptible Agents","publisher":"Conference on Uncertainty in Artificial Intelligence, UAI 2016 (Orseau and Armstrong)","year":2016,"url":"https://www.auai.org/uai2016/proceedings/papers/68.pdf","locator":"Abstract, PDF p. 1","access":"free"},{"title":"Model AI Governance Framework for Agentic AI, Version 1.5","publisher":"Infocomm Media Development Authority (Singapore)","year":2026,"url":"https://www.imda.gov.sg/-/media/imda/files/about/emerging-tech-and-research/artificial-intelligence/mgf-for-agentic-ai.pdf","locator":"Section 2.3.3, ''Continuous testing and monitoring'', PDF p. 43; Executive summary on human approval of irreversible actions","access":"free"}]'::jsonb, '2026-10-02')
