insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.5', '["**What it measures.** Whether a failing AI system triggers the organisation''s existing incident response: named scenarios, known reporting duties, rehearsal, and lessons fed back.","**Why it matters.** A model can give wrong or unfair answers for weeks with no alarm. If nobody treats that as an incident, the people refused, overcharged or exposed are not told and not put right, and the same fault harms the next person.","**The UK position.** No UK law sets a general duty to report AI failures. Where personal data is involved, a breach must be notified to the Information Commission (ICO) within 72 hours where feasible, and to the individuals when the risk to them is high. The government''s voluntary code for AI security says \"Developers and System Operators shall create, test and maintain an AI system incident management plan and an AI system recovery plan.\" Its governance code asks boards to see the plan exercised at least annually. The EU AI Act obliges providers of high-risk systems to report serious incidents to authorities, and deployers to tell the provider first; that text is being amended.","**What good looks like.** AI failure types written into the plan; reporting duties mapped beforehand; logs preserved; an AI scenario exercised yearly; each incident reviewed and the lessons applied.","**Reading the answer.** The usual weak answer is that it would be handled like any outage. Ask when an AI scenario was last rehearsed, and what changed afterwards.","**A defensible figure.** The government''s 2025/2026 breaches survey found that 25% of UK businesses had a formal incident response plan, and 45% had none of the response measures it asked about. It covers cyber incidents generally, not AI."]'::jsonb, false, '[{"title":"UK GDPR, Article 33: Notification of a personal data breach to the Commission","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/33","locator":"Art. 33(1), (2) and (5)","access":"free"},{"title":"UK GDPR, Article 34: Communication of a personal data breach to the data subject","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/34","locator":"Art. 34(1), (3) and (4)","access":"free"},{"title":"Personal data breaches: a guide","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/report-a-breach/personal-data-breach/personal-data-breaches-a-guide/","locator":"Sections ''At a glance'', ''Checklists'' and ''What breaches do we need to notify the ICO about?''; latest update noted 20 August 2025","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 6, provision 6.5; also 2.3, 10.3 and 12.1","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Section D: Incident planning, response and recovery, Actions 1 to 4","access":"free"},{"title":"Incident management. Plan: Your cyber incident response processes","publisher":"National Cyber Security Centre","year":2019,"url":"https://www.ncsc.gov.uk/collection/incident-management/cyber-incident-response-processes","locator":"Sections ''Developing an Incident Response (IR) plan'', ''Incident Management (IM)'' and ''Playbooks and regulatory issues''; page 3 of 7, version 1.0","access":"free"},{"title":"Cyber Assessment Framework, Principle D2: Lessons learned","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/cyber-assessment-framework/caf-objective-d/principle-d2-lessons-learned","locator":"Principle D2 statement and guidance; version 4.0, reviewed 6 August 2025","access":"free"},{"title":"Cyber security breaches survey 2025/2026","publisher":"Department for Science, Innovation and Technology and Home Office","year":2026,"url":"https://www.gov.uk/government/statistics/cyber-security-breaches-survey-20252026/cyber-security-breaches-survey-20252026","locator":"Summary, ''Incident response''; section 5.1 and Figure 5.2","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 73: Reporting of serious incidents","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-73","locator":"Art. 73(1) to (6)","access":"free"},{"title":"PS26/2: Operational incident and third party reporting","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/publications/policy-statements/ps26-2-operational-incident-third-party-reporting","locator":"Summary page, sections ''Summary'' and ''Background''","access":"free"},{"title":"Investigation: WannaCry cyber attack and the NHS","publisher":"National Audit Office","year":2018,"url":"https://www.nao.org.uk/wp-content/uploads/2017/10/Investigation-WannaCry-cyber-attack-and-the-NHS.pdf","locator":"Summary, paragraphs 9 and 10; Part Three, paragraph 3.3. HC 414, Session 2017-2019","access":"free"},{"title":"Capita fined £14m for data breach affecting over 6m people","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/about-the-ico/media-centre/news-and-blogs/2025/10/capita-fined-14m-for-data-breach-affecting-over-6m-people/","locator":"Sections ''The cyber attack'' and ''Summary of the contraventions''","access":"free"},{"title":"The Network and Information Systems Regulations 2018, regulation 11: The duty to notify incidents","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/uksi/2018/506/regulation/11","locator":"Reg. 11(1) and (3)(b)(i)","access":"free"},{"title":"Towards a common reporting framework for AI incidents","publisher":"OECD","year":2025,"url":"https://www.oecd.org/content/dam/oecd/en/publications/reports/2025/02/towards-a-common-reporting-framework-for-ai-incidents_8c488fdb/f326d4ac-en.pdf","locator":"Abstract and Executive summary; OECD Artificial Intelligence Papers No. 34","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4 (MANAGE function), MANAGE 4.3; also MANAGE 4.1 and, in Table 1, GOVERN 4.3","access":"free"},{"title":"Preventing Repeated Real World AI Failures by Cataloging Incidents: The AI Incident Database","publisher":"arXiv (McGregor)","year":2020,"url":"https://arxiv.org/abs/2011.08512","locator":"Abstract","access":"free"},{"title":"Lessons for Editors of AI Incidents from the AI Incident Database","publisher":"arXiv (Paeth, Atherton, Pittaras, Frase and McGregor)","year":2024,"url":"https://arxiv.org/abs/2409.16425","locator":"Abstract","access":"free"},{"title":"AI incident reporting: Addressing a gap in the UK''s regulation of AI","publisher":"The Centre for Long-Term Resilience","year":2024,"url":"https://www.longtermresilience.org/reports/ai-incident-reporting-addressing-a-gap-in-the-uks-regulation-of-ai/","locator":"Summary page, section ''The need for incident reporting''","access":"free"}]'::jsonb, '2026-10-02')
