insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.6', '["**What it measures.** Whether the business can keep serving people when an AI system is unavailable, withdrawn or switched off, and how quickly it can recover.","**Why it matters.** When a system that screens claims, answers customers or schedules care stops, the people waiting bear the cost: payments delayed, questions unanswered, decisions stalled. A fallback that exists only on paper protects no one.","**The UK position.** No general law requires an AI service to be kept running. Where personal data is processed, security must include the ability to restore access to it in a timely manner after an incident. Regulated financial firms must identify their important business services, set impact tolerances and stay within them through severe but plausible disruption; they had until 31 March 2025. Since 13 July 2026 four large cloud providers have been overseen as critical third parties, but firms keep responsibility for their own third-party risk. The National Cyber Security Centre''s framework for essential services asks that \"consideration is also given to how operation of the essential function can continue in the event of technology failure or compromise\".","**What good looks like.** For each AI system the business depends on: a written manual fallback, a decision on what stops first, a recovery target, and a test that proves them. Reliance on a single supplier is named and owned.","**Reading the answer.** A supplier''s uptime guarantee answers a different question. Ask when the fallback was last run by the people who would have to run it.","**A defensible figure.** In the government''s 2025/2026 breaches survey, 33% of UK businesses had a business continuity plan that covered cyber security."]'::jsonb, false, '[{"title":"FCA Handbook, SYSC 15A: Operational resilience","publisher":"Financial Conduct Authority","year":2022,"url":"https://handbook.fca.org.uk/handbook/sysc15a","locator":"SYSC 15A.2.1R, 15A.2.5R, 15A.2.9R, 15A.4.1R, 15A.5.3R and 15A.5.8R (each dated 31/03/2022)","access":"free"},{"title":"Operational resilience","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/firms/operational-resilience","locator":"Opening section and ''Operational resilience requirements for firms''; last updated 15 September 2026","access":"free"},{"title":"CrowdStrike outage: lessons for operational resilience","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/firms/operational-resilience/crowdstrike-outage-lessons-operational-resilience","locator":"Sections ''Our general observations following the outage'' and ''Observations on ensuring the resilience of infrastructure''","access":"free"},{"title":"Critical third parties: strengthening UK financial services","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/firms/critical-third-parties-strengthening-uk-financial-services","locator":"Sections ''What the regime means'' and ''Designated Critical Third Parties''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1)(b), (c) and (d)","access":"free"},{"title":"Cyber Assessment Framework, Principle B5: Resilient networks and systems","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/cyber-assessment-framework/caf-objective-b/principle-b5-resilient-networks-and-systems","locator":"Principle B5 description and guidance on resilience preparation; version 4.0, reviewed 6 August 2025","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 5, provisions 5.3 and 5.3.1; Principle 6, provision 6.5","access":"free"},{"title":"Cyber security breaches survey 2025/2026","publisher":"Department for Science, Innovation and Technology and Home Office","year":2026,"url":"https://www.gov.uk/government/statistics/cyber-security-breaches-survey-20252026/cyber-security-breaches-survey-20252026","locator":"Section 3.8 and Figure 3.9","access":"free"},{"title":"Guidelines for secure AI system development","publisher":"National Cyber Security Centre, with the US Cybersecurity and Infrastructure Security Agency and partner agencies","year":2023,"url":"https://www.ncsc.gov.uk/files/Guidelines-for-secure-AI-system-development.pdf","locator":"Section 2 ''Secure development'', ''Secure your supply chain'' (PDF page 12); section 3 ''Secure deployment'', ''Develop incident management procedures'' (PDF page 14)","access":"free"},{"title":"Independent Review of NATS (En Route) Plc''s Flight Planning System Failure on 28 August 2023: Final report (CAP 2993)","publisher":"Civil Aviation Authority","year":2024,"url":"https://www.caa.co.uk/publication/download/23337","locator":"Chapter 2, ''Contingency arrangements'', paragraphs 2.14, 2.15 and 2.21; Recommendation 1","access":"free"},{"title":"SS1/21 Operational resilience: Impact tolerances for important business services","publisher":"Prudential Regulation Authority","year":2022,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2021/ss121-march-22.pdf","locator":"Chapter 4, paragraphs 4.5 and 4.6","access":"free"},{"title":"Financial Stability in Focus: Artificial intelligence in the financial system","publisher":"Bank of England, Financial Policy Committee","year":2025,"url":"https://www.bankofengland.co.uk/financial-stability-in-focus/2025/april-2025","locator":"Executive summary and the section on operational risks in relation to AI service providers","access":"free"},{"title":"The Financial Stability Implications of Artificial Intelligence","publisher":"Financial Stability Board","year":2024,"url":"https://www.fsb.org/uploads/P14112024.pdf","locator":"Executive summary, first bullet; section 4.2.1 and Table 4","access":"free"},{"title":"Principles for Operational Resilience","publisher":"Basel Committee on Banking Supervision","year":2021,"url":"https://www.bis.org/publications/202103-guidelines-principles-operational-resilience.pdf","locator":"Principle 3 (business continuity planning and testing); also Principles 5 and 6","access":"free"},{"title":"Learning lessons from the cyber-attack: British Library cyber incident review","publisher":"British Library","year":2024,"url":"https://www.bl.uk/home/british-library-cyber-incident-review-8-march-2024.pdf","locator":"Section Six, ''Learning lessons from the attack'', lesson 6 (page 17 of 18); Section Three on recovery","access":"free"},{"title":"An Empirical Characterization of Outages and Incidents in Public Services for Large Language Models","publisher":"arXiv (Chu, Talluri, Lu and Iosup)","year":2025,"url":"https://arxiv.org/abs/2501.12469","locator":"Abstract","access":"free"},{"title":"Picking on the Same Person: Does Algorithmic Monoculture lead to Outcome Homogenization?","publisher":"arXiv (Bommasani, Creel, Kumar, Jurafsky and Liang)","year":2022,"url":"https://arxiv.org/abs/2211.13972","locator":"Abstract","access":"free"},{"title":"CAA Paper 2004/10: Flight Crew Reliance on Automation","publisher":"Civil Aviation Authority","year":2004,"url":"https://www.caa.co.uk/publication/download/12922","locator":"Executive Summary, pages v to vi","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4 (MANAGE function), MANAGE 2.3; also Table 1, GOVERN 6.2","access":"free"}]'::jsonb, '2026-10-02')
