insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.8', '["**What it measures.** Whether the board holds evidence that its controls over AI work, enough to support a public statement that the company''s material controls are effective.","**Why it matters.** A declaration tells investors, staff and customers that the company''s safeguards work. If the board signs it without evidence on AI, those people rely on an assurance nobody tested, and failures that harm them (unfair decisions, leaked data, wrong numbers) surface later and larger.","**The UK position.** The UK Corporate Governance Code 2024 asks boards of listed companies to declare in the annual report whether material controls were effective at the balance sheet date, and to describe any that were not. The provision applies from 2026 financial years, on a comply-or-explain basis. The Financial Reporting Council does not define a material control; the board decides. Its guidance says these could include controls over \"information and technology risks including cybersecurity, data protection and new technologies (e.g. artificial intelligence)\". It adds that a board can give only a reasonable conclusion based on evidence obtained, and that external assurance is not required. Unlisted companies are outside the Code; the government''s Cyber Governance Code asks any board for formal reporting at least quarterly.","**What good looks like.** AI systems considered when material controls are identified; evidence that each control operates, gathered through the year; weaknesses reported with the action taken.","**Reading the answer.** The weak answer is that management has confirmed it. Ask what evidence on AI controls the board saw, and who tested it.","**A defensible figure.** In the Financial Reporting Council''s 2025 review of 100 annual reports, 40 companies did not report the outcome of their review of control effectiveness."]'::jsonb, false, '[{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 4, Provision 29 (PDF page 14); Introduction, ''Application'' and ''Reporting on the Code''","access":"free"},{"title":"Corporate Governance Code Guidance: Material controls","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/library/standards-codes-policy/corporate-governance/corporate-governance-code-guidance/","locator":"Section 4, paragraphs 270 to 275; page last updated 3 June 2026","access":"free"},{"title":"Corporate Governance Code Guidance: Declaration on the effectiveness of the material controls","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/library/standards-codes-policy/corporate-governance/corporate-governance-code-guidance/","locator":"Section 4, paragraphs 296 to 300","access":"free"},{"title":"Annual Review of Corporate Governance Reporting 2025","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/8893/Annual_Review_of_Corporate_Governance_Reporting_2025.pdf","locator":"Section 4, ''Reporting on the outcome of the review of effectiveness'' (page 39), ''Provision 29'' (pages 40 to 41) and ''Artificial Intelligence'' (pages 44 to 45); sample described on page 5","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Section E: Assurance and oversight, Actions 1 to 5; Glossary, ''Gain assurance''","access":"free"},{"title":"Cyber Security Toolkit for Boards: Implementing effective cyber security measures","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/board-toolkit/principle-e-assurance-and-oversight/implementing-effective-cyber-security-measures","locator":"Principle E, sections on testing the effectiveness of controls and on metrics; version 3.0, reviewed 8 April 2025","access":"free"},{"title":"Cyber security breaches survey 2025/2026","publisher":"Department for Science, Innovation and Technology and Home Office","year":2026,"url":"https://www.gov.uk/government/statistics/cyber-security-breaches-survey-20252026/cyber-security-breaches-survey-20252026","locator":"Section 2.2, ''Board responsibilities'', Figures 2.6 to 2.8","access":"free"},{"title":"FCA Handbook, SYSC 15A: Operational resilience","publisher":"Financial Conduct Authority","year":2022,"url":"https://handbook.fca.org.uk/handbook/sysc15a","locator":"SYSC 15A.6.1R and 15A.7.1R (each dated 31/03/2022)","access":"free"},{"title":"FCA, Bank of England and Treasury joint statement on frontier AI models and cyber resilience","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/news/statements/fca-boe-treasury-joint-statement-frontier-ai-models-cyber-resilience","locator":"Section ''Governance and strategy''; footnote on status","access":"free"},{"title":"Provision 29 Mythbuster: Preparing to report","publisher":"Financial Reporting Council","year":2026,"url":"https://www.frc.org.uk/documents/9097/Provision_29_Mythbuster.pdf","locator":"Questions ''How many material controls should we have?'', ''Will boards have to seek external assurance over controls?'' and ''How should the declaration be worded?''","access":"free"},{"title":"Mythbuster: the auditor''s responsibilities in respect of the Provision 29 statement required by the UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2026,"url":"https://www.frc.org.uk/documents/9420/Provision_29_Mythbuster_June_2026_TR6phecr.pdf","locator":"Questions on whether the audit opinion covers the statement and whether the auditor tests the material controls","access":"free"},{"title":"FCA Handbook, UK Listing Rules, UKLR 6.6: Annual financial report","publisher":"Financial Conduct Authority","year":2025,"url":"https://handbook.fca.org.uk/handbook/uklr6","locator":"UKLR 6.6.6R(5) and (6) (dated 28/03/2025)","access":"free"},{"title":"FCA Handbook, Disclosure Guidance and Transparency Rules, DTR 7.2: Corporate governance statements","publisher":"Financial Conduct Authority","year":2016,"url":"https://handbook.fca.org.uk/handbook/dtr7","locator":"DTR 7.2.5R (dated 29/01/2016)","access":"free"},{"title":"Sarbanes-Oxley Act of 2002, section 404: Management assessment of internal controls","publisher":"United States Congress (U.S. Government Publishing Office)","year":2002,"url":"https://www.govinfo.gov/content/pkg/PLAW-107publ204/html/PLAW-107publ204.htm","locator":"Section 404(a) and (b); Public Law 107-204, 116 Stat. 789","access":"free"},{"title":"Prudential Standard CPS 234 Information Security","publisher":"Australian Prudential Regulation Authority","year":2019,"url":"https://handbook.apra.gov.au/standard/cps-234","locator":"Sections ''Roles and responsibilities'' and ''Testing control effectiveness''","access":"free"},{"title":"Final Notice: TSB Bank plc","publisher":"Financial Conduct Authority","year":2022,"url":"https://www.fca.org.uk/publication/final-notices/tsb-bank-plc-2022.pdf","locator":"Paragraph 2.36(c); penalty at paragraph 1.1","access":"free"},{"title":"Post Office Horizon IT Inquiry: Final Report, Volume 1","publisher":"Post Office Horizon IT Inquiry (Sir Wyn Williams)","year":2025,"url":"https://www.postofficehorizoninquiry.org.uk/sites/default/files/2025-07/Post%20Office%20Horizon%20IT%20Inquiry%20Final%20Report%20Volume%201_0.pdf","locator":"Chapter 1, Introduction, paragraphs 1.3 and 1.4; HC 1119","access":"free"},{"title":"Trusted third-party AI assurance roadmap","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/trusted-third-party-ai-assurance-roadmap/trusted-third-party-ai-assurance-roadmap","locator":"Section ''Challenges for a trusted third-party assurance market'', under ''Quality''","access":"free"},{"title":"Auditing large language models: a three-layered approach","publisher":"arXiv (Mökander, Schuett, Kirk and Floridi)","year":2023,"url":"https://arxiv.org/abs/2302.08500","locator":"Abstract","access":"free"},{"title":"Closing the AI Accountability Gap: Defining an End-to-End Framework for Internal Algorithmic Auditing","publisher":"arXiv (Raji, Smart, White, Mitchell, Gebru, Hutchinson, Smith-Loud, Theron and Barnes)","year":2020,"url":"https://arxiv.org/abs/2001.00973","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
