insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.1', '["**What it measures.** Whether the people who use AI for the organisation, employees and contractors alike, know enough to use it safely, and whether records show it.","**Why it matters.** Untrained staff paste confidential or personal information into public tools, accept wrong output and pass it on. Customers and the public are affected by work nobody checked; staff are blamed for errors they were never equipped to catch.","**The UK position.** No UK statute sets a general AI literacy duty. Organisations within the scope of the EU AI Act have, since February 2025, had to take measures to support the AI literacy of their staff and of others who operate or use AI on their behalf. The 2026 amendment added: \"This obligation does not require providers or deployers to guarantee any specific level of AI literacy of any individual.\" National authorities have been able to enforce it since August 2026. The European Commission says there is no duty to measure employees'' knowledge, but that relying on the instructions for use is not enough. Acas advises that staff may need training and that AI output should be checked for accuracy, tone and bias.","**What good looks like.** Training matched to role and tool, covering contractors; records of who was trained, on what and when; content refreshed when tools change; competence tested, not attendance counted.","**Reading the answer.** One recorded webinar, with no list of who watched, is the weak answer. So is a programme that stops at employees.","**A defensible figure.** In a government-commissioned survey of 801 UK employers, carried out in 2024 and published in January 2026, 11% said staff had undertaken AI training in the previous 12 months."]'::jsonb, true, '[{"title":"Regulation (EU) 2024/1689 (AI Act), Article 4: AI literacy","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-4","locator":"Art. 4(1)-(3), paragraphs marked ''AMENDED''","access":"free"},{"title":"Timeline for the Implementation of the EU AI Act","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/timeline/timeline-implementation-eu-ai-act","locator":"Entries for 02 Feb 2025 and 02 Aug 2026","access":"free"},{"title":"AI Literacy - Questions & Answers","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/faqs/ai-literacy-questions-answers","locator":"Answers on measuring knowledge, on whether training is mandatory, on ''other persons'', and on enforcement","access":"free"},{"title":"AI skills for life and work: employer survey findings","publisher":"Department for Science, Innovation and Technology (research by Ipsos)","year":2026,"url":"https://www.gov.uk/government/publications/ai-skills-for-life-and-work-employer-survey-findings/ai-skills-for-life-and-work-employer-survey-findings--2","locator":"Key findings; section 5, Figure 5.6; methodology (sample size 801, fieldwork 19 March to 7 June 2024)","access":"free"},{"title":"Research evidence, analysis and methodology: What works for AI upskilling in the UK","publisher":"Skills England (author: Dr Nisreen Ameen, Royal Holloway, University of London)","year":2026,"url":"https://www.gov.uk/government/publications/skills-for-ai-what-works-for-ai-upskilling-in-the-uk/research-evidence-analysis-and-methodology-what-works-for-ai-upskilling-in-the-uk","locator":"Executive summary and methodology","access":"free"},{"title":"One third of employers think AI will increase productivity","publisher":"Acas","year":2025,"url":"https://www.acas.org.uk/one-third-of-employers-think-ai-will-increase-productivity","locator":"''Some top tips for employers from Acas on the use of AI at work''","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 9: You have the skills and expertise needed to implement and use AI solutions","access":"free"},{"title":"AI Opportunities Action Plan","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-opportunities-action-plan/ai-opportunities-action-plan","locator":"Recommendations 14 to 19 (skills)","access":"free"},{"title":"Explaining decisions made with AI, Part 2, Task 5: Prepare implementers to deploy your AI system","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-2-explaining-ai-in-practice/task-5-prepare/","locator":"Introduction and ''Educate implementers about the strengths and limitations of AI decision-support systems''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 1, GOVERN 2.2","access":"free"},{"title":"UK GDPR, Article 39: Tasks of the data protection officer","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/39","locator":"Art. 39(1)(b)","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 1, provision 1.1.1","access":"free"},{"title":"R (Ayinde) v London Borough of Haringey; Al-Haroun v Qatar National Bank [2025] EWHC 1383 (Admin)","publisher":"High Court of Justice, King''s Bench Division (Divisional Court), via The National Archives Find Case Law","year":2025,"url":"https://caselaw.nationalarchives.gov.uk/ewhc/admin/2025/1383","locator":"Paragraph 9","access":"free"},{"title":"Artificial Intelligence (AI): Guidance for Judicial Office Holders","publisher":"Courts and Tribunals Judiciary","year":2025,"url":"https://www.judiciary.uk/wp-content/uploads/2025/10/Artificial-Intelligence-AI-Guidance-for-Judicial-Office-Holders-2.pdf","locator":"Section 3, part I: Understand AI and its applications","access":"free"},{"title":"Use of artificial intelligence in government (HC 612, Session 2023-24)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Summary, paragraph 20","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Section 4.5: Non-regulatory constraints to AI adoption","access":"free"},{"title":"The Impact of Generative AI on Critical Thinking: Self-Reported Reductions in Cognitive Effort and Confidence Effects From a Survey of Knowledge Workers","publisher":"Lee, Sarkar, Tankelevitch, Drosos, Rintel, Banks and Wilson; CHI 2025 (author copy hosted by Microsoft Research)","year":2025,"url":"https://www.microsoft.com/en-us/research/wp-content/uploads/2025/01/lee_2025_ai_critical_thinking_survey.pdf","locator":"Abstract (PDF page 1)","access":"free"},{"title":"A Brief AI Literacy Intervention Does Not Significantly Reduce Over-Reliance and Increases Under-Reliance on ChatGPT: A Randomized Study","publisher":"Puppart and Aru; arXiv","year":2025,"url":"https://arxiv.org/abs/2503.10556","locator":"Abstract","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Internal governance structures and measures, paragraph 3.7, item 2(iv) (printed page 23)","access":"free"}]'::jsonb, '2026-10-02')
