insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.2', '["**What it measures.** Whether those assigned to oversee AI systems can do the job: trained on the system, given time for each case, and free to overrule it.","**Why it matters.** An overseer with no training, a heavy caseload or a manager who frowns on overrides approves what the system proposes. People affected believe someone checked their case; the overseer carries blame for outcomes they could not change.","**The UK position.** UK data protection law turns on whether human involvement in a significant decision is meaningful, but says little about the person. The Information Commission (ICO), in guidance now under review, says reviewers need authority to override and confidence they will not be penalised, adding: \"This authority and confidence cannot be created by policies and training alone: a supportive organisational culture is also crucial\". Its audit toolkit expects a manageable caseload and a log of overrides with reasons. Its draft guidance on automated decisions, still in consultation, expects reviewers trained to understand the system''s logic, outputs, limitations and risks. The EU AI Act requires deployers of high-risk systems to assign oversight to people with the competence, training, authority and support needed; the European Commission''s published text applies this to listed high-risk uses from 2 December 2027.","**What good looks like.** Named overseers with system-specific training, refreshed on change; caseloads that allow attention to each case; written authority to overrule; override rates and sampled re-reviews reported.","**Reading the answer.** A name on a chart is the weak answer. Ask how many cases a reviewer handles daily, and when anyone last overruled the system.","**A defensible figure.** A 2022 peer-reviewed study surveyed 41 policies requiring human oversight of government algorithms and found evidence that people cannot perform the oversight expected."]'::jsonb, false, '[{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What is the role of human oversight?'', subsection ''How should we train our staff to address these risks?''","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure and its ''ways to meet our expectations'' list","access":"free"},{"title":"Automated decision-making, including profiling: What does the UK GDPR say about ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-does-the-uk-gdpr-say-about-adm/","locator":"Section ''What is a ''solely'' automated decision?'', list of criteria for meaningful human involvement","access":"free"},{"title":"Explaining decisions made with AI, Part 2, Task 5: Prepare implementers to deploy your AI system","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-2-explaining-ai-in-practice/task-5-prepare/","locator":"''At a glance'' and the passage on decision-automation bias","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(2) and 26(3)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, third paragraph, point (c)(i), marked ''AMENDED''","access":"free"},{"title":"AI Literacy - Questions & Answers","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/faqs/ai-literacy-questions-answers","locator":"Answer to ''Is an AI training mandatory for article 4 of the AI Act or are other AI literacy initiatives also allowed?''","access":"free"},{"title":"The flaws of policies requiring human oversight of government algorithms","publisher":"Ben Green, Computer Law & Security Review 45 (author''s copy on arXiv)","year":2022,"url":"https://arxiv.org/abs/2109.05067","locator":"Abstract","access":"free"},{"title":"On the Quest for Effective Human Oversight: Legal, Philosophical, and Technical Perspectives","publisher":"Sarah Sterz and others, ACM Conference on Fairness, Accountability, and Transparency 2024 (authors'' copy on arXiv)","year":2024,"url":"https://arxiv.org/abs/2404.04059","locator":"Abstract","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 2, MAP 3.4; Table 1, GOVERN 3.2","access":"free"},{"title":"FCA Handbook, SYSC 5.1: Skills, knowledge and expertise (competent employees rule)","publisher":"Financial Conduct Authority","year":2025,"url":"https://www.handbook.fca.org.uk/handbook/SYSC/5/1.html","locator":"SYSC 5.1.1R (text shown as in force from 23/10/2025)","access":"free"},{"title":"Supervisory Statement SS1/23: Model risk management principles for banks","publisher":"Prudential Regulation Authority, Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.4: Roles and responsibilities","access":"free"},{"title":"R (Bridges) v Chief Constable of South Wales Police [2020] EWCA Civ 1058","publisher":"Court of Appeal (Civil Division), via The National Archives Find Case Law","year":2020,"url":"https://caselaw.nationalarchives.gov.uk/ewca/civ/2020/1058","locator":"Paragraphs 184-185","access":"free"},{"title":"Institutionalised distrust and human oversight of artificial intelligence: towards a democratic design of AI governance under the European Union AI Act","publisher":"Laux; AI & Society 39, 2853-2866 (Springer)","year":2023,"url":"https://link.springer.com/article/10.1007/s00146-023-01777-z","locator":"Abstract","access":"free"},{"title":"Human-AI Interactions in Public Sector Decision-Making: \"Automation Bias\" and \"Selective Adherence\" to Algorithmic Advice","publisher":"Alon-Barkat and Busuioc; Journal of Public Administration Research and Theory (author copy on arXiv, v3)","year":2022,"url":"https://arxiv.org/pdf/2103.02381","locator":"Abstract (PDF page 1)","access":"free"},{"title":"Moral Crumple Zones: Cautionary Tales in Human-Robot Interaction","publisher":"Elish; Engaging Science, Technology, and Society, Vol. 5 (2019)","year":2019,"url":"https://estsjournal.org/index.php/ests/article/view/260","locator":"Abstract","access":"free"},{"title":"Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile (NIST AI 600-1)","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf","locator":"Suggested action MS-4.2-004; GOVERN 3.2 on roles for human-AI configurations and oversight","access":"free"}]'::jsonb, '2026-10-02')
