insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.3', '["**What it measures.** Whether systems are set up so a person can step in: a point to intervene before an output takes effect, reasons on screen, time to act and a way to stop.","**Why it matters.** When a screen shows a conclusion without reasons, and agreeing takes one click while disagreeing takes a form, people agree. The harm falls on people whose cases needed a second look, and on staff held responsible for decisions the design made.","**The UK position.** The UK GDPR requires safeguards to be built into processing when its means are chosen, and anyone subject to a significant, solely automated decision must be able to obtain human intervention. The Information Commission (ICO), in guidance now under review, says controls against automation bias belong in scoping and design, not only in training: \"Those in charge of designing the front-end interface of an AI system must understand the needs, thought processes, and behaviours of human reviewers and allow them to effectively intervene.\" It suggests a confidence score beside each output and testing options with reviewers early. The EU AI Act requires high-risk systems to be designed so that people can oversee, override and interrupt them; on the European Commission''s published timetable that duty does not yet apply.","**What good looks like.** A deployment standard: defined intervention points, reasons shown at decision time, overriding as easy as approving, a fall-back to manual working. Interventions are counted, designs tested with reviewers, suppliers held to the standard.","**Reading the answer.** A claim that staff can always override is weak if nobody ever has. Ask to see the reviewer''s screen and last quarter''s interventions.","**A defensible figure.** No defensible figure was found."]'::jsonb, false, '[{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What is the role of human oversight?'', subsections ''How can we address risks of automation bias?'' and ''How can we address risks of interpretability?''","access":"free"},{"title":"UK GDPR, Article 25: Data protection by design and by default","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/25","locator":"Art. 25(1)","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(2)(c)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 14: Human oversight","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-14","locator":"Art. 14(1), 14(3) and 14(4)(a)-(e)","access":"free"},{"title":"Timeline for the Implementation of the EU AI Act","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/timeline/timeline-implementation-eu-ai-act","locator":"Entry for 02 Dec 2027","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure, list of ways to meet expectations (fall back and hybrid working)","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 4: You have meaningful human control at the right stages","access":"free"},{"title":"Ethics, Transparency and Accountability Framework for Automated Decision-Making","publisher":"Cabinet Office","year":2023,"url":"https://www.gov.uk/government/publications/ethics-transparency-and-accountability-framework-for-automated-decision-making/ethics-transparency-and-accountability-framework-for-automated-decision-making","locator":"Section on explainability and human intervention","access":"free"},{"title":"Automation Bias in the AI Act: On the Legal Implications of Attempting to De-Bias Human Oversight of AI","publisher":"Johann Laux and Hannah Ruschemeier (authors'' copy on arXiv)","year":2025,"url":"https://arxiv.org/abs/2502.10036","locator":"Abstract","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 2, MAP 3.5","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 4: Enable human responsibility for AI systems, provisions 4.1 to 4.3","access":"free"},{"title":"Good machine learning practice for medical device development: guiding principles","publisher":"Medicines and Healthcare products Regulatory Agency (with the US FDA and Health Canada)","year":2021,"url":"https://www.gov.uk/government/publications/good-machine-learning-practice-for-medical-device-development-guiding-principles/good-machine-learning-practice-for-medical-device-development-guiding-principles","locator":"Guiding principle 7 (see also principle 9)","access":"free"},{"title":"When combinations of humans and AI are useful: A systematic review and meta-analysis","publisher":"Vaccaro, Almaatouq and Malone; Nature Human Behaviour","year":2024,"url":"https://www.nature.com/articles/s41562-024-02024-1","locator":"Abstract","access":"free"},{"title":"To Trust or to Think: Cognitive Forcing Functions Can Reduce Overreliance on AI in AI-assisted Decision-making","publisher":"Buçinca, Malaya and Gajos; arXiv (Proceedings of the ACM on Human-Computer Interaction, CSCW 2021)","year":2021,"url":"https://arxiv.org/abs/2102.09692","locator":"Abstract","access":"free"},{"title":"Does the Whole Exceed its Parts? The Effect of AI Explanations on Complementary Team Performance","publisher":"Bansal and others; arXiv (CHI 2021)","year":2021,"url":"https://arxiv.org/abs/2006.14779","locator":"Abstract","access":"free"},{"title":"Model Artificial Intelligence Governance Framework, Second Edition","publisher":"Infocomm Media Development Authority and Personal Data Protection Commission, Singapore","year":2020,"url":"https://www.pdpc.gov.sg/-/media/files/pdpc/pdf-files/resource-for-organisation/ai/sgmodelaigovframework2.pdf","locator":"Determining the level of human involvement in AI-augmented decision-making, item (c) Human-over-the-loop, following paragraph 3.13 (printed pages 30-31)","access":"free"}]'::jsonb, '2026-10-02')
