insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.4', '["**What it measures.** Whether the effect on jobs is assessed in writing before the board decides to adopt AI that changes work, and whether the board''s consideration is minuted.","**Why it matters.** People whose tasks, pay or posts will change tend to learn last. An assessment made beforehand lets redeployment, retraining or redesign be weighed while they are still options. Made afterwards, it is an explanation, not a safeguard.","**The UK position.** Directors must act to promote the success of the company and, in doing so, have regard among other matters to \"the interests of the company''s employees\". Companies must record minutes of directors'' meetings. Larger companies must publish a statement of how directors had regard to those matters, and the UK Corporate Governance Code asks boards to describe how they were considered in board discussions and decision-making. No UK law requires a workforce impact assessment for AI by that name, and the duty is owed to the company, not to staff. Redundancies proposed on a sufficient scale trigger collective consultation. Acas advises consulting workers and their representatives on introducing AI, and notes that expecting roles to use it could change terms and conditions.","**What good looks like.** A dated assessment before approval: roles touched, tasks removed and added, what happens to the people, transition costs, alternatives considered. The board''s discussion is minuted. Predicted effects are later compared with actual ones.","**Reading the answer.** Papers dated after the decision are the weak answer. So is an assessment that never mentions job losses.","**A defensible figure.** In the CIPD''s autumn 2025 survey of 2,019 UK employers, 17% expected the use of AI tools to reduce their headcount in the next 12 months."]'::jsonb, false, '[{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a) and (b)","access":"free"},{"title":"Companies Act 2006, section 414CZA: Section 172(1) statement","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CZA","locator":"s.414CZA(1) and (2)","access":"free"},{"title":"Companies Act 2006, section 248: Minutes of directors'' meetings","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/248","locator":"s.248(1)-(3)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 1, Principle E and Provision 5 (page 7)","access":"free"},{"title":"Trade Union and Labour Relations (Consolidation) Act 1992, section 188: Duty of employer to consult representatives","publisher":"legislation.gov.uk","year":1992,"url":"https://www.legislation.gov.uk/ukpga/1992/52/section/188","locator":"s.188(1), (1A) and (4)","access":"free"},{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1) and 35(9)","access":"free"},{"title":"1 in 4 workers worry that AI will lead to job losses","publisher":"Acas","year":2025,"url":"https://www.acas.org.uk/1-in-4-workers-worry-that-ai-will-lead-to-job-losses","locator":"''Some top tips for employers from Acas on the use of AI at work''","access":"free"},{"title":"Labour Market Outlook: Autumn 2025","publisher":"CIPD","year":2025,"url":"https://www.cipd.org/globalassets/media/knowledge/knowledge-hub/reports/2025-pdfs/9024-lmo-autumn-2025-report-web.pdf","locator":"Key points (page 5) and section on artificial intelligence (page 16 onwards)","access":"free"},{"title":"Generative AI and Jobs: A Refined Global Index of Occupational Exposure (ILO Working Paper 140)","publisher":"International Labour Organization","year":2025,"url":"https://webapps.ilo.org/static/english/intserv/working-papers/wp140/index.html","locator":"Abstract and Conclusion","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(7)","access":"free"},{"title":"Companies Act 2006, section 170: Scope and nature of general duties","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/170","locator":"s.170(1)","access":"free"},{"title":"Employment Rights Act 1996, section 139: Redundancy","publisher":"legislation.gov.uk","year":1996,"url":"https://www.legislation.gov.uk/ukpga/1996/18/section/139","locator":"s.139(1)(b)","access":"free"},{"title":"BTI 2014 LLC v Sequana SA and others [2022] UKSC 25","publisher":"UK Supreme Court, via The National Archives Find Case Law","year":2022,"url":"https://caselaw.nationalarchives.gov.uk/uksc/2022/25","locator":"Paragraphs 65-66 (Lord Reed); see also paragraph 74","access":"free"},{"title":"Corporate Governance Code Guidance","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/library/standards-codes-policy/corporate-governance/corporate-governance-code-guidance/","locator":"Section 1, Decision-making, paragraphs 30-31","access":"free"},{"title":"HSE''s regulatory approach to artificial intelligence (AI)","publisher":"Health and Safety Executive","year":2026,"url":"https://press.hse.gov.uk/2026/06/12/hses-regulatory-approach-to-artificial-intelligence-ai/","locator":"Policy statement, ''Assess and manage risks from AI in the workplace''","access":"free"},{"title":"Use of artificial intelligence in government (HC 612, Session 2023-24)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Part Three, paragraph 3.8, ''Assessing workforce impacts'' (also Summary paragraph 15)","access":"free"},{"title":"Assessment of AI capabilities and the impact on the UK labour market","publisher":"Department for Science, Innovation and Technology and AI Security Institute","year":2026,"url":"https://www.gov.uk/government/publications/assessment-of-ai-capabilities-and-the-impact-on-the-uk-labour-market/assessment-of-ai-capabilities-and-the-impact-on-the-uk-labour-market","locator":"Evidence judgement 2 (see also judgement 4 on hiring)","access":"free"},{"title":"Canaries in the Coal Mine? Six Facts about the Recent Employment Effects of Artificial Intelligence","publisher":"Brynjolfsson, Chandar and Chen; Stanford Digital Economy Lab working paper","year":2025,"url":"https://digitaleconomy.stanford.edu/wp-content/uploads/2025/08/Canaries_BrynjolfssonChandarChen.pdf","locator":"Section 1, summary of the six facts (abstract gives the same figure for ages 22-25)","access":"free"},{"title":"Good Work Algorithmic Impact Assessment: an approach for worker involvement","publisher":"Institute for the Future of Work","year":2023,"url":"https://www.ifow.org/publications/good-work-algorithmic-impact-assessment-an-approach-for-worker-involvement","locator":"Publication page, summary","access":"free"},{"title":"OECD AI Principles, Principle 2.4: Building human capacity and preparing for labour market transformation","publisher":"Organisation for Economic Co-operation and Development (OECD.AI)","year":2024,"url":"https://oecd.ai/en/dashboards/ai-principles/P13","locator":"Principle 2.4, second paragraph","access":"free"}]'::jsonb, '2026-10-02')
