insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.5', '["**What it measures.** Whether the people who will work with an AI system, or be managed by it, are told before it starts, and whether what they say can still change it.","**Why it matters.** A system that allocates shifts, scores performance or watches activity alters working lives. If it arrives unannounced, workers cannot ask how it judges them, warn where it will go wrong, or object. The harm is to dignity and fair treatment, and it falls on those with least say.","**The UK position.** No UK statute requires consultation on AI as such. Employers must consult employees or their safety representatives in good time on \"the health and safety consequences for those employees of the introduction (including the planning thereof) of new technologies into the workplace\". Where the statutory information and consultation provisions apply, representatives must be consulted on decisions likely to bring substantial changes in work organisation. Data protection law tells a controller assessing high-risk processing to seek, where appropriate, the views of the people affected, and the Information Commission (ICO) expects employers planning monitoring to seek and record workers'' views. The EU AI Act goes further where it applies: employers must inform workers and their representatives before a high-risk system is used at work.","**What good looks like.** Representatives and affected staff briefed before the decision is final; their comments recorded, answered and visibly acted on.","**Reading the answer.** An announcement at launch is the usual weak answer. Ask what changed because of what staff said.","**A defensible figure.** The general right to be informed and consulted covers only undertakings with at least 50 employees and, unless the employer acts first, only once 2% of them, and no fewer than 15, have asked."]'::jsonb, false, '[{"title":"The Health and Safety (Consultation with Employees) Regulations 1996, regulation 3: Duty of employer to consult","publisher":"legislation.gov.uk","year":1996,"url":"https://www.legislation.gov.uk/uksi/1996/1513/regulation/3","locator":"Reg. 3, opening words and (e)","access":"free"},{"title":"The Safety Representatives and Safety Committees Regulations 1977, regulation 4A: Employer''s duty to consult and provide facilities and assistance","publisher":"legislation.gov.uk","year":1977,"url":"https://www.legislation.gov.uk/uksi/1977/500/regulation/4A","locator":"Reg. 4A(1), opening words and (e)","access":"free"},{"title":"The Information and Consultation of Employees Regulations 2004, regulation 20: Standard information and consultation provisions","publisher":"legislation.gov.uk","year":2004,"url":"https://www.legislation.gov.uk/uksi/2004/3426/regulation/20","locator":"Reg. 20(1)(c), (2), (3) and (4)","access":"free"},{"title":"The Information and Consultation of Employees Regulations 2004, regulation 7: Employee request to negotiate an agreement","publisher":"legislation.gov.uk","year":2004,"url":"https://www.legislation.gov.uk/uksi/2004/3426/regulation/7","locator":"Reg. 7(2) and (3); Schedule 1 for the 50-employee threshold","access":"free"},{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(9)","access":"free"},{"title":"Employment practices and data protection: monitoring workers. Data protection and monitoring workers","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/employment/monitoring-workers/data-protection-and-monitoring-workers/","locator":"Section ''Should we discuss the introduction of monitoring with our workers?''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(7)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 1, Provision 5 (PDF page 8)","access":"free"},{"title":"Employment Rights Act 2025, section 29: Collective redundancy: extended application of requirements","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/36/section/29","locator":"s.29(2)","access":"free"},{"title":"My boss the algorithm: an ethical look at algorithms in the workplace","publisher":"Acas","year":2020,"url":"https://www.acas.org.uk/research-and-commentary/my-boss-the-algorithm-an-ethical-look-at-algorithms-in-the-workplace/paper","locator":"Executive summary; section ''Involving the workforce''","access":"free"},{"title":"Consulting employees on health and safety: A brief guide to the law (INDG232 rev2)","publisher":"Health and Safety Executive","year":2013,"url":"https://www.hse.gov.uk/pubns/indg232.pdf","locator":"PDF page 3, ''What should consultation with employees involve?''; PDF page 2 for the list of matters, including new technology","access":"free"},{"title":"Managing technology that manages people: November 2025. A Social Partnership approach to algorithmic management systems in the Welsh public sector","publisher":"Welsh Government (guidance agreed by the Workforce Partnership Council)","year":2025,"url":"https://www.gov.wales/managing-technology-manages-people-november-2025-html","locator":"Section ''After a new system starts being used''; also ''Before adoption and implementation'' and ''Due diligence and consultation during buying or building systems''","access":"free"},{"title":"Protection of workers'' personal data: An ILO code of practice","publisher":"International Labour Office","year":1997,"url":"https://www.ilo.org/sites/default/files/wcmsp5/groups/public/@ed_protect/@protrav/@safework/documents/normativeinstrument/wcms_107797.pdf","locator":"Section 12, Collective rights, paragraph 12.2(a) and (b) (PDF page 19); paragraph 5.8","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and (2)(a) to (d); textual amendment note F1","access":"free"},{"title":"Robots, Digitalization, and Worker Voice (GLO Discussion Paper No. 1038)","publisher":"Filippo Belloc, Gabriel Burdin and Fabio Landini, Global Labor Organization (EconStor repository)","year":2022,"url":"https://www.econstor.eu/bitstream/10419/249341/1/GLO-DP-1038.pdf","locator":"Abstract (PDF page 2) and Introduction (PDF page 4)","access":"free"},{"title":"Advanced Digital Technologies in Unionized Firms","publisher":"Fabio Berton, Stefano Dughera and Andrea Ricci, Italian Economic Journal (Springer, open access)","year":2024,"url":"https://link.springer.com/article/10.1007/s40797-024-00276-4","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
