insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.6', '["**What it measures.** Whether the default, when AI changes a job, is to redesign the work around people, and whether success is measured by output and quality instead of posts removed.","**Why it matters.** The choice decides who gains. One economist puts it this way: \"when AI is focused on augmenting humans rather than mimicking them, then humans retain the power to insist on a share of the value created\". Where the aim is replacement, workers lose income and bargaining power, and the organisation loses the judgement it needs to check the machine. Field evidence from customer support found that AI used to assist raised productivity, most of all for the least experienced.","**The UK position.** No UK law requires augmentation. Directors must have regard to the interests of employees and to long-term consequences when promoting the company''s success. Where collective redundancies are proposed, the employer must consult representatives on ways of avoiding the dismissals and reducing their number, with a view to reaching agreement. Official statistics show that most businesses using AI report no change in headcount so far.","**What good looks like.** A written default of redesign; any departure justified case by case; managers'' targets set on throughput and quality; results reported to the board like any other strategy.","**Reading the answer.** Listen for the double message: augmentation in the staff briefing, headcount savings in the business case. Ask which measure managers are rewarded on.","**A defensible figure.** In the Office for National Statistics survey published in July 2026, just under 7% of medium-sized businesses using AI reported that it had reduced their headcount, the highest of any size band; most businesses reported no change."]'::jsonb, false, '[{"title":"Trade Union and Labour Relations (Consolidation) Act 1992, section 188: Duty of employer to consult representatives","publisher":"legislation.gov.uk","year":1992,"url":"https://www.legislation.gov.uk/ukpga/1992/52/section/188","locator":"s.188(1), (1A) and (2); notes F2, F4","access":"free"},{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a) and (b)","access":"free"},{"title":"Artificial intelligence in UK businesses: 2023 to 2026","publisher":"Office for National Statistics","year":2026,"url":"https://www.ons.gov.uk/businessindustryandtrade/business/businessservices/articles/artificialintelligenceinukbusinesses/2023to2026","locator":"Section ''Labour market effects'' and Figure 7","access":"free"},{"title":"Assessment of AI capabilities and the impact on the UK labour market","publisher":"Department for Science, Innovation and Technology and AI Security Institute","year":2026,"url":"https://www.gov.uk/government/publications/assessment-of-ai-capabilities-and-the-impact-on-the-uk-labour-market/assessment-of-ai-capabilities-and-the-impact-on-the-uk-labour-market","locator":"Figure 2 and the paragraph above it","access":"free"},{"title":"Generative AI at Work","publisher":"Erik Brynjolfsson, Danielle Li and Lindsey Raymond (arXiv preprint 2304.11771)","year":2024,"url":"https://arxiv.org/pdf/2304.11771","locator":"Abstract, page 1","access":"free"},{"title":"Experimental Evidence on the Productivity Effects of Generative Artificial Intelligence","publisher":"Shakked Noy and Whitney Zhang, MIT (working paper)","year":2023,"url":"https://economics.mit.edu/sites/default/files/inline-files/Noy_Zhang_1.pdf","locator":"Abstract, page 1","access":"free"},{"title":"The Turing Trap: The Promise & Peril of Human-Like Artificial Intelligence","publisher":"Erik Brynjolfsson, Stanford Digital Economy Lab (arXiv preprint 2201.04200)","year":2022,"url":"https://arxiv.org/pdf/2201.04200","locator":"Abstract, page 1","access":"free"},{"title":"Generative AI and Jobs: A global analysis of potential effects on job quantity and quality (ILO Working Paper 96)","publisher":"International Labour Organization","year":2023,"url":"https://www.ilo.org/sites/default/files/wcmsp5/groups/public/@dgreports/@inst/documents/publication/wcms_890761.pdf","locator":"Abstract (PDF page 4)","access":"free"},{"title":"The Future of Jobs Report 2025","publisher":"World Economic Forum","year":2025,"url":"https://reports.weforum.org/docs/WEF_Future_of_Jobs_Report_2025.pdf","locator":"Key findings, page 6; chapter 2, ''The shifting human-machine frontier: automation versus augmentation''","access":"free"},{"title":"The Wrong Kind of AI? Artificial Intelligence and the Future of Labor Demand (IZA Discussion Paper No. 12292)","publisher":"Daron Acemoglu and Pascual Restrepo, IZA Institute of Labor Economics","year":2019,"url":"https://docs.iza.org/dp12292.pdf","locator":"Abstract (PDF page 3)","access":"free"},{"title":"New Frontiers: The Origins and Content of New Work, 1940-2018 (NBER Working Paper 30389)","publisher":"David Autor, Caroline Chin, Anna Salomons and Bryan Seegmiller, National Bureau of Economic Research","year":2022,"url":"https://www.nber.org/system/files/working_papers/w30389/w30389.pdf","locator":"Abstract (PDF page 2)","access":"free"},{"title":"Can we Have Pro-Worker AI? Choosing a path of machines in service of minds (policy memo)","publisher":"Daron Acemoglu, David Autor and Simon Johnson, MIT Shaping the Future of Work Initiative","year":2023,"url":"https://shapingwork.mit.edu/wp-content/uploads/2023/09/Pro-Worker-AI-Policy-Memo.pdf","locator":"Summary, page 1 (PDF page 2)","access":"free"},{"title":"Large Language Models, Small Labor Market Effects (Becker Friedman Institute Working Paper No. 2025-56)","publisher":"Anders Humlum and Emilie Vestergaard, University of Chicago, Becker Friedman Institute","year":2025,"url":"https://bfi.uchicago.edu/wp-content/uploads/2025/04/BFI_WP_2025-56-1.pdf","locator":"Abstract (PDF page 2); Introduction for the share of workers with new tasks","access":"free"},{"title":"Transformed by AI: How generative artificial intelligence could affect work in the UK - and how to manage it","publisher":"Carsten Jung and Bhargav Srinivasa Desikan, Institute for Public Policy Research","year":2024,"url":"https://ippr-org.files.svdcdn.com/production/Downloads/Transformed_by_AI_March24_2024-03-27-121003_kxis.pdf","locator":"Summary, page 7 (PDF page 7); chapter 4, section 4.1","access":"free"},{"title":"Companies Act 2006, section 414CB: Contents of non-financial and sustainability information statement","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CB","locator":"s.414CB(1)(b) and (2)(b) to (e)","access":"free"},{"title":"OECD AI Principles, Principle 2.4: Building human capacity and preparing for labour market transformation","publisher":"Organisation for Economic Co-operation and Development (OECD.AI)","year":2024,"url":"https://oecd.ai/en/dashboards/ai-principles/P13","locator":"Rationale for this principle, third paragraph","access":"free"},{"title":"Managing technology that manages people: November 2025. A Social Partnership approach to algorithmic management systems in the Welsh public sector","publisher":"Welsh Government (guidance agreed by the Workforce Partnership Council)","year":2025,"url":"https://www.gov.wales/managing-technology-manages-people-november-2025-html","locator":"Section ''General principles'', principle 5 (Jobs); principle 4 (Building capability)","access":"free"}]'::jsonb, '2026-10-02')
