insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.7', '["**What it measures.** Whether staff know which AI tools they may use and for what, and whether the organisation finds out about the tools it never approved.","**Why it matters.** People paste customer records, staff files and confidential plans into free tools nobody has assessed. The individuals whose information it is never agreed to that and will never know. The organisation cannot protect what it cannot see.","**The UK position.** No law names shadow AI. Data protection law requires a controller to take steps so that anyone acting under its authority handles personal data only on its instructions, and to pass personal data to an outside service only under a binding contract. The National Cyber Security Centre treats unapproved AI as a form of shadow IT. It says such use is rarely malicious and usually shows that approved tools fall short, and it warns: \"If you blame or punish staff, their peers will be reluctant to tell you about their own unsanctioned practices\". It advises a simple, quick process for requests and tells users not to put sensitive information into public AI tools. Government research found that very few businesses had any internal policy on AI.","**What good looks like.** A short policy written for staff: approved tools, information that must never be entered, a fast route to request something new. Unapproved use found by asking without blame and by technical monitoring, and tracked over time.","**Reading the answer.** A policy nobody has read, backed by a slow approval queue, is the usual weak answer. A ban alone hides the problem.","**A defensible figure.** In a 2025 survey across 47 countries, 70% of employees who use AI at work said they use free, publicly available tools."]'::jsonb, false, '[{"title":"Shadow IT","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/guidance/shadow-it","locator":"Sections ''What is shadow IT?'', ''What can you learn from shadow IT?'' and ''Organisational mitigations''","access":"free"},{"title":"ChatGPT and large language models: what''s the risk?","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/blog-post/chatgpt-and-large-language-models-whats-the-risk","locator":"Section on whether queries are visible to the provider; recommendations","access":"free"},{"title":"AI and cyber security: what you need to know","publisher":"National Cyber Security Centre","year":2024,"url":"https://www.ncsc.gov.uk/guidance/ai-and-cyber-security-what-you-need-to-know","locator":"Section ''Questions to ask about the security of your organisation''s AI systems''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1) and (4)","access":"free"},{"title":"UK GDPR, Article 28: Processor","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/28","locator":"Art. 28(1) and (3)","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 3; section ''Public AI applications and web services''","access":"free"},{"title":"AI adoption research","publisher":"Department for Science, Innovation and Technology","year":2026,"url":"https://www.gov.uk/government/publications/ai-adoption-research/ai-adoption-research","locator":"Methodology (limitations); qualitative findings on responsible use","access":"free"},{"title":"Trust, attitudes and use of artificial intelligence: A global study 2025","publisher":"University of Melbourne and KPMG International","year":2025,"url":"https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/2025/05/trust-attitudes-and-use-of-ai-global-report.pdf","locator":"Page 69 (PDF page 72); Figure 41 on page 71; executive summary (PDF page 8)","access":"free"},{"title":"2024 Work Trend Index Annual Report: AI at work is here. Now comes the hard part","publisher":"Microsoft and LinkedIn","year":2024,"url":"https://www.microsoft.com/en-us/worklab/work-trend-index/ai-at-work-is-here-now-comes-the-hard-part","locator":"First finding, on employees bringing their own AI to work","access":"free"},{"title":"R (Ayinde) v London Borough of Haringey; Al-Haroun v Qatar National Bank QPSC [2025] EWHC 1383 (Admin)","publisher":"High Court of Justice, King''s Bench Division, Divisional Court (The National Archives, Find Case Law)","year":2025,"url":"https://caselaw.nationalarchives.gov.uk/ewhc/admin/2025/1383","locator":"Paragraphs 6 to 9","access":"free"},{"title":"Artificial Intelligence (AI) Guidance for Judicial Office Holders","publisher":"Courts and Tribunals Judiciary","year":2025,"url":"https://www.judiciary.uk/wp-content/uploads/2025/10/Artificial-Intelligence-AI-Guidance-for-Judicial-Office-Holders-2.pdf","locator":"Section 3, part II ''Uphold confidentiality and privacy'' (PDF page 5)","access":"free"},{"title":"Risk Outlook report: The use of artificial intelligence in the legal market","publisher":"Solicitors Regulation Authority","year":2023,"url":"https://www.sra.org.uk/sra/research-publications/artificial-intelligence-legal-market/","locator":"Section ''Confidentiality and privacy''; section ''Accountability''","access":"free"},{"title":"UK GDPR, Article 24: Responsibility of the controller","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/24","locator":"Art. 24(1) and (2)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile (NIST AI 600-1)","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf","locator":"Suggested action GV-3.2-003 under GOVERN 3.2 (PDF page 22); also GV-1.4-002 and GV-1.6-001","access":"free"},{"title":"Generative artificial intelligence (AI) in education","publisher":"Department for Education","year":2025,"url":"https://www.gov.uk/government/publications/generative-artificial-intelligence-in-education/generative-artificial-intelligence-ai-in-education","locator":"Paragraph beginning ''Schools and colleges should also consider''; section ''Data privacy''","access":"free"},{"title":"From Frontier to Shadow AI: A Simmering Threat to Assurance and Security in Critical Infrastructure (arXiv preprint 2606.00088)","publisher":"Mohan Baruwal Chhetri and others, CSIRO","year":2026,"url":"https://arxiv.org/pdf/2606.00088","locator":"Abstract, page 1","access":"free"},{"title":"The Adoption of ChatGPT (Becker Friedman Institute Working Paper No. 2024-50)","publisher":"Anders Humlum and Emilie Vestergaard, University of Chicago, Becker Friedman Institute","year":2024,"url":"https://bfi.uchicago.edu/wp-content/uploads/2024/04/BFI_WP_2024-50.pdf","locator":"Introduction (PDF page 5); abstract (PDF page 2)","access":"free"}]'::jsonb, '2026-10-02')
