insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.8', '["**What it measures.** Whether the organisation knows which human skills it must keep as AI takes over tasks, and has a way of keeping them in use.","**Why it matters.** Skills that are not practised fade. Researchers describe the irony: automate the routine and \"you deprive the user of the routine opportunities to practice their judgement\", so people are unprepared when the exception arrives. Those harmed are the customers and colleagues who rely on a human check that no longer works, and the junior staff who never learn the craft.","**The UK position.** No UK law addresses loss of skill through AI. Employers must take employees'' capabilities into account when entrusting tasks, and must train them when new technology brings new risks, but those duties concern health and safety. The Health and Safety Executive expects refresher training for infrequent, complex or safety-critical tasks. Aviation met the problem first: a Civil Aviation Authority paper warned that crews relying on automation might lose manual flying skills, and the United States regulator later asked airlines to make room for manual flying.","**What good looks like.** For each significant automation, a recorded decision on what people must still be able to do and how that is kept up: rotation through manual cases, deliberate practice, checks. Capability is tested, not assumed.","**Reading the answer.** An assurance that people would cope, offered without evidence, is the weak answer. Ask when the manual process was last run.","**A defensible figure.** In a 2026 trial, not yet peer reviewed, 52 software developers learned a new tool; those given AI assistance scored 17% lower on a test of understanding afterwards."]'::jsonb, false, '[{"title":"The Management of Health and Safety at Work Regulations 1999, regulation 13: Capabilities and training","publisher":"legislation.gov.uk","year":1999,"url":"https://www.legislation.gov.uk/uksi/1999/3242/regulation/13","locator":"Reg. 13(1) and (2)(b)(iii)","access":"free"},{"title":"Human factors: Training and competence","publisher":"Health and Safety Executive","year":2026,"url":"https://www.hse.gov.uk/humanfactors/topics/competence.htm","locator":"Section ''Key principles in competence''","access":"free"},{"title":"CAA Paper 2004/10: Flight Crew Reliance on Automation","publisher":"Civil Aviation Authority","year":2004,"url":"https://www.caa.co.uk/publication/download/12922","locator":"Executive Summary, page v","access":"free"},{"title":"Safety Alert for Operators 13002: Manual Flight Operations","publisher":"Federal Aviation Administration","year":2013,"url":"https://www.faa.gov/sites/faa.gov/files/other_visit/aviation_industry/airline_operators/airline_safety/SAFO13002.pdf","locator":"Discussion, page 1","access":"free"},{"title":"The Impact of Generative AI on Critical Thinking: Self-Reported Reductions in Cognitive Effort and Confidence Effects From a Survey of Knowledge Workers","publisher":"Hao-Ping (Hank) Lee and others, Carnegie Mellon University and Microsoft Research (CHI 2025)","year":2025,"url":"https://www.microsoft.com/en-us/research/wp-content/uploads/2025/01/lee_2025_ai_critical_thinking_survey.pdf","locator":"Abstract and Introduction, page 1","access":"free"},{"title":"How AI Impacts Skill Formation","publisher":"Judy Hanwen Shen and Alex Tamkin (arXiv preprint 2601.20245)","year":2026,"url":"https://arxiv.org/pdf/2601.20245","locator":"Abstract, page 1; results, page 2; section 4.3 for the sample","access":"free"},{"title":"Your Brain on ChatGPT: Accumulation of Cognitive Debt when Using an AI Assistant for Essay Writing Task","publisher":"Nataliya Kosmyna and others, MIT Media Lab (arXiv preprint 2506.08872)","year":2025,"url":"https://arxiv.org/pdf/2506.08872","locator":"Abstract, PDF page 2","access":"free"},{"title":"The Future of Jobs Report 2025","publisher":"World Economic Forum","year":2025,"url":"https://reports.weforum.org/docs/WEF_Future_of_Jobs_Report_2025.pdf","locator":"Key findings, page 6","access":"free"},{"title":"Does using artificial intelligence assistance accelerate skill decay and hinder skill development without performers'' awareness?","publisher":"Brooke N. Macnamara and others, Cognitive Research: Principles and Implications (Springer, open access)","year":2024,"url":"https://link.springer.com/article/10.1186/s41235-024-00572-8","locator":"Abstract","access":"free"},{"title":"AI-induced Deskilling in Medicine: A Mixed-Method Review and Research Agenda for Healthcare and Beyond","publisher":"Chiara Natali, Luca Marconi, Leslye Denisse Dias Duran and Federico Cabitza, Artificial Intelligence Review (Springer, open access)","year":2025,"url":"https://link.springer.com/article/10.1007/s10462-025-11352-1","locator":"Abstract; section 2.1 for the systematic review method","access":"free"},{"title":"The Vicious Circles of Skill Erosion: A Case Study of Cognitive Automation","publisher":"Tapani Rinta-Kahila and others, Journal of the Association for Information Systems, 24(5), 1378-1412 (AIS eLibrary)","year":2023,"url":"https://aisel.aisnet.org/jais/vol24/iss5/2/","locator":"Abstract on the journal''s own page","access":"free"},{"title":"Enhanced FAA Oversight Could Reduce Hazards Associated With Increased Use of Flight Deck Automation (Audit Report AV-2016-013)","publisher":"U.S. Department of Transportation, Office of Inspector General","year":2016,"url":"https://www.oig.dot.gov/sites/default/files/FAA%20Flight%20Decek%20Automation_Final%20Report%5E1-7-16.pdf","locator":"Results in Brief, page 2 (PDF page 3)","access":"free"},{"title":"FCA Handbook, Training and Competence sourcebook, TC 2.1: Assessing and maintaining competence","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.handbook.fca.org.uk/handbook/TC/2/1.html","locator":"TC 2.1.12R (maintaining competence); TC 2.1.13G","access":"free"},{"title":"GRI 404: Training and Education 2016","publisher":"Global Reporting Initiative","year":2016,"url":"https://www.globalreporting.org/publications/documents/english/gri-404-training-and-education-2016/","locator":"Disclosure 404-3, guidance (background); Disclosure 404-2, requirements","access":"free"},{"title":"OECD AI Principles, Principle 2.4: Building human capacity and preparing for labour market transformation","publisher":"Organisation for Economic Co-operation and Development (OECD.AI)","year":2024,"url":"https://oecd.ai/en/dashboards/ai-principles/P13","locator":"Rationale for this principle, third paragraph","access":"free"},{"title":"Managing technology that manages people: November 2025. A Social Partnership approach to algorithmic management systems in the Welsh public sector","publisher":"Welsh Government (guidance agreed by the Workforce Partnership Council)","year":2025,"url":"https://www.gov.wales/managing-technology-manages-people-november-2025-html","locator":"Section ''Due diligence and consultation during buying or building systems''; general principle 4 (Building capability)","access":"free"}]'::jsonb, '2026-10-02')
