insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.1', '["**What it measures.** Whether the organisation knows which customers, lenders and public buyers must report on sustainability, which duties reach it as a supplier, and what each may ask.","**Why it matters.** A reporting duty placed on a large company travels down to its suppliers as questionnaires. A firm caught by surprise answers with guesses, and guessed figures pass into reports that investors, lenders and the public rely on. That includes the energy its AI tools use. The EU legislator recorded: \"There is evidence that undertakings in the value chain, including small and medium-sized enterprises, receive disproportionate requests for information from reporting undertakings\".","**The UK position.** No UK law was found that limits what a customer may ask. An EU customer must report only if it exceeds both EUR 450 million net turnover and 1,000 employees (Directive (EU) 2026/470). Financial Conduct Authority rules require listed companies to report against UK Sustainability Reporting Standards for periods from 1 January 2027, with value-chain emissions on a comply-or-explain basis. Quoted and large companies must report energy and carbon. Central government asks bidders for a Carbon Reduction Plan on contracts above £5 million a year.","**What good looks like.** A written map: each major customer, lender and public buyer; the duty it is under; the data it may legitimately ask for; revised when clients or thresholds change.","**Reading the answer.** Knowing who the big customers are is not knowing their obligations. Ask for the map and its date. One drawn before 2026 is out of date.","**A defensible figure.** The European Commission estimates that the 2026 directive cut the number of companies in scope of mandatory EU sustainability reporting by about 85% (staff working document SWD(2026) 500, printed page 3)."]'::jsonb, true, '[{"title":"Directive (EU) 2026/470 amending Directives 2006/43/EC, 2013/34/EU, (EU) 2022/2464 and (EU) 2024/1760 (the Omnibus I Directive)","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/2f337274-12b4-11f1-8870-01aa75ed71a1.0006.03/DOC_1","locator":"Recital 12; Article 2(1), (4) and (5), amending Articles 1(3), 19a and 29a of Directive 2013/34/EU; Article 3, amending Article 5(2) of Directive (EU) 2022/2464; Articles 5 and 6","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Section on the context of the ESRS revision, PDF page 4 (printed page 3); section 2.3, PDF page 10 (printed page 9); passage on the value chain cap, PDF page 6 (printed page 5)","access":"free"},{"title":"Directive (EU) 2025/794 as regards the dates from which Member States are to apply certain corporate sustainability reporting and due diligence requirements (the ''stop-the-clock'' Directive)","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2025,"url":"http://publications.europa.eu/resource/cellar/8a789948-1a5f-11f0-b1a3-01aa75ed71a1.0006.03/DOC_1","locator":"Article 1 (amending Article 5(2) of Directive (EU) 2022/2464); Article 3 (transposition by 31 December 2025)","access":"free"},{"title":"Corporate sustainability reporting","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/capital-markets-union-and-financial-markets/company-reporting-and-auditing/company-reporting/corporate-sustainability-reporting_en","locator":"Sections ''What the EU is doing and why'' and ''Policy making timeline'' (entries for 14 April 2025, 30 July 2025, 9 December 2025 and 3 July 2026)","access":"free"},{"title":"PS26/19: Aligning listed issuers'' sustainability disclosures with international standards","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/publications/policy-statements/ps26-19-aligning-listed-issuers-sustainability-disclosures-international-standards","locator":"Sections ''Who this is for'' and ''Next steps''","access":"free"},{"title":"UK Sustainability Reporting Standards","publisher":"Department for Business and Trade","year":2026,"url":"https://www.gov.uk/guidance/uk-sustainability-reporting-standards","locator":"Section ''What the UK is doing''","access":"free"},{"title":"Companies Act 2006, section 414CA: Non-financial and sustainability information statement","publisher":"legislation.gov.uk","year":2022,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CA","locator":"s.414CA(A1), (1), (1A), (2A), (3) and (4)","access":"free"},{"title":"Streamlined Energy and Carbon Reporting (SECR) regulations: evaluation","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://www.gov.uk/government/publications/streamlined-energy-and-carbon-reporting-secr-regulations-evaluation","locator":"Landing page, ''Details''; report reference RAF019/2425 (112 pages)","access":"free"},{"title":"PPN 006: Taking account of Carbon Reduction Plans in the procurement of major government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-taking-account-of-carbon-reduction-plans-html","locator":"Paragraphs 3, 4 and 11; footnote 5","access":"free"},{"title":"Modernising corporate reporting: consultation document","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/6aa913c42344967b89b087ed/modernising-corporate-reporting-consultation-document.pdf","locator":"Paragraphs 6, 149 to 150 and 154 to 158 (PDF pages 42 to 43)","access":"free"},{"title":"Commission Delegated Regulation (EU) 2026/1563 amending Delegated Regulation (EU) 2023/2772 as regards the simplification of certain sustainability reporting standards","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/7c16cdc5-b556-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Annex, ESRS 1 General Requirements, chapter 5, paragraphs 62 to 66; Article 3 (entry into force and application)","access":"free"},{"title":"UK SRS S1: General Requirements for Disclosure of Sustainability-related Financial Information","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/699dd3b007d7bff3604d6c5e/uk_srs_1_general_requirements_for_disclosure_of_sustainability_related_financial_information.pdf","locator":"Appendix A, defined term ''value chain'' (printed page 21, PDF page 25); paragraph 2 (PDF page 7); Appendix B, paragraph B5 (printed page 23, PDF page 27)","access":"free"},{"title":"Supervisory statement 5/25: Enhancing banks'' and insurers'' approaches to managing climate-related risks","publisher":"Bank of England, Prudential Regulation Authority","year":2025,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2025/ss425-december-2025.pdf","locator":"Paragraphs 4.25 to 4.31 (printed pages 17 to 18, PDF pages 19 to 20); chapter 1, ''Scope'' (printed page 4); commencement at paragraph 3.1","access":"free"},{"title":"Scope 3 Emissions in the UK Reporting Landscape: Call for Evidence Analysis Report","publisher":"Department for Energy Security and Net Zero","year":2024,"url":"https://assets.publishing.service.gov.uk/media/67499f7e75bb645366b3a1e7/summary-of-responses-call-for-evidence-scope-3-emissions-reporting.pdf","locator":"Chapter 2, ''SME Impacts'', PDF page 18; introduction, PDF page 6 (184 responses)","access":"free"},{"title":"SMEs and Net Zero 2025: UK Net Zero Business Census report","publisher":"British Business Bank","year":2025,"url":"https://www.british-business-bank.co.uk/sites/g/files/sovrnj166/files/2025-10/smes-net-zero-report-2025.pdf","locator":"''Tracking and measuring carbon emissions'', page 17; summary table, page 16; Appendix I (survey sample and methodology), page 48","access":"free"},{"title":"Data Requests in Value Chains: The Effects of Corporate Sustainability Reporting on SMEs in The Netherlands","publisher":"Niemann, Morssinkhof, van der Linden and de Vries, Sustainability 17(17), 8029 (MDPI); copy held in the Delft University of Technology repository","year":2025,"url":"https://repository.tudelft.nl/file/File_45575c22-db6d-40bd-b5d7-d43ab0c97965","locator":"Abstract (article page 1, PDF page 2); section 3.1 and Figure 1 (article page 5, PDF page 6)","access":"free"},{"title":"Dear supplier, how sustainable are you? A multiple-case study analysis of a widespread tool for sustainable supply chain management","publisher":"Fraser and co-authors, Sustainability Management Forum 28, 127-149 (Springer)","year":2020,"url":"https://link.springer.com/article/10.1007/s00550-020-00507-z","locator":"Abstract","access":"free"},{"title":"Fostering convergence in SME sustainability reporting (OECD SME and Entrepreneurship Papers)","publisher":"OECD","year":2025,"url":"https://www.oecd.org/content/dam/oecd/en/publications/reports/2025/02/fostering-convergence-in-sme-sustainability-reporting_133eb77f/ffbf16fb-en.pdf","locator":"Section 1 (printed page 10, PDF page 11); executive summary (printed page 6, PDF page 7)","access":"free"}]'::jsonb, '2026-10-02')
