insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.2', '["**What it measures.** Whether the organisation can produce the basic data set that the EU''s voluntary standard defines: energy, emissions, water, waste, workforce, safety, pay and conduct.","**Why it matters.** Customers and lenders build their own public reports on suppliers'' numbers. A firm that reconstructs its figures for each questionnaire gives different answers to different askers, and nobody can tell which is right. The people misled are those who rely on the customer''s report. Energy used by AI systems is part of the footprint and is easily left out.","**The UK position.** The Basic Module is EU law, not UK law: Annex I to Commission Delegated Regulation (EU) 2026/1560, published on 21 September 2026, which supersedes the Commission''s 2025 Recommendation of EFRAG''s standard. It has eleven disclosures, B1 to B11. The regulation says: \"This module is the target approach for micro-undertakings and constitutes a minimum requirement for other undertakings\". Several environmental items are voluntary for firms with ten employees or fewer. No UK equivalent for small firms was found: energy and carbon reporting binds quoted and large companies, and government encourages others to report voluntarily.","**What good looks like.** One maintained data set covering B1 to B11, a named owner, the method noted beside each figure, and a yearly refresh.","**Reading the answer.** Energy bills in a folder are fragments. Ask when the set was last refreshed and whether the emissions method is written down. The standard asks for comparatives from the second year.","**A defensible figure.** The Commission''s staff estimate the first-year cost of the Basic Module at EUR 3,500 to 4,500 for firms with fewer than 20 employees and EUR 7,500 to 12,800 for firms with 20 to 250 (SWD(2026) 500, printed page 20)."]'::jsonb, false, '[{"title":"Commission Delegated Regulation (EU) 2026/1560 establishing sustainability reporting standards for voluntary use by undertakings protected by the value chain cap","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/db614b12-b555-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Article 2 and Article 4; recitals 3 and 5; Annex I, paragraphs 2, 6 to 8, 14, 18 and 24 to 43 (Basic Module, B1 to B11)","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Section 4.3.2 ''Quantified impacts of the VS'', text and table, PDF page 21 (printed page 20); footnote 37","access":"free"},{"title":"Commission Recommendation (EU) 2025/1710 on a voluntary sustainability reporting standard for small and medium-sized undertakings","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2025,"url":"http://publications.europa.eu/resource/cellar/6e6d1165-7196-11f0-bf4e-01aa75ed71a1.0006.03/DOC_1","locator":"Recitals 8, 11 and 15 to 17; Annex I","access":"free"},{"title":"Voluntary sustainability reporting standard for non-listed SMEs (VSME)","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/sites/default/files/sites/webpublishing/SiteAssets/VSME%20Standard.pdf","locator":"Paragraphs 5, 22 to 44 (Basic Module, B1 to B11), in particular paragraphs 30, 31 and 42(b)","access":"free"},{"title":"Voluntary reporting standard for SMEs (VSME): concluded project page","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/en/projects/voluntary-reporting-standard-for-smes-vsme/concluded","locator":"Opening paragraphs; ''VSME Digital Template and XBRL Taxonomy''","access":"free"},{"title":"Commission adopts revised sustainability reporting standards","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/news/commission-adopts-revised-sustainability-reporting-standards-2026-07-03_en","locator":"News article, paragraphs on the voluntary reporting standard and on scrutiny","access":"free"},{"title":"Environmental reporting guidelines: including Streamlined Energy and Carbon Reporting requirements","publisher":"Department for Energy Security and Net Zero; Department for Environment, Food and Rural Affairs; Department for Business, Energy and Industrial Strategy","year":2019,"url":"https://www.gov.uk/government/publications/environmental-reporting-guidelines-including-mandatory-greenhouse-gas-emissions-reporting-guidance","locator":"Landing page, ''Details''; guidance PDF (152 pages), chapter 2, page 29, and chapter 3 on voluntary reporting","access":"free"},{"title":"2026 post-implementation review of the SECR regulations 2018","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://assets.publishing.service.gov.uk/media/6a0dbf75faac4bc0b0e906af/2026-streamlined-energy-and-carbon-reporting-post-implementation-review.pdf","locator":"''Objective 4: Proportionate reporting burden'', pages 18 to 19, including Figure 3","access":"free"},{"title":"UK government conversion factors for company reporting of greenhouse gas emissions","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting","locator":"Collection page, opening summary; ''Conversion factors 2026''","access":"free"},{"title":"The Greenhouse Gas Protocol: A Corporate Accounting and Reporting Standard (revised edition)","publisher":"Greenhouse Gas Protocol (World Resources Institute and World Business Council for Sustainable Development)","year":2004,"url":"https://ghgprotocol.org/sites/default/files/standards/ghg-protocol-revised.pdf","locator":"Chapter 4, ''Setting operational boundaries'', printed page 25 (PDF page 27); chapter 5 on the base year, printed page 35 (PDF page 37)","access":"free"},{"title":"The Reporting of Injuries, Diseases and Dangerous Occurrences Regulations 2013, regulation 12: Recording and record-keeping","publisher":"legislation.gov.uk","year":2013,"url":"https://www.legislation.gov.uk/uksi/2013/1471/regulation/12","locator":"Regulation 12(1) and (2)","access":"free"},{"title":"The Equality Act 2010 (Gender Pay Gap Information) Regulations 2017, regulation 1: Citation, commencement, interpretation and application","publisher":"legislation.gov.uk","year":2017,"url":"https://www.legislation.gov.uk/uksi/2017/172/regulation/1","locator":"Regulation 1(2), definition of ''relevant employer''; regulation 2(1) for the six figures to be published","access":"free"},{"title":"Making environmental claims on goods and services (the Green Claims Code)","publisher":"Competition and Markets Authority","year":2021,"url":"https://www.gov.uk/government/publications/green-claims-code-making-environmental-claims/environmental-claims-on-goods-and-services","locator":"Section 2, ''Business-to-business claims''; section 3, principles ''Claims must be truthful and accurate'' and ''Claims must be substantiated''","access":"free"},{"title":"SMEs and Net Zero 2025: UK Net Zero Business Census report","publisher":"British Business Bank","year":2025,"url":"https://www.british-business-bank.co.uk/sites/g/files/sovrnj166/files/2025-10/smes-net-zero-report-2025.pdf","locator":"''Tracking and measuring carbon emissions'', page 17; summary table ''SME Net Zero Key Progress Indicators'', page 16","access":"free"},{"title":"Data Requests in Value Chains: The Effects of Corporate Sustainability Reporting on SMEs in The Netherlands","publisher":"Niemann, Morssinkhof, van der Linden and de Vries, Sustainability 17(17), 8029 (MDPI); copy held in the Delft University of Technology repository","year":2025,"url":"https://repository.tudelft.nl/file/File_45575c22-db6d-40bd-b5d7-d43ab0c97965","locator":"Section 3.3, ''Perceived Relevance of ESG Data for SMEs Themselves'' (article page 8, PDF page 9), with Figures 4 and 5","access":"free"},{"title":"Engaging small and medium-sized enterprises (SMEs) in the low carbon agenda","publisher":"Conway, Energy, Sustainability and Society 5, article 32 (Springer)","year":2015,"url":"https://link.springer.com/article/10.1186/s13705-015-0060-x","locator":"Abstract, ''Results''","access":"free"},{"title":"Fostering convergence in SME sustainability reporting (OECD SME and Entrepreneurship Papers)","publisher":"OECD","year":2025,"url":"https://www.oecd.org/content/dam/oecd/en/publications/reports/2025/02/fostering-convergence-in-sme-sustainability-reporting_133eb77f/ffbf16fb-en.pdf","locator":"Table 2.2, printed pages 18 to 19 (PDF pages 19 to 20); executive summary, printed page 6 (PDF page 7); Annex A, Table A A.1","access":"free"}]'::jsonb, '2026-10-02')
