insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.3', '["**What it measures.** Whether, where a lender or major client requires it, the organisation can answer the fuller set: strategy, emissions targets, climate risks, human rights policies and incidents, and value-chain emissions.","**Why it matters.** These answers are judgements and estimates, not meter readings. A target nobody can evidence, or a value-chain estimate with no stated method, misleads the lender or client who relies on it, and through them investors and the public. The emissions of bought-in AI services sit in the value chain and are estimates too.","**The UK position.** The Comprehensive Module, C1 to C9, is the second part of the EU voluntary standard in Delegated Regulation (EU) 2026/1560, which states: \"Applying the Basic Module is a prerequisite for applying the Comprehensive Module.\" Value-chain (Scope 3) emissions are not among the nine; the standard treats them as an optional addition, measured across fifteen categories. Financial Conduct Authority rules for listed companies put Scope 3 on a comply-or-explain basis, recognising that many struggle to obtain the data. Those companies will turn to suppliers.","**What good looks like.** Capability built for named counterparties: targets with base year and target year, climate risks assessed, a human rights policy and complaints route, value-chain estimates with the method stated.","**Reading the answer.** Ask who required it and what was sent. Answers rebuilt for each request are not readiness. The standard does not require assurance, so a claim of assured data needs the assurer named.","**A defensible figure.** For firms with 20 to 250 employees, the Commission''s staff estimate the cost of both modules together at EUR 17,500 to 22,800 in the first year and EUR 8,500 to 11,000 a year after (SWD(2026) 500, printed page 20)."]'::jsonb, false, '[{"title":"Commission Delegated Regulation (EU) 2026/1560 establishing sustainability reporting standards for voluntary use by undertakings protected by the value chain cap","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/db614b12-b555-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Recital 5; Annex I, paragraphs 6(b), 7, 12 and 44 to 64 (Comprehensive Module, C1 to C9, and paragraphs 49 to 52 on Scope 3)","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Section 4.3.1 and section 4.3.2, text and table, PDF page 21 (printed page 20); footnote 37","access":"free"},{"title":"Voluntary sustainability reporting standard for non-listed SMEs (VSME)","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/sites/default/files/sites/webpublishing/SiteAssets/VSME%20Standard.pdf","locator":"Paragraphs 45 to 65 (Comprehensive Module, C1 to C9), in particular paragraphs 49 and 50 to 52","access":"free"},{"title":"UK SRS S2: climate-related disclosures","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/699ddf22532c9ad91ebbcc2b/uk_srs_s2_climate_related_disclosures.pdf","locator":"Paragraph 29(a)(i) (PDF pages 14 to 15); Appendix A, defined terms ''Scope 3 greenhouse gas emissions'' and ''Scope 3 categories'' (PDF page 22)","access":"free"},{"title":"PS26/19: Aligning listed issuers'' sustainability disclosures with international standards (policy statement)","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/publication/policy/ps26-19.pdf","locator":"Paragraph 2.10 (PDF page 9); paragraphs 3.12 and 3.13 (PDF page 28)","access":"free"},{"title":"Companies Act 2006, section 414CB: Contents of non-financial and sustainability information statement","publisher":"legislation.gov.uk","year":2022,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CB","locator":"s.414CB(A1), (2A)(a) to (h) and (4A)","access":"free"},{"title":"2026 post-implementation review of the SECR regulations 2018","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://assets.publishing.service.gov.uk/media/6a0dbf75faac4bc0b0e906af/2026-streamlined-energy-and-carbon-reporting-post-implementation-review.pdf","locator":"''Objective 4: Proportionate reporting burden'', page 19, paragraph under Figure 3","access":"free"},{"title":"PPN 006: Taking account of Carbon Reduction Plans in the procurement of major government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-taking-account-of-carbon-reduction-plans-html","locator":"Paragraph 11; Carbon Reduction Plan template, sections on baseline and current emissions","access":"free"},{"title":"Corporate Value Chain (Scope 3) Accounting and Reporting Standard","publisher":"Greenhouse Gas Protocol (World Resources Institute and World Business Council for Sustainable Development)","year":2011,"url":"https://ghgprotocol.org/sites/default/files/standards/Corporate-Value-Chain-Accounting-Reporing-Standard_041613_2.pdf","locator":"Chapter 5, section 5.4 ''Overview of scope 3 categories'', page 31 (PDF page 33); figure 5.2 and table 5.3","access":"free"},{"title":"Supervisory statement 5/25: Enhancing banks'' and insurers'' approaches to managing climate-related risks","publisher":"Bank of England, Prudential Regulation Authority","year":2025,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2025/ss425-december-2025.pdf","locator":"Paragraph 4.28 (printed pages 17 to 18, PDF pages 19 to 20); paragraphs 4.25 and 4.31","access":"free"},{"title":"Thematic Review: Climate-related Financial Disclosures by AIM and Large Private Companies","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/7931/Climate-related_Financial_Disclosures_by_AIM_and_Large_Private_Companies.pdf","locator":"Section 12, ''Targets and key performance indicators'', page 23; executive summary, page 4","access":"free"},{"title":"Modern Slavery Act 2015, section 54: Transparency in supply chains etc","publisher":"legislation.gov.uk","year":2015,"url":"https://www.legislation.gov.uk/ukpga/2015/30/section/54","locator":"s.54(1), (2), (4) and (5); turnover threshold in S.I. 2015/1833, regulation 2 (£36 million)","access":"free"},{"title":"Guiding Principles on Business and Human Rights: Implementing the United Nations ''Protect, Respect and Remedy'' Framework","publisher":"United Nations Office of the High Commissioner for Human Rights","year":2011,"url":"https://www.ohchr.org/sites/default/files/documents/publications/guidingprinciplesbusinesshr_en.pdf","locator":"Principle 14 and commentary, printed page 15 (PDF page 20); principles 15 and 16 on policy commitment and due diligence","access":"free"},{"title":"Transition Plan Taskforce Disclosure Framework","publisher":"Transition Plan Taskforce (published on the IFRS Foundation''s site)","year":2023,"url":"https://www.ifrs.org/content/dam/ifrs/knowledge-hub/resources/tpt/disclosure-framework-oct-2023.pdf","locator":"Section 3, the five elements, page 21; Figure 3, page 15 (sub-element 3.1, engagement with value chain)","access":"free"},{"title":"Assurance of sustainability reporting: consultation and government response","publisher":"Department for Business and Trade","year":2025,"url":"https://www.gov.uk/government/consultations/assurance-of-sustainability-reporting","locator":"''Detail of outcome'' (added 30 January 2026)","access":"free"},{"title":"Scope 3 Emissions in the UK Reporting Landscape: Call for Evidence Analysis Report","publisher":"Department for Energy Security and Net Zero","year":2024,"url":"https://assets.publishing.service.gov.uk/media/67499f7e75bb645366b3a1e7/summary-of-responses-call-for-evidence-scope-3-emissions-reporting.pdf","locator":"Chapter 2, ''Data challenges'', PDF page 20","access":"free"},{"title":"Harmonizing corporate carbon footprints","publisher":"Klaaßen and Stoll, Nature Communications 12, 6149 (Springer Nature)","year":2021,"url":"https://www.nature.com/articles/s41467-021-26349-x","locator":"Abstract","access":"free"},{"title":"Completing the SME carbon profile: scalable prediction of scope 3 emissions","publisher":"Phillpotts and co-authors, Journal of Industrial Ecology 30, 23-38 (Springer Nature)","year":2026,"url":"https://link.springer.com/article/10.1007/s44498-026-00003-5","locator":"Abstract","access":"free"},{"title":"Senate Bill No. 253, Climate Corporate Data Accountability Act (chaptered 7 October 2023)","publisher":"California Legislative Information","year":2023,"url":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240SB253","locator":"Section 2, adding Health and Safety Code section 38532, subdivisions (b)(2), (b)(5) and (c)(1)","access":"free"}]'::jsonb, '2026-10-02')
