insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.4', '["**What it measures.** Whether the organisation knows the legal limit on what a large customer may demand for its own sustainability report, and uses it.","**Why it matters.** A small supplier facing a large customer rarely feels able to say no. Each request answered beyond the limit becomes the baseline for the next, and data produced under pressure is often guessed. The harm falls on the smaller firm''s staff and on everyone who relies on the customer''s report.","**The UK position.** The right is EU law; no UK equivalent was found. Directive (EU) 2026/470 provides: \"Protected undertakings shall have the right to decline to provide information exceeding the information specified in the voluntary standards\". It applies to requests made for the customer''s reporting under that directive, not for due diligence or other purposes. Contract terms to the contrary are not binding, and a customer asking for more must say which items go further and that the supplier may decline. Annex II to Delegated Regulation (EU) 2026/1560 lists the datapoints inside the limit, for financial years from 1 January 2027. Member states must transpose the directive by 19 March 2027.","**What good looks like.** A written position: requests checked against the list; those beyond it declined with the provision cited and the standard data offered instead; requests and refusals logged.","**Reading the answer.** Ask for one refusal and the basis it stated. Check who was asking: the right applies to companies reporting under the EU directive, not to every customer or bank.","**A defensible figure.** A protected undertaking is one in a reporting company''s value chain that does not exceed an average of 1,000 employees in the preceding financial year (Directive 2013/34/EU, Article 19a(3), as amended)."]'::jsonb, false, '[{"title":"Directive (EU) 2026/470 amending Directives 2006/43/EC, 2013/34/EU, (EU) 2022/2464 and (EU) 2024/1760 (the Omnibus I Directive)","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/2f337274-12b4-11f1-8870-01aa75ed71a1.0006.03/DOC_1","locator":"Article 2(4)(b), inserting new subparagraphs into Article 19a(3) of Directive 2013/34/EU (and Article 2(5) for the matching text in Article 29a(3)); Article 2(8), new Article 29ca; recital 12; Article 5(1); Article 6","access":"free"},{"title":"Commission Delegated Regulation (EU) 2026/1560 establishing sustainability reporting standards for voluntary use by undertakings protected by the value chain cap","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/db614b12-b555-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Article 1, Article 3 and Article 4; recitals 4 to 6; Annex II ''List of disclosures covered by the value chain cap''","access":"free"},{"title":"Commission Delegated Regulation C(2026) 5011 final: explanatory memorandum","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-delegated-act-2026-5011_en.pdf","locator":"Explanatory memorandum, section 1 (PDF pages 2 to 3) and section 3 (PDF pages 5 to 6)","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Passage on the value chain cap, PDF page 6 (printed page 5); section 4.1, PDF pages 19 to 20 (printed pages 18 to 19)","access":"free"},{"title":"Implementing and delegated acts: Corporate Sustainability Reporting Directive","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/regulation-and-supervision/financial-services-legislation/implementing-and-delegated-acts/corporate-sustainability-reporting-directive_en","locator":"Section ''Latest'', entries dated 3 July 2026","access":"free"},{"title":"Commission adopts revised sustainability reporting standards","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/news/commission-adopts-revised-sustainability-reporting-standards-2026-07-03_en","locator":"News article, paragraph on the voluntary reporting standard","access":"free"},{"title":"Commission Recommendation (EU) 2025/1710 on a voluntary sustainability reporting standard for small and medium-sized undertakings","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2025,"url":"http://publications.europa.eu/resource/cellar/6e6d1165-7196-11f0-bf4e-01aa75ed71a1.0006.03/DOC_1","locator":"Recitals 14 and 17; points 4 to 6 of the Recommendation","access":"free"},{"title":"PPN 006: Taking account of Carbon Reduction Plans in the procurement of major government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-taking-account-of-carbon-reduction-plans-html","locator":"Paragraphs 3 and 13","access":"free"},{"title":"Feedback on sustainability reporting standards: additional explanatory information regarding the value chain cap","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/news/feedback-sustainability-reporting-standards-additional-explanatory-information-regarding-value-chain-2026-05-06_en","locator":"Part B, questions 3 to 6","access":"free"},{"title":"Commission Delegated Regulation (EU) 2026/1563 amending Delegated Regulation (EU) 2023/2772 as regards the simplification of certain sustainability reporting standards","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/7c16cdc5-b556-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Annex, ESRS 1 General Requirements, chapter 5, paragraph 66; paragraph 65 on estimates; Article 3 (entry into force and application)","access":"free"},{"title":"Directive (EU) 2022/2464 as regards corporate sustainability reporting (the Corporate Sustainability Reporting Directive), as originally published","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2022,"url":"http://publications.europa.eu/resource/cellar/59e70288-7ce5-11ed-9887-01aa75ed71a1.0006.02/DOC_1","locator":"Article 1(8), inserting Article 29b into Directive 2013/34/EU, paragraph 4","access":"free"},{"title":"Procurement Act 2023, section 12: Covered procurement: objectives","publisher":"legislation.gov.uk","year":2023,"url":"https://www.legislation.gov.uk/ukpga/2023/54/section/12","locator":"s.12(4); see also s.22(1) and (5) on proportionate conditions of participation","access":"free"},{"title":"UK SRS S1: General Requirements for Disclosure of Sustainability-related Financial Information","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/699dd3b007d7bff3604d6c5e/uk_srs_1_general_requirements_for_disclosure_of_sustainability_related_financial_information.pdf","locator":"Appendix B, paragraphs B6 and B8 to B10 (printed pages 23 to 24, PDF pages 27 to 28)","access":"free"},{"title":"Scope 3 Emissions in the UK Reporting Landscape: Call for Evidence Analysis Report","publisher":"Department for Energy Security and Net Zero","year":2024,"url":"https://assets.publishing.service.gov.uk/media/67499f7e75bb645366b3a1e7/summary-of-responses-call-for-evidence-scope-3-emissions-reporting.pdf","locator":"Chapter 1, ''Compliance with IFRS'', PDF page 14; chapter 2, ''Data challenges'', item 6, PDF page 20","access":"free"},{"title":"Data Requests in Value Chains: The Effects of Corporate Sustainability Reporting on SMEs in The Netherlands","publisher":"Niemann, Morssinkhof, van der Linden and de Vries, Sustainability 17(17), 8029 (MDPI); copy held in the Delft University of Technology repository","year":2025,"url":"https://repository.tudelft.nl/file/File_45575c22-db6d-40bd-b5d7-d43ab0c97965","locator":"Section 1, Introduction (article page 2, PDF page 3); end of section 3.2 (article page 8, PDF page 9)","access":"free"},{"title":"Supply-chain data sharing for scope 3 emissions","publisher":"Stenzel and Waichman, npj Climate Action 2, article 7 (Springer Nature)","year":2023,"url":"https://www.nature.com/articles/s44168-023-00032-x","locator":"Section ''Obstacles to primary data sharing'', paragraphs on data privacy concerns","access":"free"}]'::jsonb, '2026-10-02')
