insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.5', '["**What it measures.** Whether the organisation knows how much energy, water and carbon its use of AI accounts for, and whether that shapes the models and suppliers it chooses.","**Why it matters.** The cost of a query is not paid by the person who types it. It falls on communities whose power and drinking water a data centre draws on, and on everyone through emissions. Calling AI use responsible without counting is a claim with nothing behind it.","**The UK position.** No UK law requires a business to report the footprint of the AI it buys. Energy and carbon reporting for large companies covers their own energy use; emissions from purchased services, where cloud and AI sit, are voluntary. Of commercial models, the International Energy Agency says: \"This lack of data makes it hard to estimate energy consumption for the field of AI as a whole and for users and companies to make informed choices when it comes to energy efficiency.\" The EU''s AI Act makes providers of general-purpose models document energy consumption, but for regulators on request, not for customers.","**What good looks like.** A short written estimate for the systems that matter, with method and limits stated; suppliers asked for their data; the trend watched; a smaller, task-specific model chosen where it does the job.","**Reading the answer.** Ask how the number was reached. An estimate with a stated method is a sound answer. A footprint dismissed as negligible with no working is not.","**A defensible figure.** Data centres used about 415 terawatt-hours of electricity in 2024, around 1.5% of world consumption, projected to reach about 945 by 2030 (Energy and AI, p.14). That is all data centre use, not AI alone."]'::jsonb, false, '[{"title":"Energy and AI (World Energy Outlook Special Report)","publisher":"International Energy Agency","year":2025,"url":"https://iea.blob.core.windows.net/assets/de9dea13-b07d-42c5-a398-d1b3ae17d866/EnergyandAI.pdf","locator":"Executive summary, p.14 (figures); Chapter 1, p.44, paragraph beginning ''Similar caveats hold'' (quotation); p.46 on energy per task","access":"free"},{"title":"Engineering Responsible AI: foundations for environmentally sustainable AI","publisher":"National Engineering Policy Centre (Royal Academy of Engineering, with the Institution of Engineering and Technology and BCS)","year":2025,"url":"https://nepc.raeng.org.uk/media/2aggau2j/foundations-for-sustainable-ai-nepc-report.pdf","locator":"PDF page 7, section on better data; foundational step 1 ''Expanding environmental reporting mandates'', PDF page 8","access":"free"},{"title":"AI Energy Council","publisher":"Department for Science, Innovation and Technology; Department for Energy Security and Net Zero","year":2025,"url":"https://www.gov.uk/government/groups/ai-energy-council","locator":"Section ''Role of the group'' and list ''Key areas being discussed by the AI Energy Council''","access":"free"},{"title":"UK Compute Roadmap","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/uk-compute-roadmap/uk-compute-roadmap","locator":"Section on AI Growth Zones, paragraph beginning ''Noting that AI infrastructure is enormously energy intensive''; section on the AI Research Resource, ''Security and sustainability by design''","access":"free"},{"title":"Regulation (EU) 2024/1689 (Artificial Intelligence Act), Annex XI: technical documentation for providers of general-purpose AI models","publisher":"European Commission, AI Act Service Desk (Commission''s copy of the Official Journal text)","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/annex-11","locator":"Annex XI, Section 1, point 2(d) and (e) and the sentence that follows; read with Article 53(1)(a) and (5), Article 40(2) and Article 112(6) on the same site","access":"free"},{"title":"Corporate Value Chain (Scope 3) Accounting and Reporting Standard","publisher":"Greenhouse Gas Protocol (World Resources Institute and World Business Council for Sustainable Development)","year":2011,"url":"https://ghgprotocol.org/sites/default/files/standards/Corporate-Value-Chain-Accounting-Reporing-Standard_041613_2.pdf","locator":"Section 5.5, ''Category 1: Purchased goods and services'', PDF page 40","access":"free"},{"title":"Environmental Reporting Guidelines: including Streamlined Energy and Carbon Reporting guidance","publisher":"HM Government (Department for Business, Energy and Industrial Strategy; Department for Environment, Food and Rural Affairs)","year":2019,"url":"https://assets.publishing.service.gov.uk/media/67161e8696def6d27a4c9ab3/environmental-reporting-guidance-secr-march-2019.pdf","locator":"Chapter 2, section ''Should quoted companies report all their emissions?'', printed page 39 (PDF page 39)","access":"free"},{"title":"Power Hungry Processing: Watts Driving the Cost of AI Deployment?","publisher":"Luccioni, Jernite and Strubell (ACM FAccT 2024); arXiv","year":2024,"url":"https://arxiv.org/abs/2311.16863","locator":"Abstract; section 4.1 of the paper (PDF page 6) for energy per 1,000 inferences by task","access":"free"},{"title":"Energy and Policy Considerations for Deep Learning in NLP","publisher":"Strubell, Ganesh and McCallum; Association for Computational Linguistics","year":2019,"url":"https://aclanthology.org/P19-1355.pdf","locator":"Section 5 ''Conclusions'', first recommendation, p.3648","access":"free"},{"title":"Software Carbon Intensity (SCI) Specification, version 1.1.0","publisher":"Green Software Foundation","year":2024,"url":"https://sci.greensoftware.foundation/","locator":"Introduction, final two paragraphs; section ''Methodology summary'' (SCI = (O + M) per R)","access":"free"},{"title":"ICT Sector Guidance built on the GHG Protocol Product Life Cycle Accounting and Reporting Standard, Chapter 4: Cloud and data center services","publisher":"Greenhouse Gas Protocol","year":2017,"url":"https://ghgprotocol.org/sites/default/files/GHGP-ICTSG%20-%20ALL%20Chapters.pdf","locator":"Chapter 4, ''Executive Summary: Cloud and data center services'', printed page 4-4 (PDF page 120); section 4.6 on allocation","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service (Department for Science, Innovation and Technology)","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 2 ''You use AI lawfully, ethically and responsibly''; section ''Using AI safely and responsibly'', sustainability bullet and practical recommendations","access":"free"},{"title":"Water use in AI and Data Centres","publisher":"Government Digital Sustainability Alliance (published by the Department for Environment, Food and Rural Affairs)","year":2025,"url":"https://assets.publishing.service.gov.uk/media/688cb407dc6688ed50878367/Water_use_in_data_centre_and_AI_report.pdf","locator":"Section 1, introduction (PDF page 2); section on UK regulation and the transparency gap; strategic recommendations","access":"free"},{"title":"Directive (EU) 2023/1791 on energy efficiency (recast), Article 12: Data centres","publisher":"European Union (Publications Office copy of the Official Journal text)","year":2023,"url":"http://publications.europa.eu/resource/cellar/0e432499-5752-11ee-9220-01aa75ed71a1.0006.03/DOC_1","locator":"Article 12(1) to (4); Annex VII lists the information","access":"free"},{"title":"The Large and Medium-sized Companies and Groups (Accounts and Reports) Regulations 2008, Schedule 7, Part 7A: energy and carbon report (unquoted companies)","publisher":"legislation.gov.uk","year":2008,"url":"https://www.legislation.gov.uk/uksi/2008/410/schedule/7/part/7A","locator":"Sch. 7 Part 7A, paragraph 20D(1) to (3) and (7)","access":"free"},{"title":"Making AI Less \"Thirsty\": Uncovering and Addressing the Secret Water Footprint of AI Models","publisher":"Li, Yang, Islam and Ren; arXiv (accepted by Communications of the ACM)","year":2023,"url":"https://arxiv.org/abs/2304.03271","locator":"Abstract (version 5, revised 26 March 2025)","access":"free"},{"title":"Measuring the environmental impact of delivering AI at Google Scale","publisher":"Elsworth and others (Google); arXiv","year":2025,"url":"https://arxiv.org/abs/2508.15734","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
