insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.6', '["**What it measures.** Whether sustainability figures are gathered once, from a known source, with an owner and a written method, and then reused for every customer, lender and report.","**Why it matters.** Figures rebuilt for each request drift apart. Customers, lenders and the public then rely on numbers nobody can trace. The risk grows when an AI tool fills the gaps, because it will produce a plausible number whether or not one exists.","**The UK position.** No law tells a small company how to keep sustainability data. Rules for large companies show what is expected: directors'' reports must state the methodologies used to calculate energy and emissions figures, and government guidance says to use verifiable data and show how estimates were made. The UK Sustainability Reporting Standards, published in February 2026, treat information as verifiable when the inputs behind it can be corroborated. In a 2023 review of climate metrics, the Financial Reporting Council said: \"We also encourage companies to be transparent about data limitations, including explanations of estimations and areas where it is not feasible to collect data.\"","**What good looks like.** One dataset; an owner for each line; sources and conversion factors recorded; a refresh date; estimates marked as estimates; a second person checking figures before release.","**Reading the answer.** Ask for last year''s electricity figure and where it came from. If two documents give two numbers, the data is being rebuilt each time. Independent assurance sits at the top of the scale; even among the largest companies it is usually limited.","**A defensible figure.** 83% of assurance engagements for FTSE 350 companies in 2023 involved limited assurance over some or all of the metrics assured (Financial Reporting Council market study, February 2025, paragraph 18)."]'::jsonb, false, '[{"title":"The Large and Medium-sized Companies and Groups (Accounts and Reports) Regulations 2008, Schedule 7, Part 7A: energy and carbon report (unquoted companies)","publisher":"legislation.gov.uk","year":2008,"url":"https://www.legislation.gov.uk/uksi/2008/410/schedule/7/part/7A","locator":"Sch. 7 Part 7A, paragraphs 20D, 20F and 20H","access":"free"},{"title":"Environmental Reporting Guidelines: including Streamlined Energy and Carbon Reporting guidance","publisher":"HM Government (Department for Business, Energy and Industrial Strategy; Department for Environment, Food and Rural Affairs)","year":2019,"url":"https://assets.publishing.service.gov.uk/media/67161e8696def6d27a4c9ab3/environmental-reporting-guidance-secr-march-2019.pdf","locator":"Chapter 2, section ''Collecting your energy use data'', PDF page 46; Chapter 1 principles (consistent, transparent), PDF page 9","access":"free"},{"title":"UK SRS S1: General Requirements for Disclosure of Sustainability-related Financial Information","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/699dd3b007d7bff3604d6c5e/uk_srs_1_general_requirements_for_disclosure_of_sustainability_related_financial_information.pdf","locator":"Appendix D, paragraphs D21 to D23 (verifiability), PDF page 42; paragraph 23 (consistent data and assumptions), PDF page 10","access":"free"},{"title":"CRR Thematic review of climate-related metrics and targets","publisher":"Financial Reporting Council","year":2023,"url":"https://www.frc.org.uk/documents/3561/Thematic_review_of_climate-related_metrics_and_targets_2023.pdf","locator":"Section 2, cross-sector findings on data, PDF page 20","access":"free"},{"title":"Assurance of Sustainability Reporting Market Study: Final Report","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/7963/Assurance_of_Sustainability_Reporting_Market_Study_Final_Report.pdf","locator":"Paragraph 18 and Figure 10, PDF page 15 (also the summary, PDF page 9); paragraphs 24 to 28 on quality","access":"free"},{"title":"The Greenhouse Gas Protocol: A Corporate Accounting and Reporting Standard (revised edition)","publisher":"Greenhouse Gas Protocol (World Resources Institute and World Business Council for Sustainable Development)","year":2004,"url":"https://ghgprotocol.org/sites/default/files/standards/ghg-protocol-revised.pdf","locator":"Chapter 7 ''Managing Inventory Quality'', PDF pages 50 to 53, including Table 4","access":"free"},{"title":"Greenhouse gas reporting: conversion factors 2026","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://www.gov.uk/government/publications/greenhouse-gas-reporting-conversion-factors-2026","locator":"Section ''Details'', including the note ''Update: July 2026''","access":"free"},{"title":"PPN 006: Technical standard for completion of Carbon Reduction Plans","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-technical-standard-for-completion-of-carbon-reduction-plans-html","locator":"Paragraphs 11 to 13 (annual review and publication) and 21 to 22 (conversion factors and boundary)","access":"free"},{"title":"Voluntary sustainability reporting standard for non-listed SMEs (VSME)","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/sites/default/files/sites/webpublishing/SiteAssets/VSME%20Standard.pdf","locator":"Paragraph 9 (qualities of information), PDF page 6; paragraph 18 (avoiding duplication); list of disclosures B1 to B11 and C1 to C9","access":"free"},{"title":"FRC Lab report: Improving ESG data production","publisher":"Financial Reporting Council (Financial Reporting Lab)","year":2022,"url":"https://www.frc.org.uk/documents/4919/FRC_Lab_Report_Improving_ESG_Data_Production.pdf","locator":"Section 2 ''Method'', ''Sources, tools and systems for data collection'', PDF page 18; ''Validating the data'' on owners, methodology statements and audit trail","access":"free"},{"title":"International Standard on Sustainability Assurance (UK) 5000: General Requirements for Sustainability Assurance Engagements","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/8887/ISSA_UK_5000.pdf","locator":"Paragraph 9 (limited and reasonable assurance), PDF page 8; paragraphs 117 and 118 (the entity''s information system); paragraph 15 (effective date)","access":"free"},{"title":"Corporate Value Chain (Scope 3) Accounting and Reporting Standard","publisher":"Greenhouse Gas Protocol (World Resources Institute and World Business Council for Sustainable Development)","year":2011,"url":"https://ghgprotocol.org/sites/default/files/standards/Corporate-Value-Chain-Accounting-Reporing-Standard_041613_2.pdf","locator":"Chapter 7 ''Collecting Data'', paragraph beginning ''To facilitate quality assurance'', printed page 75 (PDF page 77); Appendix C ''Data Management Plan'', printed page 129","access":"free"},{"title":"Small Business Finance Markets 2025/26","publisher":"British Business Bank","year":2026,"url":"https://www.british-business-bank.co.uk/sites/g/files/sovrnj166/files/2026-03/report-small-business-finance-markets-2026.pdf","locator":"Chapter 2.5 ''Finance for environmental sustainability'', section ''The proportion of smaller businesses measuring their carbon emissions remains low'', PDF page 98","access":"free"},{"title":"Harmonizing corporate carbon footprints","publisher":"Klaaßen and Stoll; Nature Communications 12, 6149","year":2021,"url":"https://www.nature.com/articles/s41467-021-26349-x","locator":"Abstract; Results, case study of the technology sector","access":"free"},{"title":"Corporate carbon performance data: Quo vadis?","publisher":"Busch, Johnson and Pioch; Journal of Industrial Ecology 26(1), 350-363","year":2020,"url":"https://link.springer.com/article/10.1111/jiec.13008","locator":"Abstract","access":"free"},{"title":"GHG Inventory Development Process and Guidance","publisher":"United States Environmental Protection Agency, Center for Corporate Climate Leadership","year":2025,"url":"https://www.epa.gov/climateleadership/ghg-inventory-development-process-and-guidance","locator":"Section ''The GHG Inventory Development Process'', step 3 ''Develop a GHG Inventory Management Plan''","access":"free"}]'::jsonb, '2026-10-02')
