insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.7', '["**What it measures.** Whether one senior person is answerable for sustainability, and whether the board sees performance figures on a set timetable.","**Why it matters.** When nobody owns it, the costs a business puts on its community and the environment, including the energy its AI uses, are nobody''s job to weigh. Promises made to customers and lenders have no one answerable for keeping them.","**The UK position.** Every director must have regard to the impact of the company''s operations on the community and the environment (Companies Act 2006, section 172); the courts leave the weighing to directors acting in good faith. Companies with more than 500 employees that are traded, banks, insurers, on AIM or have turnover above £500 million must describe their governance of climate-related risks. Smaller companies have no such duty, but a supplier bidding for a major government contract needs its Carbon Reduction Plan approved by the board and signed by a director. Reviewing first-year climate disclosures, the Financial Reporting Council found \"the extent of the integration of the climate governance process with the company’s overall governance process was often unclear\".","**What good looks like.** A named director or equivalent; sustainability in their objectives; a board paper with metrics at set intervals; authority to refuse a target the business cannot evidence.","**Reading the answer.** Ask who, and when the board last saw the figures. A name without a date is a title, not ownership. In a small firm the owner may also run finance or operations; that is fine.","**A defensible figure.** Of 20 companies whose climate disclosures the Financial Reporting Council reviewed, only half presented all the required information on targets and progress against them (January 2025 review, sections 1 and 3)."]'::jsonb, false, '[{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a) to (f), in particular (d)","access":"free"},{"title":"Companies Act 2006, section 414CB: Contents of non-financial and sustainability information statement","publisher":"legislation.gov.uk","year":2022,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CB","locator":"s.414CB(A1) and (2A)(a) to (h); notes F4 and F7","access":"free"},{"title":"Companies Act 2006, section 414CA: Non-financial and sustainability information statement","publisher":"legislation.gov.uk","year":2022,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CA","locator":"s.414CA(1), (1A), (2A)(a) and (4)","access":"free"},{"title":"UK SRS S2: Climate-related Disclosures","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/699ddf22532c9ad91ebbcc2b/uk_srs_s2_climate_related_disclosures.pdf","locator":"Paragraphs 5 and 6 (governance), PDF page 7; paragraph 29(g) (remuneration), PDF page 16","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 1, Principle A and Provision 1, p.6; Section 5, Principle P, p.15","access":"free"},{"title":"Recommendations of the Task Force on Climate-related Financial Disclosures: Final Report","publisher":"Task Force on Climate-related Financial Disclosures","year":2017,"url":"https://assets.bbhub.io/company/sites/60/2021/10/FINAL-2017-TCFD-Report.pdf","locator":"Section C, ''Governance'', recommended disclosures a) and b) with guidance for all sectors, PDF page 27","access":"free"},{"title":"Thematic Review: Climate-related Financial Disclosures by AIM and Large Private Companies","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/7931/Climate-related_Financial_Disclosures_by_AIM_and_Large_Private_Companies.pdf","locator":"Section 1 ''Executive summary'', key findings (PDF page 4); section 3 ''Scope and selection'' (PDF page 7); section 7 ''Governance arrangements'' (PDF page 13)","access":"free"},{"title":"PPN 006: Technical standard for completion of Carbon Reduction Plans","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-technical-standard-for-completion-of-carbon-reduction-plans-html","locator":"Paragraphs 24 and 25 (approval and sign-off)","access":"free"},{"title":"Voluntary sustainability reporting standard for non-listed SMEs (VSME)","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/sites/default/files/sites/webpublishing/SiteAssets/VSME%20Standard.pdf","locator":"Comprehensive Module, disclosure C2, paragraphs 48 and 49, PDF page 12; template at paragraph 213 (source of the quoted words)","access":"free"},{"title":"ClientEarth v Shell plc and others [2023] EWHC 1897 (Ch)","publisher":"High Court of Justice, Chancery Division (The National Archives, Find Case Law)","year":2023,"url":"https://caselaw.nationalarchives.gov.uk/ewhc/ch/2023/1897","locator":"Paragraphs 20 and 28 to 30 (directors'' duties); paragraph 99 (outcome)","access":"free"},{"title":"Companies Act 2006, section 414CZA: Section 172(1) statement","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CZA","locator":"s.414CZA(1) and (2); textual amendment note on S.I. 2018/860","access":"free"},{"title":"The Wates Corporate Governance Principles for Large Private Companies","publisher":"Financial Reporting Council (Wates Coalition Group)","year":2018,"url":"https://www.frc.org.uk/documents/634/The_Wates_Corporate_Governance_Principles_for_Large_Private_Companies.pdf","locator":"Principle Six ''Stakeholder relationships and engagement'', guidance on external impacts, printed page 21 (PDF page 24); Principle Three ''Director responsibilities'', printed page 15; Principle Five ''Remuneration'', printed page 19","access":"free"},{"title":"Supervisory Statement SS5/25: Enhancing banks'' and insurers'' approaches to managing climate-related risks","publisher":"Bank of England, Prudential Regulation Authority","year":2025,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2025/ss425-december-2025.pdf","locator":"Chapter 1 ''Governance'', paragraphs 4.2 and 4.6, printed pages 12 and 13 (PDF pages 14 and 15); paragraphs 4.40 and 4.41 on reporting and management information to the board","access":"free"},{"title":"G20/OECD Principles of Corporate Governance 2023","publisher":"Organisation for Economic Co-operation and Development","year":2023,"url":"https://www.oecd.org/content/dam/oecd/en/publications/reports/2023/09/g20-oecd-principles-of-corporate-governance-2023_60836fcb/ed750b30-en.pdf","locator":"Chapter VI ''Sustainability and resilience'', Principle VI.C, printed page 47 (PDF page 49)","access":"free"},{"title":"Do chief sustainability officers and CSR committees influence CSR-related outcomes? A structured literature review based on empirical-quantitative research findings","publisher":"Velte and Stawinoga; Journal of Management Control 31, 333-377","year":2020,"url":"https://link.springer.com/article/10.1007/s00187-020-00308-x","locator":"Abstract","access":"free"},{"title":"Executive Compensation Tied to ESG Performance: International Evidence (ECGI Finance Working Paper 825/2022)","publisher":"Cohen, Kadach, Ormazabal and Reichelstein; European Corporate Governance Institute","year":2022,"url":"https://www.ecgi.global/publications/working-papers/executive-compensation-tied-to-esg-performance-international-evidence","locator":"Abstract (working paper page; last revised 25 March 2023)","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.8', '["**What it measures.** Whether the organisation uses its sustainability evidence on purpose, in bids and in finance conversations, and records whether it made a difference.","**Why it matters.** Used honestly, good evidence earns work. Used loosely, it misleads the buyer or lender and takes work from an honest rival. AI-drafted bids sharpen the risk: they assert credentials fluently whether or not anyone has checked.","**The UK position.** For major central government contracts, a bidder must supply a Carbon Reduction Plan as a condition of participation, and a tender that fails a condition must be disregarded. The plan is pass or fail: guidance says plans should not be scored or compared. Separately, central government must give social value a minimum weighting; environmental benefit is one outcome a buyer may choose. On finance the evidence is thin. Reviewing sustainability-linked loans, the Financial Conduct Authority wrote: \"Small savings on margins may be outweighed by costs and negotiation time with lenders or legal advisors.\" It found the market slow to develop for smaller firms. The Competition and Markets Authority expects businesses to hold robust evidence for environmental claims.","**What good looks like.** A maintained set of bid answers drawn from one dataset; the same figures given to customers and lenders; a note after each tender and loan of whether sustainability counted.","**Reading the answer.** Ask for one contract or loan where it mattered, and how they know. In public tenders, readiness is more often an entry ticket than a scoring advantage.","**A defensible figure.** Margin step-ups for missed sustainability targets were around 2.5 basis points, capped at about 5, among investment-grade borrowers (Financial Conduct Authority letter, 29 June 2023). A basis point is one hundredth of one per cent."]'::jsonb, false, '[{"title":"Procurement Act 2023, section 19: Award of public contracts following a competitive tendering procedure","publisher":"legislation.gov.uk","year":2023,"url":"https://www.legislation.gov.uk/ukpga/2023/54/section/19","locator":"s.19(1), (2) and (3)(a)","access":"free"},{"title":"Procurement Act 2023, section 12: Covered procurement: objectives","publisher":"legislation.gov.uk","year":2023,"url":"https://www.legislation.gov.uk/ukpga/2023/54/section/12","locator":"s.12(1)(a) to (d) and (4); commencement note I2","access":"free"},{"title":"PPN 006: Taking account of Carbon Reduction Plans in the procurement of major government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-taking-account-of-carbon-reduction-plans-html","locator":"Paragraphs 2 to 4 (scope), 9 (timing) and 10 to 13 (the requirement)","access":"free"},{"title":"PPN 006: Frequently asked questions","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-frequently-asked-questions","locator":"Questions on how plans are assessed and on emissions data","access":"free"},{"title":"PPN 002: Taking account of social value in the award of central government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-002-taking-account-of-social-value-in-the-award-of-contracts/ppn-002-taking-account-of-social-value-in-the-award-of-central-government-contracts-html","locator":"Paragraphs 7 to 11","access":"free"},{"title":"National Procurement Policy Statement","publisher":"Cabinet Office","year":2025,"url":"https://assets.publishing.service.gov.uk/media/67ab332fd41dfb0b59cec46a/E03274856_National_Procurement_Policy_Statement_Accessible.pdf","locator":"Section on the government''s missions, ''Make Britain a clean energy superpower'', PDF page 4; later section on small and medium-sized enterprises","access":"free"},{"title":"Review of the Sustainability-Linked Loans (SLL) Market: letter to Heads of ESG/Sustainable Finance","publisher":"Financial Conduct Authority","year":2023,"url":"https://www.fca.org.uk/publication/correspondence/sll-letter-june-2023.pdf","locator":"Summary findings, p.2; ''Conflicts of interest and weak incentives to issue SLLs'', p.3","access":"free"},{"title":"The Issuance and Design of Sustainability-linked Loans (Working Paper 23-027)","publisher":"Loumioti and Serafeim; Harvard Business School","year":2022,"url":"https://www.hbs.edu/ris/Publication%20Files/23-027_4b09d278-4051-468e-a5d9-eb0e7c50c25d.pdf","locator":"Abstract, PDF page 3","access":"free"},{"title":"The greening of lending: mortgage pricing of energy transition risk (Staff Working Paper No. 1,016)","publisher":"Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/working-paper/2023/the-greening-of-lending-mortgage-pricing-of-energy-transition-risk.pdf","locator":"Abstract, PDF page 2","access":"free"},{"title":"Making environmental claims on goods and services (Green Claims Code guidance)","publisher":"Competition and Markets Authority","year":2021,"url":"https://www.gov.uk/government/publications/green-claims-code-making-environmental-claims/environmental-claims-on-goods-and-services","locator":"Sections ''Claims must be truthful and accurate'', ''Claims must be substantiated'' and ''Business-to-business claims''","access":"free"},{"title":"Procurement Act 2023, section 23: Award criteria","publisher":"legislation.gov.uk","year":2023,"url":"https://www.legislation.gov.uk/ukpga/2023/54/section/23","locator":"s.23(2)(a) to (d), (3) and (5)","access":"free"},{"title":"Public Services (Social Value) Act 2012, section 1: Contracts of relevant authorities","publisher":"legislation.gov.uk","year":2012,"url":"https://www.legislation.gov.uk/ukpga/2012/3/section/1","locator":"s.1(3)(a) and (b)","access":"free"},{"title":"PPN 016: Carbon reduction contract schedule","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-016-carbon-reduction-contract-schedule/ppn-016-carbon-reduction-contract-schedule-html","locator":"Paragraphs 1 to 6 (issue, scope and timing); the accompanying guidance note describes contract-specific emissions reporting and reduction targets","access":"free"},{"title":"The Business Protection from Misleading Marketing Regulations 2008, regulation 3: Prohibition of advertising which misleads traders","publisher":"legislation.gov.uk","year":2008,"url":"https://www.legislation.gov.uk/uksi/2008/1276/regulation/3","locator":"Regulation 3(1), (2) and (5)(e)","access":"free"},{"title":"Directive 2014/24/EU on public procurement, Article 67: Contract award criteria","publisher":"European Union (Publications Office copy of the Official Journal text)","year":2014,"url":"http://publications.europa.eu/resource/cellar/aa61f069-b654-11e3-86f9-01aa75ed71a1.0006.03/DOC_1","locator":"Article 67(1) and (2)","access":"free"},{"title":"Competing for government procurement contracts: The role of corporate social responsibility","publisher":"Flammer; Strategic Management Journal 39(5), 1299-1324 (author''s copy, Columbia University)","year":2018,"url":"https://www.columbia.edu/~cf2870/PDFs/Flammer_SMJ2018_inclAppendix.pdf","locator":"Research summary and managerial summary, PDF page 1; discussion, PDF page 19","access":"free"},{"title":"The pricing of carbon risk in syndicated loans: which risks are priced and why? (BIS Working Paper 946)","publisher":"Ehlers, Packer and de Greiff; Bank for International Settlements","year":2021,"url":"https://www.bis.org/publ/work946.htm","locator":"Abstract","access":"free"},{"title":"Small Business Finance Markets 2025/26","publisher":"British Business Bank","year":2026,"url":"https://www.british-business-bank.co.uk/sites/g/files/sovrnj166/files/2026-03/report-small-business-finance-markets-2026.pdf","locator":"Chapter 2.5 ''Finance for environmental sustainability'', section on barriers, PDF page 95; Figure B.32","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();

-- Glossary ----------------------------------------------------------------
insert into glossary_terms (term, def) values ('8×8 framework', 'Principled Futures'' assessment structure: eight governance domains, each with eight criteria, scored 0–4 against defined maturity bands. Sixty-four questions that together describe how well an organisation governs its AI and ESG position.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Accountability file', 'One maintained folder per AI system holding its classification, impact assessments, approvals, testing records, incidents and reviews. The test is whether it can be produced in an afternoon, from known locations, by someone other than its author.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Accountability rings', 'The three circles of people around the telemetry measures: those who run AI daily, those who set the rules, and the outside eyes who check both. Every measure belongs to one named person in one ring.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Adversarial input', 'An input deliberately crafted to look normal to humans while making an AI system misbehave — flipping a classification or slipping a filter. One of the attack types unique to AI that conventional security testing does not cover.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('AI Act (EU)', 'The European Union''s AI regulation, phasing in from 2025 to 2028: prohibited practices, transparency duties from August 2026, and full high-risk obligations from late 2027. It reaches UK organisations whose systems or outputs touch people in the EU.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('AI literacy duty', 'Article 4 of the EU AI Act: organisations must support a sufficient level of AI literacy in staff and anyone using AI on their behalf, applicable since February 2025 with enforcement from August 2026. An effort obligation — but one that fails where no effort can be evidenced.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('AI register', 'A single maintained record of every AI system in use — including AI embedded in procured software — with each system''s purpose, data, risk tier and named owner. The starting point of governance: you cannot govern what you have not listed.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('AI-washing', 'Overstating what your AI does, how autonomous it is, or how well it is governed — in marketing, bids or investor material. Now a named enforcement concern, and the easiest audit anyone will ever run against your own records.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Article 22B / 22C (UK GDPR)', 'The UK''s rebuilt automated-decision rules, in force since February 2026. Article 22B keeps a hard default prohibition on significant automated decisions using special-category data; Article 22C sets the four safeguards for every other significant automated decision.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Article 26 (EU AI Act)', 'The deployer-obligations article: use high-risk AI per the provider''s instructions, assign competent human oversight, keep input data relevant, monitor operation, retain logs for at least six months, and inform workers and affected people. Where most SMEs'' AI Act duties actually live.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Article 50 (EU AI Act)', 'The transparency article, live from 2 August 2026: people must be told when they are interacting with AI, and generative systems must mark synthetic content machine-readably. The first AI Act duty most organisations will meet in practice.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Assessment notice', 'The ICO''s power to compel an organisation to submit to an audit or produce reports on its data processing. The reason the accountability file needs to exist before the letter arrives, not after.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('ATRS', 'The Algorithmic Transparency Recording Standard: the UK government''s template for documenting how public-sector algorithms work, mandatory for central departments. A ready-made model for what "documented enough" looks like in the private sector too.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Augmentation-first', 'The adoption strategy in which AI''s purpose is extending what your existing workforce can do, rather than replacing it. Measured in throughput and quality rather than headcount reduction — the strategy with the better failure profile and the better story.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Automation bias', 'The documented human tendency to defer to machine output, strongest exactly when the machine is usually right. The reason oversight has to be designed and measured, not just staffed.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Balancing test', 'The documented weighing exercise required when relying on legitimate interests as a lawful basis: your interest, the necessity of the processing, and the impact on the individuals concerned. A recital is not a test; the test is the writing-down.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Basic Module (VSME)', 'Disclosures B1 to B11 of the voluntary SME sustainability standard: company profile, energy, emissions, workforce, safety, pay and conduct. The standardised data set that answers most customer and bank questionnaires — assembled once, reused everywhere.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Bias carve-out', 'The explicit lawful route, established by the Omnibus package, for processing personal data to detect and correct bias in AI systems. Permission for a purpose — use it deliberately, record the basis, and confine it to fairness work.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Breach (telemetry)', 'A metric that has crossed its threshold — the red state in the register, escalating to the people who own the response. Distinct from a data breach, which is a security incident involving personal data.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Comprehensive Module (VSME)', 'Disclosures C1 to C9 of the voluntary SME standard: strategy, targets, climate risks, human rights and Scope 3 emissions. The fuller data set worth building for the lenders and flagship clients whose business justifies it.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Concentration risk', 'Multiple critical processes resting on one vendor, one model family or one integration point — individually sensible choices compounding into a single point of failure. Named, priced and exit-planned in mature estates.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Containment', 'The designed, rehearsed capability to stop an AI system quickly: defined triggers, authorised people, dual authorisation for drastic action, a tested mechanism and a rollback plan. For systems that act autonomously, the licence for everything else.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Contestability', 'A person''s practical ability to challenge an automated decision and obtain a fresh look with a possible different outcome. One of the DUAA''s four safeguards — and a process that never changes an outcome is not one.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('CSRD', 'The EU''s Corporate Sustainability Reporting Directive. Since the Omnibus reforms its mandatory scope starts at 1,000 employees and €450 million turnover — but in-scope companies must report on their value chains, which is how its questions reach smaller suppliers.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Data minimisation', 'The principle that you process no more personal data than the purpose needs. AI''s appetite for context makes "feed it everything" the path of least resistance — and every unnecessary field a compliance exposure, a bias vector and a breach multiplier.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Data poisoning', 'Corrupting an AI system upstream by manipulating its training or reference data so it learns the attacker''s preferred behaviour. Typically discovered, if at all, long after the damage compounds.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Deepfake', 'AI-generated or manipulated content that convincingly depicts real people, places or events. Publishing one triggers disclosure duties under the AI Act, with narrow carve-outs for evidently artistic or satirical work.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Deployer', 'An organisation using an AI system under its own authority — as opposed to the provider who built it. Most SMEs are deployers, and deployer duties (instructions, oversight, input data, monitoring, logs) are where their obligations concentrate.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Disparate impact', 'A pattern in which a system''s outcomes differ substantially across groups sharing a protected characteristic, regardless of intent. Measured by comparing selection or approval rates — the number that turns fairness from assertion into evidence.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('DPIA', 'A Data Protection Impact Assessment: the structured, documented assessment required before processing likely to be high-risk to individuals — which automated decision-making about people almost always is. Done at the right moment, the cheapest design review your AI will get.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('DSIT', 'The UK''s Department for Science, Innovation and Technology — home of the government''s AI policy, the central AI risk function, and the guidance ecosystem (including the ATRS and assurance portfolio) this framework draws on.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Dual authorisation', 'The two-key discipline for drastic actions on consequential systems: suspension requires two authorised people, preventing both rogue shutdown and rogue hesitation. Standard practice for kill-switch design.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('DUAA', 'The Data (Use and Access) Act 2025: the UK statute that rebuilt the automated-decision rules around permission-plus-safeguards, created the recognised-legitimate-interests basis, and amended the UK GDPR. In force for ADM purposes since February 2026.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('EFRAG', 'The European Financial Reporting Advisory Group — author of the EU''s sustainability reporting standards, including the voluntary SME standard (VSME) this framework''s ESG domain is built around.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Equality Act 2010', 'The UK''s discrimination statute, protecting nine characteristics. It never mentions algorithms and does not need to: liability attaches to outcomes, and an AI system producing worse outcomes for a protected group exposes the organisation that deployed it.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Explainability', 'The capability to state, in plain language, why a system produced this output for this person — main factors, specific to the case, at a level the recipient can act on. Built at procurement or build time; nearly impossible to retrofit.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Four safeguards', 'The DUAA''s requirements for significant automated decisions: the person is informed, can make representations, can obtain human intervention, and can contest the outcome. Each must be operational — a working mechanism with an owner and records, not a paragraph in a policy.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('FRC', 'The Financial Reporting Council: regulator of UK corporate governance and author of the 2024 Code, whose Provision 29 declaration brings AI within the board''s material-controls attestation from the 2026 reporting cycle.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('FRIA', 'A Fundamental Rights Impact Assessment: the AI Act''s required assessment for high-risk systems deployed by public bodies and by banking or insurance entities in defined uses. Broader than a DPIA — dignity, non-discrimination, redress — and complementary to it, not a substitute.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('GHG Protocol', 'The standard method for corporate greenhouse-gas accounting, dividing emissions into Scopes 1, 2 and 3 with fifteen categories of value-chain emissions. The arithmetic underneath every serious sustainability disclosure.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Hallucination', 'A generative system producing confident, fluent output that is factually wrong. Tracked as a telemetry rate because it announces itself in metrics long before it announces itself in headlines.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Horizon scanning', 'A defined process — watchlist, cadence, change log, named owner — for tracking the regulatory instruments that can change your obligations, and converting movement into action. The alternative is discovering deadlines from headlines, usually late.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Human intervention', 'The DUAA safeguard entitling a person to have a human re-take an automated decision. The intervening human must meet the meaningful-involvement standard — competent, reasoning-sighted, authorised to reverse — or the intervention is ceremony.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('ICO', 'The Information Commissioner''s Office: the UK''s data-protection regulator, with powers including assessment notices and audits. Its guidance defines, among much else, what makes human involvement in automated decisions meaningful.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('IDTA', 'The UK''s International Data Transfer Addendum: the contractual mechanism (alongside the UK Extension to the Data Privacy Framework) that keeps personal-data transfers to other countries lawful.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Incident clocks', 'The AI Act''s serious-incident reporting deadlines: fifteen days generally, ten where a death is involved, two for widespread infringement or critical-infrastructure disruption. They start at awareness of the causal link — ready or not.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('ISO/IEC 42001', 'The international management-system standard for AI — the certifiable framework for how an organisation governs its AI estate, explicitly commended in UK guidance. One of the proportionate routes to independent assurance.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Kill-switch', 'The tested ability to stop an AI system quickly: defined triggers, authorised roles, dual authorisation, rollback and a business fallback. A governance control that has to be built and rehearsed, because it cannot be improvised on the day.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Lawful basis', 'The legal ground every processing of personal data must rest on — consent, contract, legal obligation, vital interests, public task or legitimate interests. AI deployments typically need a basis per purpose: training, operation and outputs.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Legitimate interests', 'The most flexible lawful basis: processing necessary for interests not overridden by the individual''s rights, evidenced by a documented balancing test. One blanket recital stretched across an AI system''s purposes is not an analysis; it is a hope.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Machine-readable marking', 'The AI Act''s requirement that synthetic content carry technical, detectable marking — layered metadata plus watermarking — not merely a visible label. A caption is a label; the duty asks for detectability that survives cropping, compression and paraphrase.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Maturity bands', 'The five levels of the 0–4 scale: Initial, Developing, Defined, Managed, Leading. Scores of 0–100 map to bands at thresholds of 20, 40, 60 and 80 — the same language across the assessment, telemetry and report.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Meaningful human involvement', 'The legal test deciding whether a decision escapes the solely-automated regime: the reviewing human must have the competence to understand the output, access to the system''s reasoning, and the authority to override it. Rubber-stamping fails it.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Model card', 'A structured record of what an AI system is for, what data trained it, how it performs across groups, and where it should not be used. Becoming the lingua franca of fairness and procurement evidence.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Model drift', 'The gradual divergence between what a model was trained on and the world it now operates in, degrading accuracy silently. One of the core telemetry measures, because drift announces itself in numbers before outcomes.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('NCSC', 'The UK''s National Cyber Security Centre, whose guidelines for secure AI system development set the design bar across the lifecycle — and anchor the government''s voluntary Code of Practice for the cyber security of AI.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Omnibus (Digital / Omnibus I)', 'The EU''s 2025–26 simplification packages: the Digital Omnibus adjusted AI Act timelines and SME accommodations; Omnibus I cut CSRD''s mandatory scope to 1,000 employees and created the protected-undertaking value-chain cap.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Parity band', 'The practitioner convention for disparate-impact testing: outcome ratios between groups within roughly 0.8 and 1.25 are treated as within tolerance; divergence beyond triggers investigation. The threshold matters less than defining it in advance.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('PECR', 'The UK''s Privacy and Electronic Communications Regulations: the rules on cookies, tracking and electronic marketing. Strictly necessary storage — like this product''s local answer storage — needs no consent banner; everything else does.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Prompt injection', 'Instructions smuggled into content an AI system processes, hijacking its behaviour from inside the data channel. A category error for perimeter security thinking, because the attack arrives as payload, not intrusion.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Protected characteristics', 'The nine grounds the Equality Act protects: age, disability, gender reassignment, marriage and civil partnership, pregnancy and maternity, race, religion or belief, sex, and sexual orientation. The map every AI use should be checked against.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Protected undertaking', 'An organisation with fewer than 1,000 employees, which may lawfully refuse value-chain data requests exceeding the voluntary SME standard. A right that protects nobody unless exercised.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Provider', 'The organisation that develops an AI system or has it developed and places it on the market. Providers carry the design-side duties — documentation, marking, energy disclosure — that deployers depend on downstream.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Provision 29', 'The UK Corporate Governance Code 2024 provision requiring boards to declare annually on the effectiveness of material internal controls — a boundary the FRC has said includes IT, cyber and AI. Attestation, not just monitoring, from the 2026 cycle.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Proxy variable', 'An innocuous-looking data field that statistically reconstructs a protected characteristic — postcode, school, surname, employment gaps. Deleting the labelled column achieves little while the proxies keep discriminating.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('RACI', 'A decision-rights map: who is Responsible, Accountable, Consulted and Informed for each system. For AI, the accountable name must survive the legal test — could this person genuinely override the system, and would they know when to?')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Recognised legitimate interests', 'The DUAA''s new lawful basis for defined public-interest purposes — with an explicit statutory bar: it cannot ground significant automated decisions. Reaching for it for ADM misreads the Act at the exact point the Act anticipated.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Red-teaming', 'Deliberate, authorised attack on your own systems to find what a real adversary would. For AI, the step that turns a threat model from hypothesis into tested control.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Ring (accountability)', 'One of the three circles of people around the telemetry measures — run it (daily users), steer it (rule-setters), check it (outside eyes) — each with its own review rhythm. Every measure is owned in exactly one ring.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Risk appetite', 'The board''s written statement of which AI uses it embraces, tolerates with controls, or refuses — with tolerances concrete enough to guide a real decision. Unwritten appetite is enforced by luck.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Risk tiers (AI Act)', 'The AI Act''s four-level classification: prohibited practices, high risk, limited risk (transparency duties), and minimal risk. Obligations attach to tier, and deployment context sets the tier — the same model can sit in different tiers in different uses.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('s172 (Companies Act)', 'The director''s duty to promote the company''s success with regard to stakeholder interests — tested procedurally, through what the minutes show was actually weighed. For AI adoption, the minute book is where the safe harbour is built.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Scope 1, 2 and 3', 'The GHG Protocol''s emission categories: Scope 1 is fuel you burn, Scope 2 is energy you buy, Scope 3 is everything in your value chain — usually estimated, not measured, and respectable when the method is stated.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Shadow AI', 'AI tools staff adopt without approval — personal subscriptions, free tiers, browser extensions — invisible to the register and busy processing whatever was pasted into them. The governed response is a better catalogue and a faster approval route, not a wider ban.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Significant decision', 'A decision producing a legal effect on a person or something similarly significant — a job refused, credit declined, an entitlement removed. One of the two tests deciding whether the DUAA''s automated-decision regime applies.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Solely automated', 'A decision made without meaningful human involvement. The word doing the work is "meaningful": a human who forwards what the system decided has not moved the decision out of scope — they have decorated it.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Special-category data', 'The most sensitive personal data: health, race, religion, sexual orientation, biometrics and their kin. Significant automated decisions based on it remain prohibited by default — and it enters pipelines through side doors like inference and bundled vendor features.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Subject access request', 'A person''s right to a copy of their personal data and information about how it is used. Where AI is involved, a complete response includes the algorithmic chapter — the decision-relevant information the safeguards regime already requires.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Telemetry', 'Continuous measurement of governance health: eleven measures with thresholds, owners and cadences, replacing point-in-time audits with a live register. The bridge from governed-on-paper to governed-in-fact.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Threshold', 'The pre-agreed line that turns a metric reading into a status — within, watch, or breach — and a breach into an escalation. Set from the board''s risk appetite, not discovered after the fact.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Transparency paradox', 'The structural bind in which deployers are legally responsible for explanations that their vendors'' opaque models make impossible to give. Resolved at procurement — documentation and reasoning access as conditions of purchase — or not at all.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Twin Transition', 'The EU''s framing that digital and green transformation should advance together rather than trade off. For AI: adopt deliberately, count the energy cost, and let efficiency weigh in vendor choices.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('UK Corporate Governance Code 2024', 'The FRC''s governance code for listed companies, applying from 2025 with the Provision 29 material-controls declaration from the 2026 reporting cycle. The instrument that moved AI oversight from good practice to board attestation.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Value chain', 'Everyone upstream and downstream of a company''s operations — suppliers included. Large companies'' sustainability duties reach their value chains, which is how reporting obligations arrive at SMEs by contract rather than statute.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('VSME', 'The Voluntary Sustainability Reporting Standard for SMEs, published by EFRAG: a Basic Module (B1–B11) and a Comprehensive Module (C1–C9). The standardised answer to the questionnaire flood — produced once, reused everywhere.')
  on conflict (term) do update set def = excluded.def, updated_at = now();
insert into glossary_terms (term, def) values ('Watermarking', 'Embedding robust, machine-detectable signals in AI-generated content so it can be identified as synthetic even after editing. One layer of the AI Act''s marking architecture, alongside secured metadata — with legacy systems'' deadline on 2 December 2026.')
  on conflict (term) do update set def = excluded.def, updated_at = now();

-- Guides ------------------------------------------------------------------
insert into guides (id, body) values ('how-scoring-works', '["Every one of the 64 assessment criteria is answered on a 0–4 scale, where each level is a described maturity state — not a feeling. Your answer for a criterion is the level whose description best matches your organisation today.","A domain''s score is the average of its answered criteria, converted to 0–100. Your overall score is the average of your domain scores, so each of the eight domains carries equal weight in version 1.0 of the framework.","Scores map to maturity bands at fixed thresholds: 0–19 Initial, 20–39 Developing, 40–59 Defined, 60–79 Managed, 80–100 Leading. The same bands appear everywhere — assessment, telemetry, report — so a number always means the same thing.","Unanswered criteria are never counted as zero. A domain you have not started shows no score at all, and your overall score reflects only what you have actually assessed."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('running-the-assessment', '["The assessment is 64 questions across eight domains, and everything autosaves as you go — leave and return whenever suits. The rail on the left shows each domain''s progress, and a green check appears when a domain''s eight criteria are complete.","Answer honestly rather than aspirationally: the framework rewards knowing where you are, and every criterion links to a briefing explaining what leading practice looks like and why it matters.","Many boards split the work by domain — the finance director takes ESG, the operations lead takes security — using the category rail to jump directly to their section. The picture assembles as each section completes.","When all 64 are answered, the completion banner offers your three next moves: download the board pack, copy a board summary, and assign owners to the telemetry measures."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('maturity-bands', '["Initial means the practice is absent — no awareness or action. Developing means it happens, but reactively and informally, dependent on individuals rather than process.","Defined means the practice is documented: a policy, a register, a procedure with a named owner. This is the band where most obligations start being defensible, because what is written down can be evidenced.","Managed means the documented practice is measured — adherence monitored, results tracked, deviations corrected. Leading means it is externally assured, benchmarked, and improving on evidence: the band where governance becomes a commercial asset.","The bands deliberately describe how work is done, not how much. A small organisation can be Leading; a large one can be Initial. Maturity is a property of discipline, not headcount."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('assigning-owners', '["Every telemetry measure should belong to one named person in one accountability ring. On the Telemetry page, each metric card carries an owner chip — click it to assign a name, a role and a ring.","The three rings carry different rhythms: Run it is the people using AI daily, watching the measures week by week. Steer it is senior management and the board, setting thresholds and acting on breaches. Check it is the outside eyes — your accountant, auditor or reviewer — confirming annually that the records reflect reality.","Assignments persist and flow through the product: the advisory report''s priority risks name the owner of each affected area, and the rings section shows how many measures each circle owns.","The rule that makes it work: if a number has no name, it isn''t governed — it''s just displayed. The warning above the register counts your unowned measures until they reach zero."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('reading-the-report', '["The report assembles itself from your assessment: an executive summary with your overall score and band, priority risk areas for domains scoring under 60, the full category breakdown with movement since your last snapshot, a peer benchmark, and a sequenced roadmap.","Priority areas name their weakest criteria — the specific questions dragging the score — and each links to the accountable owner you assigned in Telemetry, or tells you plainly that the area is unowned.","Download PDF produces a print-ready board pack; Share with board opens a pre-drafted email. Both carry only what you choose to send — nothing is transmitted to us.","The current report is a draft template: scores and structure are live, and the written narrative will be generated when the reporting phase completes. The draft badge stays until then."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('demo-data', '["Anything labelled Demo data is illustrative: the telemetry metric readings, the overview''s KPI figures, and the peer benchmark values. They show how the product behaves, not facts about your organisation.","Everything derived from your own assessment is real: your scores, bands, domain heatmap, history and report content. The two are never mixed without a label.","Live metric feeds replace the demo values when integrations arrive. Until then, treat demo numbers as furniture in a show home — accurate about the room, silent about your life."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('regulatory-countdown', '["The Telemetry page''s countdown tracks the regulatory deadlines that matter to AI-deploying organisations — currently Article 50''s transparency duties (2 August 2026) and the synthetic-content watermarking deadline for legacy systems (2 December 2026).","Each counter turns amber inside 30 days and red inside 7, and disappears once the date has passed. The values compute from today''s date every time you load the page.","The countdown is a prompt, not a compliance calendar: the briefings for criteria 4.1 and 4.2 explain what each deadline actually requires of you."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
insert into guides (id, body) values ('your-data', '["Everything you enter — answers, score history, owner names — is stored in your browser, on your device. It is not transmitted to us, and we cannot see it. Clearing your browser''s site data deletes it permanently.","This also means your data does not follow you between devices or browsers yet. Cloud accounts, with sign-in and per-organisation storage, are the next phase — and will arrive with an updated privacy policy before anything changes.","The full detail is in the Privacy policy and GDPR statement, linked in the footer. The short version: we practise the data minimisation our own briefings preach."]'::jsonb)
  on conflict (id) do update set body = excluded.body, updated_at = now();
